/* 令和7年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r07.committeeSessions.push(...[{"id":"r07-20250307-3","meetingId":"r07-c-budget","date":"2025年3月7日","dateIso":"2025-03-07","committee":"予算特別委員会","time":"午前 ９時３０分～午後 ５時１０分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を182件抜き出しています。","topics":[{"id":"topic-01","title":"令和７年度品川区一般会計予算","agenda":"令和７年度品川区一般会計予算","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問","question":"１８９ページ、新年賀詞交換会経費、同じく１８９ページ、坂井市区民交流ツアー、２０７ページ、荏原町安全安心ステーション運営経費についてお伺いします。初めに、１８９ページの新年賀詞交換会経費についてお伺いいたします。新年賀詞交換会の定義というものをお聞かせ願いたいと思います。","respondent":"勝亦総務課長","answer":"区では毎年、関わり合いの深い地域団体ですとか各種団体、官公署の方々をお招きいたしまして実施しています。新年の挨拶と日頃の感謝を伝えるとともに、親睦を兼ねて連携を深める機会として実施しています。","id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"コロナ禍のときには開催していなかった時期もあったかと考えています。令和５年度は、恐らく１,０００人ぐらいの方にご案内をしているかと思うのですけれども、令和５年度、令和６年度の出席人数を教えていただきたいと思います。","respondent":"勝亦総務課長","answer":"新年賀詞交換会ですが、例年２,０００人程度の方にご招待状を出しています。出席人数ですけれども、令和５年度が５４２人、それから、令和６年度が５６８人となっています。","id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問","question":"すみません、２,０００人ということで、失礼いたしました。それで、この２,０００人に対して、令和５年度が５４２人、今年度が５６８人という人数に対して、区としては、この出席人数についてはどのようにお考えになっておられますでしょうか。","respondent":"勝亦総務課長","answer":"コロナ禍前ですと、大体９００人程度、４０％から５０％の方のご出席をいただいていたところですけれども、直近２年間で５００人台ということで、３割を切る出席になっている状況です。出席者がやはりコロナ禍を経て減少しているという傾向と見てあります。","id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それで、地域の案内をしていただいている町会長をはじめ、何名かお話をお聞きしますと、やはり飲食があったほうがいいのではないかというお声も、一定数ですが、あるのは事実です。本当の軽食でいいと思うのですけれども、今後検討していただきたいという声が要望としてあるのですけれども、どのように考えておられるでしょうか。","respondent":"勝亦総務課長","answer":"そういった中で、公費の在り方ですとか、新しい生活習慣の中で、様々な価値観があります。よりよくコミュニケーションを取ることが目的だと考えていますが、具体的にどのようにこれを達成していくか、検討してまいりたいと考えております。","id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"同じく１８９ページ、坂井市区民交流ツアーについてお尋ねします。企画政策課の方も交えて、品川区と坂井市の関わりをお聞きいたしました。それで、「ハタチの龍馬」、坂井市のキャラクターと一緒に観光地を紹介ということで、今配信されているかと思いますけれども、こういった動画を含めて、来年度、具体的にどういうふうに坂井市と関わっていくのかというのをお尋ねさせていただきたいと思います。","respondent":"大森文化観光戦略課長","answer":"坂井市と連携したＰＲ動画作成ということで、次年度も作成する予定になっております。令和６年度については、坂井市との動画を２月に上げておりますので、そちらもご確認いただければというふうにＰＲします。","id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ来年度も、坂井市、そして、高知県を含めて、よりプッシュしていただいて、プロモーション活動をしていただきたいと思います。どうぞよろしくお願いいたします。続いて、２０７ページの荏原町安全安心ステーション運営経費についてお伺いいたします。初めに、荏原町安全安心ステーションについてのご説明をお願いいたします。","respondent":"河合生活安全担当課長","answer":"荏原町安全安心ステーションにつきましては、平成１９年、当時の駅前交番が閉鎖になることに伴いまして、地域住民の要望等により、住民で構成する荏原町安全安心推進員という方々、区で委嘱する形なのですけれども、推進員の方がそこに詰めていただく形で。","id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今のご説明のとおりでありますが、開設当初は１町会だけで協力者を募ってやっていた経緯があります。毎年更新のご案内が１１月に来るところですが、今もって案内が来ていないということで、協力者の方からどうなっているのだろうという声もあります。それで、昨日、その協力者に対して何か説明があったとお聞きしておりますけれども、その内容についてお知らせいただきたいと思います。","respondent":"河合生活安全担当課長","answer":"町会のほうでも、後進の方を推薦することが難しくなってきているというお声がありました。そういったことと、今猛暑日とか、推進員の方々の体の負担等もありますので、今後どうあるべきかということで検討いたしました。","id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ご説明のとおりであります。それで、今ご説明があったとおり、今、本当に高齢化が進んで、８０代の方々に協力をいただいている中で、７月と８月は今開設をしていない状況でありますが、やはり説明をもっと早くしていただきたかったというのがまず一つです。これについては、今後、１０月までということなのですが、どういうふうな使い方というか、どういう方向性でいるのかお知らせいただきたいと思います。","respondent":"河合生活安全担当課長","answer":"今のところ推進員の方々ともお話しして、恐らく９月末、上半期終了後というところで検討しているところですが、予算については年間で取っておりますけれども、廃止となったところで差額となるような形で考えております。","id":"exchange-008"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今後の、１０月以降の使途というのはこれからいろいろ検討されるかと思うのですけれども、荏原町近辺には喫煙所がございません。今後は、喫煙所を含めて、いろいろ検討はあるかと思うのですけれども、例えば、荏原町支え愛・ほっとステーションなどという手法もあるかと思いますので、併せて要望させていただいて終わりにしたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"おはようあります。１８３ページ、区施設営繕事務費から授乳室の安全対策、２０７ページ、住まいの防犯対策助成金、２２３ページ、戸籍住民関係事務費から伺います。区有施設の営繕事務費ですが、授乳室の安全対策ということで、防犯カメラ等の設置について求めてまいりました。そして、防犯カメラ、インターホンのみではなく、もう少しメニューを広げていただきたいと思いますが、見解を伺います。","respondent":"長尾施設整備課長、河合生活安全担当課長","answer":"区有施設の授乳室における防犯ブザーの設置状況について、まずご説明いたします。集合住宅につきましても、管理者・所有者等ではなく、世帯ごとで、オーナーから了承を得たところは認めるような形で検討していきたいと考えております。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"授乳室も着実に進んでいることが確認できました。そして、次に、戸籍住民関係事務費から婚姻届についてお伺いをいたします。書き方見本にあるように、夫側のチェックが既にあることで、夫の氏になることが当たり前のような印象を与えてしまうことがないように、夫側のチェックを外し、どちらかにチェックをとするように改定をしていただきたいと思いますが、見解を伺います。","respondent":"築山戸籍住民課長","answer":"婚姻届の記入例についてです。委員ご指摘の点を踏まえまして、記入例の見直しについて検討してまいります。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"早急にご検討をお願いをいたしまして、改訂を求めたいと思います。そして、ここに乗られなかった区長が何名かいらっしゃるかと思いますが、その方がどういうご判断だったのか、また、これは国へ求めることですけれども、本当に２３区、多く声を上げていただきたいと思いますし、森澤区長が主導してやっていらっしゃるこのことに対して、呼びかけも行っていただきたいと思いますが、いかがでしょうか。","respondent":"築山戸籍住民課長","answer":"今回申し入れした際に、品川区含めて１０区が賛同して国に申し入れを行ったところですが、そうでない区につきましては、それぞれの区のご判断かと認識をしています。今後の動きですが、国の動向を注視しながら、品川区としてできる施策について考えてまいりたいと思います。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問","question":"この質疑の中で、総務省から通達をされているということで、３つほど、これまでの質疑の中でデメリットがあるということを明確にご答弁をいただいておりますけれども、逆に、このデメリットが明確になったということで、そういうことをしっかりと当事者の方にご理解をいただきながら進めることができるのではないか、総務省の通達はあるにせよ。","respondent":"築山戸籍住民課長","answer":"ただ、やはり今回の件でいきますと、国から全国統一的な対応が求められるということで、先行自治体のほうに再考を求める通知が出ていることを踏まえますと、難しい状況かと考えております。","id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"やはり国のこの通達は大きいと思いますけれども、引き続き、品川区民でも求めている方が多くいらっしゃると思いますので、区でできることの対応をしっかりとご検討を続けていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"ひがし委員","kind":"質問","question":"私からは、１９５ページ、ジェンダー平等推進事業、そして、２２１ページの戸籍・住民基本台帳関係費について順不同でお伺いいたします。令和７年度１月のしながわＤＸの推進の進捗状況としては、手続き数から見たオンライン化カバー率は３９.３７％、申請件数から見たオンライン化カバー率は９１.４５％と、オンライン化を進めているところだと認識をしております。そこでお伺いいたします。","respondent":"築山戸籍住民課長","answer":"オンライン請求およびコンビニ請求等で対応は可能となっております。一方、法人請求、士業に対しては、現在、オンライン請求等の対応は行っておりません。住民票も同様です。","id":"exchange-015"},{"speaker":"ひがし委員","kind":"確認","question":"個人ではオンライン化が進んでおり、士業、法人については、まだオンライン化はできていないということが確認ができました。取扱い通数についてお伺いします。戸籍、また、住民票全体の総数と、士業、法人、業務上請求の件数、また、その割合、窓口で対応しているのが何割で、郵送請求が何割なのかというところも教えてください。","respondent":"築山戸籍住民課長","answer":"こちらも戸籍と住民票、それぞれ別で統計を取っておりますので、それぞれの回答になりますが、戸籍につきましては、全体が１１万１,７４９通、これは令和５年度の実績です。そのうち、法人の請求や士業による職務上請求が２万３,５０６件と、全体の２１％です。","id":"exchange-016"},{"speaker":"ひがし委員","kind":"質問・要望","question":"品川区はまだ進んでいないということで、こちらを進めてほしいといったご要望もいただいております。担当課は、額面確認、金融機関での手続など、多くの時間と手間をかけなくてはいけない。さらに、申請内容に不備があると業務の負担は増し、住民票だけでも１日１０件ほどの不備が発生、その都度申請者への電話確認が必要となり、電話がつながらなければ何度もかけ直すということになるそうです。","respondent":"築山戸籍住民課長","answer":"特に士業の場合ですと、それぞれの士業が所有する専門の用紙を用いる必要がありますので、紙での要件確認をする必要がありまして、そうしますと、その書類確認とキャッシュレス決済を結びつけるためのシステムが必要になってくるといったような課題がありまして。","id":"exchange-017"},{"speaker":"ひがし委員","kind":"質問・要望","question":"まだですかというお問合せを多分区としてもいただいていると思うのですが、進捗の状況が分かるということで、行政にとっても問合せの減少、また、作業の工数が減ることで負担の軽減につながるのかなと思いますので、今できていない現状だというのは分かりましたが、ぜひ前向きに検討を進めていただきたいなと思いますので、最後にそちらについてお答えください。","respondent":"築山戸籍住民課長","answer":"法人および士業の方の請求についてですけれども、先ほど言ったシステム構築の課題ですとか、企業が収益事業として行うことに対して、区がどこまで負担すべきかといった課題がありますので、ここはもう少し検討が必要だと考えております。","id":"exchange-018"},{"speaker":"ひがし委員","kind":"質問・要望","question":"品川区の職員の業務改革という視点でも、ぜひ前向きに進めていただきたいなと思います。その際、答弁については、記念品については、男女の婚姻を前提としたものを現在提供している、そして、撮影ブースについては、検討していくというようなお話がありましたが、現在の検討状況、進捗があれば教えてください。","respondent":"築山戸籍住民課長","answer":"戸籍届出事務は法定受託事務ですので、区としてできる裁量というのは限られているのですけれども、ただ、記念品につきましては、区の独自サービスですので、この辺りにつきましては、同性パートナーにも交付ができるよう検討を進めていきたいと考えております。","id":"exchange-019"},{"speaker":"ひがし委員","kind":"質問・要望","question":"品川区に新しく入ってきた方で、例えば、東京都のパートナーシップ宣誓制度の書類を持っている方々とかにもご案内をしてもらって、住民票を出すタイミングでそれを提示するとその記念品がもらえるみたいな形もぜひ前向きに検討していただきたいなと思うのですが、その点についていかがでしょうか。","respondent":"築山戸籍住民課長","answer":"今、記念品等のお渡しは、戸籍の届出の窓口で行っているところです。どういった方法でやるのかにつきましては、今後検討していきたいと思います。","id":"exchange-020"},{"speaker":"ひがし委員","kind":"質問","question":"ぜひ前向きに進むことを祈っております。次に、ジェンダー平等推進事業についてお伺いいたします。ＤＶ・カウンセリング・にじいろ相談、１,１００万円余ということで予算が計上されております。こちらについての予算の内訳についてお聞かせください。","respondent":"木村人権・ジェンダー平等推進課長","answer":"ＤＶ相談委託が１１０万５,０００円で、カウンセリング相談委託が２１２万５,２００円、ＳＮＳ相談委託が６１８万２,０００円、にじいろ相談が１２３万７,９００円、あと、そちらに関しての周知の経費として、４６万６,０００円を計上しております。","id":"exchange-021"},{"speaker":"ひがし委員","kind":"意見","question":"こちらのこころのカウンセリングＳＮＳ相談、このＳＮＳでの相談が始まり、また、にじいろ相談窓口も設置され、相談が進んでいるということで、うれしく思っております。このこころのカウンセリングＳＮＳ相談の実績がどのぐらいなのか、また、品川区では、品川区版あなたのいばしょチャット相談も始まっております。そちらとのすみ分け、違いについてもお聞かせください。","respondent":"木村人権・ジェンダー平等推進課長","answer":"委員お尋ねのところのこころのカウンセリングＳＮＳ相談に関してなのですけれども、こちらは令和６年７月から開始しておりまして、ＳＮＳ相談の件数が３０件になっております。うち、夜間が１１件です。","id":"exchange-022"},{"speaker":"ひがし委員","kind":"提案","question":"あなたのいばしょのほうは孤独・孤立に特化していて、こころのカウンセリングというところは幅広く相談を受けているということが確認ができました。ぜひ、こちらのチャット、ＳＮＳなどの相談というところは、若い世代も相談がしやすいかなということで、前回も提案させていただきましたので、ぜひ進めていただきたいなと考えています。そちらについても検討状況をお知らせください。","respondent":"木村人権・ジェンダー平等推進課長","answer":"にじいろ相談の相談員の人数ということなのですけれども、こちら委託をしておりまして、基本的に今、第２・第４土曜日の１０時から１６時半までやっておりまして、特に固定のメンバーでということではないのですが、その時間にいらしていただける方ということで対応しております。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"伺いますが、幾ら何でも同じテーマで年１０回も宿泊研修に職員を派遣したりとか、５種類の新聞・雑誌を個人に購入というのは行き過ぎで、税金の使い方としても理解が得られないですし、機関紙を発行する部落解放同盟など、特定の団体と癒着していると思われても仕方ない状況かと思いますが、いかがでしょうか。削減すべきと思いますけれども、いかがでしょうか。","respondent":"木村人権・ジェンダー平等推進課長","answer":"特に管理職に関しましては、常に意識をしていただかないといけないというところがありますので、こちらを購入しているという理由になっております。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"同じページの一番上の行です。人権・ジェンダー平等推進課職員給与費８人との記載ですが、この３行目の会計年度任用職員給与費１人、５１５万２,０００円とは、これは同和生活相談員だと事前に伺っております。相談の実態について幾つか伺いますが、この３６８件は、同じ方が複数回相談するたびに数える延べ相談数かと思いますけれども、まず、相談者の実人数は何人か伺いたいと思います。","respondent":"木村人権・ジェンダー平等推進課長","answer":"相談内容につきましては、様々ありまして、同和地区の出身者に関する内容になっておりますので、就職相談ですとか、健康の話、生活の話、もちろん差別の話に関して受けているところでございまして、実際の相談の内容としては、教育に関するものが１０３件。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"私たち、相談の実態が見えなかったもので、昨日、３月６日８時半、朝ですが、アポを取った上で、区長室分室を訪ねさせていただきました。分室は、現在、仮移転先の南大井にありまして、１・２階が月見橋の家で、３階は丸々区長室分室となっていました。このような事業がほかにあるでしょうか。相談の記録は取られているのかいないのか伺います。なぜ相談室を見せることができないのか伺いたいと思います。","respondent":"木村人権・ジェンダー平等推進課長","answer":"プライバシーの保護も含めて、詳細について公表することができないと考えております。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"極めて特殊だと思うのですね。昨日、アポなしで相談者が来ることもあるのでということだったので、私たちは８時半に伺ったのですね。伺ったら、この相談員の方の勤務というのは９時１５分から１６時までという、週５日ということでしたので、その時間、相談者もここへ来る心配はないのです。同和生活相談は、一般の人権相談に統合して、抜本的に解消するよう求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問・要望","question":"私からは、１９１ページ、特別職報酬等審議会経費について、２０９ページ、都市型観光プラン推進事業、そして、１９３ページ、都市ブランディング推進経費についてお伺いをいたします。特別職報酬等審議会についてなのですけれど、私、１期目から、会議録を公開してほしいということをずっと主張してきておりましたし、昨年の一般質問でも公開を求めさせていただきました。本当にどうもありがとうあります。","respondent":"勝亦総務課長","answer":"他の自治体等の公開の仕方は大きく参考にはしてございませんけれども、やはり委員の自由な発言を確保する観点から、それぞれの委員の発言については、特定できないように伏せさせていただいているものです。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問","question":"ほかにも、去年の一般質問でも、これに関連して質問させていただいたのが、区長の公約で、審議会とか協議会とかの会議のメンバーの女性比率を４０％以上にするという公約を掲げられていると思いますけれど、特別職報酬等審議会は、今現状、女性比率は４０％以上になっておりますでしょうか。特別職報酬等審議会以外でも、女性比率が４０％以上ということは達成されているのでしょうか。","respondent":"勝亦総務課長","answer":"特別職報酬等審議会の女性委員の比率ですけれども、現在２０％という状況です。他の会議体につきましては、把握している限りにおきましては、現状４０％を超えているものが４会議体あります。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"都市型観光プラン推進事業に移りますけれど、これも昨年の決算特別委員会で、リーズナブル・アコモデーション、ユニバーサルツーリズム、すなわち、障害者・高齢者の方々の観光に当たっての合理的配慮を都市型観光プランに記載して、今後の品川区における観光施策にぜひ反映していっていただきたいということをお願いをさせていただきましたけれども、現在の進捗状況はどうなっていますでしょうか。","respondent":"大森文化観光戦略課長","answer":"現在の状況としては、ＶＵＣＡ時代と言われている近年におきまして、短期・中期的に計画を立てていきまして、大きな計画です国や都の計画でしたり、品川区まちづくりマスタープラン、品川区水辺利活用推進計画など、そういったところも参考に。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"地域に根差したナイトタイム観光、ナイトタイム×食、光と水によるにぎわいなどがありますけれども、そうした今後東京都が力を入れていくナイトタイム観光に連動して、やはり品川区もそうした水辺とか、食とか、いろいろなそうした名所はありますので、ぜひナイトタイム観光という視点を今後の品川区の観光施策に反映していっていただきたいと思いますけれども、その点、いかがお考えでしょうか。","respondent":"大森文化観光戦略課長","answer":"そういったときには、大井町の東小路飲食店街など、夜を楽しめるコンテンツがありますので、こういったところを引き続きＰＲしまして、こちら、東京都の助成制度等が出た際には、関係団体に周知をしながら、一層のにぎわいを図ってまいりたいと考えています。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひ強力に進めていっていただきたいと思います。この予算特別委員会で審議する前に出てきてほしかったのですが、いきなり３月下旬に出てくることになろうかと思いますが、タイムスケジュール的に間に合わなかったのか、なぜこの予算特別委員会でそのロゴマークとかキャッチフレーズを発表できなかったのか、その辺りをお伺いします。","respondent":"與那嶺戦略広報課長","answer":"改めて、出来上がったデザインなどにつきましては、議会の皆様にもご説明をさせていただきたいと考えています。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問","question":"本当は議員の皆さんも意見がいろいろあったかと思うのですけれども、そういった現状でしたらもう仕方がないので、ロゴを楽しみにしております。そして、これは本当に大事なことですので、打ち出しも大事ですし、継続的に周知していくことも必要ですし、そして、適宜区民の皆さんの反応を確かめる必要があると思うのですけれども、その辺り、できた後のことはいかがお考えでしょうか。","respondent":"與那嶺戦略広報課長","answer":"初めに、しっかりと区民や社会の皆さんにお知らせをしていくというところはもちろんですし、区の広報媒体を使ってしっかり周知をしていく、また、区で関わる団体の方や企業の方にも使っていただくであるとか、そういった広がりを持った活用を考えてあります。","id":"exchange-033"},{"speaker":"せらく委員","kind":"質問","question":"１９５ページのＤＶ・カウンセリング・にじいろ相談について、相談事業の中から、主にＤＶ・カウンセリングについて質問していきます。こちらのＤＶについてなのですけれども、毎月４日程度相談の日程が設けられていますが、こちらの予約状況を伺いたいと思います。近年の傾向を教えてください。","respondent":"木村人権・ジェンダー平等推進課長","answer":"せらく委員からのご質問で、１つ目が、ＤＶ相談の状況だと思うのですけれども、こちら、ＤＶ相談件数、令和５年度は６６件になります。こちら、面接が４１件、電話が２５件です。","id":"exchange-034"},{"speaker":"せらく委員","kind":"質問","question":"学校教育では人権についても学んだりするのですけれども、大人は、知識があるかもしれないけれども、より意識していくべきだと思っています。モラハラ・ＤＶ加害者の自助団体ＧＡＤＨＡの方からお話を聞いてきました。その上でお伺いするのですけれども、モラハラ加害者の相談先について、品川区ではカウンセリング相談で受け付けられているのでしょうか。","respondent":"木村人権・ジェンダー平等推進課長","answer":"委員からのお尋ねは、モラルハラスメントの相談はどちらでということだと思うのですけれども、カウンセリング相談でも受けておりまして、こちらでやっているカウンセリング相談、法律相談に関しては、様々のモラルハラスメントから発生して、法律的な相談をしたいですとか。","id":"exchange-035"},{"speaker":"せらく委員","kind":"確認","question":"様々な相談をお受けしているということなのですけれども、加害者からの相談も受け付けているか、いま一度確認をさせてください。","respondent":"木村人権・ジェンダー平等推進課長","answer":"失礼いたしました。モラハラの加害者からの相談も受けているかということなのですけれども、加害者からの相談もお受けします。ただ、実際の件数としてはかなり少なくて、今のところ、近年では、昨年１件、ご自身からご相談があったという記録がありました。","id":"exchange-036"},{"speaker":"せらく委員","kind":"質問","question":"分かりました。港区では、ＮＰＯなどの団体が行う更生プログラムの初回面談費用を、上限１万円なのですけれども、助成していて、担当者からお話を伺ってきました。こちらについて見解を伺えればと思います。品川区でも助成をしてほしいということは申しませんが、区としても、更生の意思を持つ加害者に対してメッセージやコア相談支援は続けてほしいと考えています。","respondent":"木村人権・ジェンダー平等推進課長","answer":"今年度は、グルーミングについての講座を実施しましたところ、男性の方も含めて、かなり興味を持っていただいて、知識を増やしていただいたというところもありますし、フォーラムですとか、そういった形のところでも周知啓発に努めてまいります。","id":"exchange-037"},{"speaker":"せらく委員","kind":"質問・要望","question":"講座は、先週、ジェンダー平等推進センターで開催されたとお聞きしまして、男性に向けた内容だったということ、参加しやすい時間帯は夜の時間帯でしたり、あと、託児の工夫もされていらっしゃるとホームページで確認をいたしました。こちら、オンライン参加も可能ということで、後日の視聴ができるように、ぜひアーカイブ映像なども残していただけるといいと思うのですけれども、いかがでしょうか。","respondent":"木村人権・ジェンダー平等推進課長","answer":"今後もこういった形で取組を進めていくように考えておりますし、できるだけ時間帯についても、今年から夜の時間帯で固定をして実施しておりますが、引き続き考えていきたいと思います。","id":"exchange-038"},{"speaker":"横山委員","kind":"質問","question":"私からは、１８９ページ、グローバル人材育成海外派遣事業、２０９ページ、しながわツアー造成補助についてお伺いいたします。１点目に、グローバル人材育成海外派遣事業についてお伺いいたします。こちらの内容と、国際友好都市交流事業との違いについてもご説明ください。","respondent":"勝亦総務課長","answer":"今回グローバル人材育成の海外派遣につきましては、事業名のとおり、グローバルな社会に対応する人材を育成するという目的で設定しています。","id":"exchange-039"},{"speaker":"横山委員","kind":"質問","question":"そこで詳しくお伺いしてきたいのですけれども、なぜアントレプレナーシップ教育で、派遣先としてフィンランドを選定したのか、その理由と背景を教えてください。現地学生との交流とありますが、どのような学生と交流するのでしょうか。フィンランドの中学、高校の授業を受ける機会などはあるのでしょうか。ホームステイなのでしょうか。現地でのプログラムの詳細を教えてください。","respondent":"勝亦総務課長","answer":"事前のオリエンテーション、事前学習、報告会などについてですけれども、目的の設定ですとか振り返りは非常に重要です。事前の学習ですとか事後学習、報告会は実施する予定ですけれども、詳細なスケジュールについては、今後決定してまいります。","id":"exchange-040"},{"speaker":"横山委員","kind":"質問・要望","question":"ステークホルダーツーリズムとして、ターゲットが狭くてもお金を支払ってファンになってくれる方に向けて、ストーリー、歴史、バリュー、忍者、ニーズ、仕掛けとして、甲賀にある資源とあらゆるものを掛け合わせ、甲賀市に来ればあらゆる忍者体験ができる、忍者になれるまちを目指すべきビジョンとして、水口岡山城跡で忍夜討２０２４を開催したり。","respondent":"勝亦総務課長、大森文化観光戦略課長","answer":"本事業は、来年度実施させていただきたい新規の事業です。これを継続していく中で、他の団体ですとか、後の後輩の方々、そういった方への展開、継続的な実施を考えてまいります。周知については、観光協会等の力を借りて周知を図ってまいりたいと思います。","id":"exchange-041"},{"speaker":"えのした委員","kind":"質問","question":"私からは、２０１ページ、地域振興事業、２１５ページ、少年少女スポーツ普及事業についてお伺いします。少年少女スポーツ普及事業についてお伺いします。こちらの事業について、目的、概要などをお聞かせください。","respondent":"三井スポーツ推進課長","answer":"少年少女スポーツ普及事業の目的、概要ですが、こちらはスポーツに親しむきっかけづくりとなる教室やイベント、また、各種スポーツ大会の開催やスポーツ活動の場の開放などを通じまして、子どもたちがスポーツに親しむことや、体力の向上をはじめ。","id":"exchange-042"},{"speaker":"えのした委員","kind":"確認","question":"確認が取れました。各種スポーツ大会の開催やスポーツ活動の場の開放をしているということで、そちらの概要や参加者人数、利用者数をお知らせください。","respondent":"三井スポーツ推進課長","answer":"各種スポーツ大会になりますが、こちらは少年少女スポーツ団体と共催で実施している区長杯や教育長杯といった大会のことになりまして、種目は、野球、サッカー、バレーボール、バスケットボールの４種目となります。","id":"exchange-043"},{"speaker":"えのした委員","kind":"質問・要望","question":"令和６年度の事務事業評価シートを確認すると、指標の達成状況には、少年少女スポーツ開放は、熱中症対策により夏季期間の利用が減ったことで、令和５年度の利用者数は、令和４年度と比較してやや減少しているとあります。７月以降については、異常気象だと言えると評価しました。このような評価ですから、令和６年度も夏季期間の利用が減っていると予想されると考えます。そこでお伺いいたします。","respondent":"三井スポーツ推進課長","answer":"熱中症対策についてですが、こちらは少年少女スポーツ大会につきましては、区と各少年少女スポーツ連盟と共催で実施しているところになりますので、こちらは来年度からは、屋外で実施している区長杯や教育長杯といった大会の際に。","id":"exchange-044"},{"speaker":"えのした委員","kind":"確認","question":"確認が取れました。地域の少年少女スポーツの推進を進めていただけるよう、よろしくお願いいたします。次に、地域振興事業、地域課題の自主的解決支援についてお伺いします。この事業について、概要などをお聞かせください。","respondent":"宮澤地域活動課長","answer":"町会・自治会側の活動を行う上での様々な困りごとや課題を自主的に解決できるよう、町会・自治会の特性や活動実態に合わせまして、ご相談や助言などを行いながら伴走的に支援するもので、令和４年度からこれまで１６町会を支援してきたところです。","id":"exchange-045"},{"speaker":"えのした委員","kind":"質問・要望","question":"確認が取れました。品川区は、マンションなどの共同住宅に住む住民が８割を超えていると言います。防火、防災、防犯、また、子育て支援、高齢者支援として、地区委員、青少年委員、民生委員等々、これを丸々受け持って活動している団体がほかにあるでしょうか。マンションとの関係構築と併せて必要なのが、若い世代の方々を町会・自治会活動に巻き込んでいくということが必要と考えますが、いかがでしょうか。","respondent":"宮澤地域活動課長","answer":"ただいま委員がご指摘いただきましたとおり、マンションとの関係づくりという点につきましては、来年度、関係構築を実効的に進めるために、個別に区も入ってマンション等の管理組合であったり。","id":"exchange-046"},{"speaker":"えのした委員","kind":"意見","question":"様々ありがとうあります。本当にＩｎｓｔａｇｒａｍ、ＬＩＮＥなどＳＮＳでの情報発信は、若い世代に受け入れやすく、町会・自治会活動を知ってもらうには効果的と考えております。先ほどご紹介があったバーベキュー、面白いですよね。こういう取組など、各町会・自治会も創意工夫をしながら活動している。こういった活動に焦点を当て、各町会・自治会の活動の参考となるような取組があればお知らせください。","respondent":"宮澤地域活動課長","answer":"これ以外にも、品川区では、町会自治会連合会のホームページで、イベントの紹介について載せています。各地域センターでも、地域ニュースということで、地域の情報も発信しているというところで、引き続き情報発信には努めていきたいと考えています。","id":"exchange-047"},{"speaker":"えのした委員","kind":"質問・要望","question":"ただ、一方で、そういった好事例の取組が、同じ地区内でもなかなか情報共有されていない現状もまだある中、好事例の横展開について、やはり引き続き取り組んでいただきたいと思いますが、いかがでしょうか。先日、各町会・自治会宛てに、地域活動課から、東京都の地域の底力発展事業助成の案内のため冊子の配布がありました。こちらの概要などをお聞かせください。","respondent":"宮澤地域活動課長","answer":"地域の底力発展事業助成、これは東京都が実施しております町会・自治会向けの支援でございまして、町会・自治会が実施する地域の課題を解決するための取組を推進し、地域力を向上するための事業に対する助成です。","id":"exchange-048"},{"speaker":"えのした委員","kind":"質問","question":"現状、この事業に申請している町会・自治会は、どの程度ありますでしょうか。申請は毎年可能なのか、お知らせください。","respondent":"宮澤地域活動課長","answer":"令和５年度は９件、今年度につきましては、現在のところ１６件申請していると聞いております。申請自体は、毎年可能です。","id":"exchange-049"},{"speaker":"えのした委員","kind":"質問","question":"私、２月に地域活動課から町会への案内があった東京都主催の地域コミュニティ活動推進フォーラムに参加してきたのですけれども、そこでやはりそこの部課長とお話ししたところ、ぜひ品川区でも多く活用してほしいというお話を伺ったので、これ、区の施策、行政書士による運営事務サポートなどを活用できるかと思いますが、活用の実績などがありましたらお知らせください。","respondent":"宮澤地域活動課長","answer":"こちら、令和５年度５件、令和６年度は４件ということで、この東京都への申請に関しても受けているところです。","id":"exchange-050"},{"speaker":"つる委員","kind":"提案","question":"よろしくお願いします。平和であります。そうした中で、昨年の第４回定例会での一般質問、被爆ピアノの平和コンサートを提案させていただきまして、次年度事業の予算を盛り込んでいただいた。これは本当に感謝をしております。その最初のコンサート、実は私の大学のゼミの先輩と一緒にコンサートをやったのですけれども、その矢川さんからも伺って、不思議な縁だなというところも感じているところであります。","respondent":"勝亦総務課長","answer":"来年度実施を予定しています戦後８０年被爆ピアノの事業です。今後予算をお認めいただいてから、予定としましては、来年の１２月に実施したいと考えています。具体的なピアニストなどについては、これから検討してまいりたいと考えています。","id":"exchange-051"},{"speaker":"つる委員","kind":"質問・要望","question":"今年の１２月と受け取りましたけれども、周知も含めて、準備はとても大切かなと思います。このときには、２００５年にしながわ中央公園に埋めたタイムカプセルを開ける予定の年になろうかと思いますし、ぜひ、そのときには会場を小ホールからきゅりあんの大ホール、３００人から１,０００人を超える方が直接集えるような平和の式典にできるような、そうした拡充を求めていきたいなと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"中高生１０人程度を選定してまいりますが、審査の基準については、これから具体的に検討してまいりますが、中高生の地域や社会への関心ですとか、その課題意識、それから、意見のオリジナリティ、独自性、そのほか、表現力ですとか説得力など。","id":"exchange-052"},{"speaker":"つる委員","kind":"質問・要望","question":"パラリンピックのときには、コロナ禍であったので、残念ながら１００％の実施にはなかなかならなかったわけでありますけれども、今回、このデフリンピックについても、海外選手との交流について、品川区の取組をお伺いしたい。それから、例えば、もうレガシーとして、大会があった１１月を手話強化月間にするとか、この辺りも含めて、残りの時間を使っていただいてお答えをいただければと思います。","respondent":"三井スポーツ推進課長","answer":"委員からお話しいただいたハンマー投げについては、追加で会場ができたということもありまして、本当に区として応援が盛り上がるように、デフリンピック認知度１２０％以上プロジェクトを進めていきたいと考えています。","id":"exchange-053"},{"speaker":"おぎの委員","kind":"質問","question":"本日もよろしくお願いします。本日は、２１１ページ、生涯学習推進事業からシルバー大学、２２１ページ、戸籍・住民基本台帳関係費から振り仮名法制化対応についてお聞きいたします。シルバー大学についてお聞きします。次回の入学説明会は４月１８日となっていますが、近年の参加者数と応募状況についてお聞かせください。","respondent":"大森文化観光戦略課長","answer":"近年のシルバー大学の参加者ということで、まずふれあいコースといきいきコースという２種類のコースがあります。令和６年については、ふれあいコースが１３９人、いきいきコースが３１６人ということになってあります。","id":"exchange-054"},{"speaker":"おぎの委員","kind":"質問・要望","question":"ふれあいアカデミー、ふれあいコースが１３９名、これは１年目ですよね。これは３年制で、幅広いテーマを学び、２・３年目のいきいきコースに移行するという。発表会には、ぜひ多くの方に来てほしいと、シルバー大学の学生から要望が出ています。事務事業評価では評価がＣとなっておりますが、その理由と、検討している改善策等があれば、併せてお聞かせください。","respondent":"大森文化観光戦略課長","answer":"延べ数ということになります。すみませんでした。それから、シルバー大学の今後の体系をどう考えていくかというようなところの評価に対する区の考えといったところなのですけれども、始まってから様々な生涯学習というところで、講座や体験型の講座等を進めてきているところです。","id":"exchange-055"},{"speaker":"おぎの委員","kind":"質問・要望","question":"一部形骸化しているというのと、分かりづらいところをもう少し分かりやすくしていくということで、見直しする部分は見直ししていただきたいと思います。それで、講座の一般開放についてお聞きします。一般席の当日参加者には１回５００円ほどご負担いただいて、運営収入の一部にしたらどうか。他区にはないシルバー大学の存在をもっと広く知ってほしい。講座の一般開放について何かあればお聞かせください。","respondent":"大森文化観光戦略課長","answer":"広い部屋が取れている場合には、そういった一般の方を受け入れるというところも今後検討していくというところになるのかなとは思うのですけれども、一般の方を入れたことによって、また部屋が狭くなるというような、その辺りのバランスも年を通して考えていきながら。","id":"exchange-056"},{"speaker":"おぎの委員","kind":"質問・要望","question":"これ、今年大変な作業かなと思うのですが、しっかりやっていただきたいと思います。戸籍情報の取扱いは、厳密な運用をよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"吉田委員","kind":"質問","question":"私からは、１９３ページの広聴関連経費からホームページ等経費について伺います。それから、もう一つが、これ、企画費のどこかに入っているべきだし、入っていてほしいなと思って、法令のチェック機能について伺いたいと思います。最初に、ホームページ等経費について伺います。本当の更新日はいつなのでしょうか。ほかにもありますよね。これ、どこがチェックしているのか、まず伺いたいと思います。","respondent":"與那嶺戦略広報課長","answer":"こちらの更新につきましては、各所管部署でホームページの内容を更新しまして、作業をかけていくという形になるのですけれども、更新日の日付については、実際につくられたときというところで出てくるところもありますので。","id":"exchange-058"},{"speaker":"吉田委員","kind":"質問","question":"これ、ご覧になった区民の方からご指摘を受けたのです。ばかにするのではないよというか、こんなに早く最終補正案が固まっていると思えないし、ご覧になったのも、そろそろ予算審議だなということで、どんな感じかなというのでご覧になったら、昨年の末だったということです。これ、どうにかすべきなのではないですか。実務上こういうことですと済ませていいものなのでしょうか。伺いたいと思います。","respondent":"與那嶺戦略広報課長","answer":"ホームページのシステムの部分につきましては、こちら、運用事業者に確認しながら、改善できることはないか考えていきたいと思います。","id":"exchange-059"},{"speaker":"吉田委員","kind":"提案","question":"これはすごくいいなと思っていて、例えば、パブリックコメントに関して、品川区のホームページのトップページの分かりやすいところ、例えば、上段のところに、電子申請と同じように、パブリックコメントの募集などの一覧が掲載できると、区民の関心も呼んで、パブリックコメントへの投稿者といいますか、コメントする人が増えるのではないかと思いますし、私たちのような団体は。","respondent":"與那嶺戦略広報課長","answer":"そのほかに、ホームページであるとか、電子申請サービスなどで、例えば、一覧を載せるであるとか大きく出すといったところについては、周知の仕方の部分になるかと思いますので、こちらは今後我々のほうでも検討してまいりたいと思います。","id":"exchange-060"},{"speaker":"吉田委員","kind":"質問・要望","question":"なので、やはり区としては、きっとパブリックコメントはいっぱい出してほしいなと思っていらっしゃるに違いない。この件については、後でもし何か見解があれば伺いたいと思いますが、もう一つの質問に入ります。今回の予算書にもそれに該当する項目が見えないのですが、品川区の条例が法との整合性が取れているかなどのチェックの機能は、現在どこが担っているのか伺いたいと思います。","respondent":"勝亦総務課長","answer":"国の法令、それから、条例等との整合性等の管理です。総務課文書係におきまして、区の例規の管理、それから、法令等との整合性のチェックを行っているところです。","id":"exchange-061"},{"speaker":"吉田委員","kind":"質問","question":"文書の部門ですか。そういう機能を、今は文書係がちゃんと担っているということで、法律との整合性をもうちゃんと取っているということでよろしいのでしょうか。そうしたら、このたびの条例改正も、ここのそごがあるよということを、きちんとその所管に対して指摘をしたという理解でよろしいでしょうか。","respondent":"勝亦総務課長","answer":"今後も厳しくチェック等はしていきたいと考えています。今回の分につきましても、こちらのほうでも一定認識はございましたけれども、改正ができていなかったという部分です。申し訳ございません。","id":"exchange-062"},{"speaker":"吉田委員","kind":"質問","question":"総務部門がそういうのを担っているということをはっきりご答弁いただいたのはよかったと思いますが、では、認識していながらそのままというのは、どういうことなのでしょうか。他区では、ちゃんと明記して法務部門として持っているところもあると聞くのですが、品川区では、あくまで文書係ということなのでしょうか。一例かもしれないし、一例あったらあと１００例あるかもしれないわけですよね。","respondent":"勝亦総務課長","answer":"今後、そういった全体的な精査も常々しておりますけれども、引き続き、しっかりやっていきたいと考えています。","id":"exchange-063"},{"speaker":"吉田委員","kind":"質問","question":"それは戦略広報課が担うのでしょうか。どうしても市とか政令市とか、そこは独立性がすごくしっかりしているのですけれども、区部、２３区とかが特に、その辺の全体の統制が取れていないのではないかということで、いろいろな、強さが分からないので、指導と言っていいのか分かりませんが、そういう申出があったと聞いていますが、その辺についてはいかがでしょうか。","respondent":"勝亦総務課長","answer":"区民に分かりにくいという部分につきましては、基本的に全体を統括しているのは総務課文書係になります。当然、各所管のほうでも管理はしていますので、それは文書係でも各所管でも、お問合せがありましたら、そういったものについてはご対応していくという考え方です。","id":"exchange-064"},{"speaker":"吉田委員","kind":"質問","question":"やはり私としては、ちゃんとそれが分かるような名称を掲げた部署があったほうが、区民としても品川区への信頼性が高まるし、必要なのではないかなと思いますが、その辺のことについては、次年度急にというのは、もう３月ですので無理だと思いますけれども、検討はいただけないでしょうか。","respondent":"勝亦総務課長","answer":"法律、それから、条例、規則等のお問合せにつきましては、該当の所管、もしくは総務課文書係をご案内いただいて結構です。","id":"exchange-065"},{"speaker":"吉田委員","kind":"質問・要望","question":"各所管となると、専門性を高めていただきたいのは、各所管が所管している事業についての専門性を高めていただきたくて、全体としての文書の保存の方法とか、それから、法令とのそごとかは、総務部門や企画部門が担うべきではないかなと常々思っておりましたので、これからはそういうふうになるよということを生活者ネットワークとしてみんなに広報しても大丈夫ということですね。","respondent":"勝亦総務課長","answer":"そういった意味では、法律ですとか条例の状況について、所管にお問合せいただいてもしっかりと対応いたしますし、そこの部分につきましては、総務課文書係で全体を統括してまいります。","id":"exchange-066"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。だから、全体としては、ぜひ今後、文書係ということが確認できましたので、そのように私は区民の皆さんにお伝えしますけれども、区としても、明確に、ここが法令部門は担いますということを伝えることをしてほしいと思います。だから、こういう機会に全体を見直すということは考えられないのでしょうか。ぜひ、その点についてもお答えいただきたいと思います。","respondent":"勝亦総務課長","answer":"法令等と条例、規則について、漏れ等がないか全体の見直し、今後事務を進めていく中で、しっかり確認していきたいと思います。","id":"exchange-067"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。しっかりやっていただきたいと思います。さっき少しだけ触れてしまったので、東京都から、品川区の対応は違うということで、対応が修正されたという事例については、やはりそれもその所管の問題ではなくて、全体として受け止めるべきだと思います。ただ、これはやはり責任者としてのそこの長とか区が担うべき問題ではなかったのかなということを思います。その辺についていかがでしょう。","respondent":"勝亦総務課長","answer":"具体的な事案は別といたしまして、法律等々の専門的な解釈の部分、所管ともしっかり連携して進めていきたいと考えております。","id":"exchange-068"},{"speaker":"中塚委員","kind":"質問・要望","question":"１９５ページ、人権啓発事業より部落解放同盟の機関紙解放新聞の大量購入と管理職への無料配布の中止を求めて質問したいと思います。新年度予算ですが、今年１年間で部落解放同盟に支払う、解放新聞などの機関紙、その他雑誌も含めて、書籍代は総額で幾らになるのか伺います。その内訳について、例えば、解放新聞全国版では１年間で総額幾らか、総部数は何部か伺います。","respondent":"木村人権・ジェンダー平等推進課長","answer":"総部数に関しましては、１万６１７部数になります。","id":"exchange-069"},{"speaker":"中塚委員","kind":"質問","question":"相当の金額と部数が来ているということで、年間で３２７万円の新聞・書籍代を部落解放同盟に支払っているということです。そこで、事務事業評価を伺いたいと思います。効率化、効率化と述べておりますが、ならば、この１５０部の購入を事務事業評価ではどのように評価しているのか伺いたいと思います。私は費用対効果をちゃんと検証すべきだと思いますが、いかがでしょうか。","respondent":"木村人権・ジェンダー平等推進課長","answer":"管理職への研修というか、学びに関しましては、各区で考え方があると思いますので、そちらにつきましては、各区の考えというふうに理解します。事務事業評価につきましては、人権啓発事業という形で評価をしておりまして、これ単体で評価をしているものではございません。","id":"exchange-070"},{"speaker":"中塚委員","kind":"質問","question":"私は、こういう聖域扱いは間違っていると思います。森澤区長は、全６６９事業を対象に事務事業評価を行ったと述べておりますが、この２３区で最も多い解放新聞の異常な大量購入をどのように思っているのか、これが効果的だと、効率的だと本当に思っているのか伺いたいと思います。税金を使って解放新聞の大量購入、研修会の繰り返し、こうしたことはやめるべきだと思いますが、いかがでしょうか。","respondent":"木村人権・ジェンダー平等推進課長","answer":"こちら、人権課題につきましては、効率ですとか、そういうところで測る話ではないのかなと考えております。","id":"exchange-071"},{"speaker":"中塚委員","kind":"質問・要望","question":"皆さん、毎週毎週解放新聞が来ておりますけれども、本当に読んでいるのでしょうか。事業に活かしているのでしょうか。こんな無駄というか、茶番な事業はないなと指摘させていただきたいと思います。税金を原資に、部落解放同盟の運営のための収入に税金を環流させている、これが狙いではないのか伺いたいと思います。同和相談員も置く。部落解放同盟との利権に手を切るべきだと思いますが、いかがでしょうか。","respondent":"木村人権・ジェンダー平等推進課長","answer":"委員がおっしゃる内容として、先ほども効率ではないというふうにお伝えしましたけれども、人権問題、特に同和の差別につきましては、長く引き続き続いている問題になりますし、現在でも苦しんでいる方がいらっしゃるという内容になっておりますので、丁寧に。","id":"exchange-072"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区も認めるように、品川区内には、既に同和地区というものは、指定されたものはありません。その中で、毎週毎週新聞を配り続ける、雑誌を購入し続ける、年間で３２０万円、この利権に手を着けようとしない、見直さないとする、その姿勢は正さなければいけないと思います。ぜひとも利権と手を切って、区民のための品川区政を強く求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"澤田委員","kind":"質問","question":"本日は、２０７ページ、住まいの防犯対策助成金、１８１ページ、全庁共通プロジェクト推進経費の公有地活用検討等についてお伺いいたします。２０７ページ、住まいの防犯対策助成金についてです。区としては、戸建て、集合住宅を含めて、録画機能付きインターホンの設置状況を把握されているのでしょうか。併せて、これまでの実績をお聞かせください。","respondent":"河合生活安全担当課長","answer":"実績につきましては、これまで防犯カメラと録画機能付きインターホン、２種類をやってきておりますが、２月末現在で、防犯カメラが１５６件、インターホンが１６２件、計３１８件というところで、やはり録画機能付きインターホンの件数のほうが若干多いというところで。","id":"exchange-074"},{"speaker":"澤田委員","kind":"質問・要望","question":"この助成を高齢者の方に実際に紹介したところ、録画機能付きインターホンを設置されまして、誰が訪ねてきたのかをモニター越しに確認することができて大変心強いと、大変好評でした。本区では、住民の８割以上が集合住宅に住んでいる状況を踏まえますと、区全体の個人宅の防犯力アップに寄与する大事な施策であると思いますので、私からも、この集合住宅への拡充というのを要望したいと思います。","respondent":"河合生活安全担当課長","answer":"品目につきましても、委員の挙げていただいた品目、こういったところを上限額内で複数選択できるような形で、助成の方向で検討しています。","id":"exchange-075"},{"speaker":"澤田委員","kind":"質問・要望","question":"続きまして、１８１ページ、全庁共通プロジェクト推進経費の公有地活用検討についてお伺いします。公有地の活用として求められているものは、高齢者、障害者グループホームなどの公共施設のほか、サッカーや野球、バスケットボールなどのボール遊びができるスペースや、発災時には避難場所ともなる公園など、多様なニーズがあります。","respondent":"吉岡政策推進担当課長","answer":"引き続き、行政需要や地域ニーズを勘案し、必要な施設量のバランスを図りながら、既存の区有地を活用・検討するほか、その他の公有地や民有地につきましても、各所管と共に連携しながら、アンテナを高く張りまして、幅広く情報収集をいたしましたり、また。","id":"exchange-076"},{"speaker":"澤田委員","kind":"質問・要望","question":"公有地法の適用により税法上の優遇措置があることなど、土地の所有者の皆さんに広くお知らせして、土地を行政のほうに売っていただくというようなことに気づいていただけるようにしたりですとか、買取基準額を上げるなど、様々な方法でご検討もいただければと要望して、次に移ります。この好事例のような公共施設や土地の活用について、区としてはどのようにお考えでしょうか。","respondent":"吉岡政策推進担当課長","answer":"今後におきましても、行政需要や地域のニーズ、そして、費用対効果など、総合的に勘案しながら、区民サービスの向上につながるような検討をしてまいりたいと思います。","id":"exchange-077"},{"speaker":"澤田委員","kind":"意見","question":"櫻河岸まちなか観光案内所のようにコンパクトな土地でも有効活用していただいているので、これからも地域のお声を聞きながら、しっかりとご希望に添ったというか、調整しながら、このような土地の活用をしていただければと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-078"},{"speaker":"塚本委員","kind":"質問","question":"私からは、１９３ページの住民参加型デジタルプラットフォーム経費、それから、時間があれば、２０３ページの町会・自治会館建設等補助について伺っていきたいと思います。この業務実施、委託にしたということの理由というか、区で独自にこれを運営してやっていこうということにはならなかったのはなぜかというところでの質問なのですけれども、ご見解をお願いいたします。","respondent":"與那嶺戦略広報課長","answer":"こちら、区で独自でつくるという考えもあろうかとは思うのですけれども、こういった取組については、まず実際に提供している事業者などと協力しながら進めていくことが、費用対効果の面も含めて、よりよいだろうという考えで、今。","id":"exchange-079"},{"speaker":"塚本委員","kind":"確認","question":"費用対効果とか、いろいろ検討しながらということでございました。アンケートと同じような政策的な目的を、このデジタルツールを使って、より便利に低コストでやろうと、こういうぐらいの位置づけなのか、いや、そうではなくて、これはもっと進んだ形のものがあるのかというところでの確認をお願いいたします。","respondent":"與那嶺戦略広報課長","answer":"区でも、電子アンケートなどはこれまでも行ってきているのですけれども、そういったアンケートですと、いわゆる区から問いを投げかけて、それに対して回答していただくというところ、それはＱとＡみたいな形で、一方向の流れであったかなというふうに把握しています。","id":"exchange-080"},{"speaker":"塚本委員","kind":"質問","question":"分かりました。昨年の１０月に、参加しやすい防災訓練ということで、試行的に、この住民参加型デジタルプラットフォームを活用したと。区から様々な投稿や意見に対して、返信というのはどういうふうに考えているのか。都度都度返信してお答えを、区に対してこれはどうなのですかというようなことに対しての返信をしていくような運用を考えているのか。この辺をお願いしたいと思います。","respondent":"與那嶺戦略広報課長","answer":"もう一つ、区が返信をするかどうかというところの部分なのですけれども、来年度以降進めていくデジタルプラットフォームの具体的なサービスであるとか事業者というところはまだ決まっていないところではあるのですけれども、そういった選定の中で。","id":"exchange-081"},{"speaker":"塚本委員","kind":"提案","question":"そういった意味では、いろいろな民主主義をより発展するというか、補完、代表制民主主義、具体的に言うと、区議会だけでは足らざるところみたいなのを補っていこうというような意味でいくと、例えば、いろいろな審議会みたいなものを区が諮問してやっているようなもの、こういったものも、こういったデジタルプラットフォームを使って区民の意見等を集約していくといったようなこととか、あるいは。","respondent":"與那嶺戦略広報課長","answer":"今、仕組みを検討している最中と先ほど申し上げましたけれども、テーマについても、庁内各部署と調整しながら考えていきたいと思っていますので、その上で、今後の活用については考えていきたいと思います。","id":"exchange-082"},{"speaker":"やなぎさわ委員","kind":"質問","question":"本日は、２０３ページ、八潮地区まちづくり事業、２１９ページ、ふるさと納税、時間があれば、２１７ページのしながわシティランでお願いします。八潮ですけれども、昭和５８年にまち開きをしたということで、私も昭和５８年生まれということで、同級生の八潮についての質問です。八潮地区を含めた品川５地区の高齢化率を教えてください。","respondent":"今井八潮まちづくり担当課長","answer":"これに対しまして、八潮地区については３６.５％ということになっておりまして、全体、ほかのエリアと比べまして、１.５倍以上の高齢化率といったような状況です。","id":"exchange-083"},{"speaker":"やなぎさわ委員","kind":"質問","question":"倍近く高いということで。さらに言うと、八潮は７０代の方が最もボリュームゾーンになっておりまして、介護サービスを利用される方は今後も増えることが予想されます。そこで取り上げたいのは、車で送迎をするような介護サービスについてです。お聞きしたいのは、八潮にあるマンションの運営といいますか、経営主体、４つぐらいあると思うのですが、その種類と、自治会の数をお教えください。","respondent":"今井八潮まちづくり担当課長","answer":"そのほか、民間の賃貸住宅の運営事業者がいらっしゃいます。それとは別に、通常の分譲マンションもあるところです。自治会数なのですけれども、八潮全体で現在２８の自治会が存在するということで認識しております。","id":"exchange-084"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ということで、運営主体もいろいろあったり、自治会も多いということで。そこで起きているのが、車止めです。送迎車が入るときの車止めのルールがばらばらという問題なのです。それによって、介護事業者ですとか、サービス利用者に実は不便が生じているということです。こういった相談が区に寄せられているかとか、もしくは、把握しているかというのをお伺いしたいのですが、いかがでしょう。","respondent":"今井八潮まちづくり担当課長","answer":"まちづくり担当所管といたしましては、地域内に在宅サービスセンターなどもありますことから、こちらの施設長の方ですとか、現場の担当者の方と定期的に意見交換のようなものも実施させていただいているところです。","id":"exchange-085"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"これは要望です。次は、ふるさと納税なのですけれども、一昨日は私、石川柊太投手を取り上げさせていただきましたが、今日は、昨年予算特別委員会でも取り上げさせていただきました「さらば青春の光」についてです。昨年、「さらば青春の光」、調査研究しますというふうに一応お答えをいただいているのですけれども、その後お調べにはなっていただけたのでしょうか。","respondent":"吉野税務課長","answer":"返礼品なのですけれども、こちらは総務省の認可が必要になります。こちらの総務省の認可に当たりましては、いろいろな基準がありまして、全部で１９項目の基準があります。","id":"exchange-086"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"確認・検証をさらに進めていただきたいと思っています。一昨日の質疑で確認した、例えば、１万円の品物を返礼品として仕入れるとした場合は、我々の返礼品額は大体３万円になるということで、いわゆる区の歳入になる部分は３万円で、そのうちの半分、５割ルールの半分、１万５,０００円が、区のいわゆる収入というか、利益というような感じになると思うのです。","respondent":"吉野税務課長","answer":"先日も答弁させていただいたのですけれども、税務課内だけでいきますと、寄附金が５３５件、１,６１０万３,０００円になります。","id":"exchange-087"},{"speaker":"やなぎさわ委員","kind":"提案","question":"この「さらば青春の光」の、ザ・森東という個人事務所なのですが、年商が２０２２年度で３億７,０００万円。１０分の１だとしても、先ほどのお話にあった、今の現時点での区の歳入よりも大きい、１０分の１でも３,０００万円の歳入になるということで、これ、かなりビジネスチャンスとしては大きいと捉えておりますので、前回、私、体験型の提案をさせていただきました。","respondent":"吉野税務課長","answer":"先ほどもお伝えしましたが、内容等を条件に照らしまして確認して、研究してまいります。","id":"exchange-088"},{"speaker":"やなぎさわ委員","kind":"質問","question":"品川、そして、五反田を代表する人気芸人、人気ユーチューバーですので、ぜひ品川区としても何かしらうまく利用というか、お互いうまくコラボレーションできたらと思いますので、よろしくお願いいたします。今年度は７,０００万円余、そして、来年度は８,０００万円余計上しておりまして、区のビッグイベントです。第１回に先駆けて、ぜひ課長の意気込みを伺えればと思うのです。よろしくお願いします。","respondent":"三井スポーツ推進課長","answer":"まだあと２日ありますので、気を引き締めて、当日皆さんが楽しんで安全に大会が開催できるよう準備を進めてまいります。","id":"exchange-089"},{"speaker":"鈴木委員","kind":"質問・要望","question":"１９４ページの人事管理費から会計年度任用職員の待遇改善と、それから、保健師の増員を求めて質問をしたいと思います。そして、代表質問の中で、２３区がほとんど継続雇用、または、その方向で検討となっている中で、品川区も１年ごとの公募をやめて継続雇用にしてほしいということで求めたのに対して、国の動向を踏まえて検討するという答弁でした。もしそうであれば、時期についてもお聞かせください。","respondent":"宮尾人事課長","answer":"来月の４月１日は枠がもう固まっており、採用の関係もほぼ終盤を迎えているということで難しいのですが、できるだけ早い段階で制度の導入に向けて検討してまいりたいと考えています。","id":"exchange-090"},{"speaker":"鈴木委員","kind":"質問・要望","question":"特に５年以上働いているという方が３３％もいるにもかかわらず、昇給がない、経験加算もない、何年働いても新入職員と同じという状況では、私はやる気をそぐのではないかと思うのですが、その点についてもどう考えるか伺います。","respondent":"宮尾人事課長","answer":"経験加算という部分ですけれども、今、公募によらない再度の任用制度、こちらを検討していく中で、こちらについても、併せて、どういったことができるのかというところを考えてまいりたいと考えています。","id":"exchange-091"},{"speaker":"鈴木委員","kind":"質問","question":"ぜひこれは、経験加算、昇給については、できる方向で検討をお願いしたいと思います。ここのところを議会の中で質問してきたときには、基本的には、その職種に類似する常勤職員の給料表に適用して報酬額を定めているということでご答弁いただいているのです。保健師なのに、准看護師と同じ等級というのがおかしいのではないかと思うのですが、その点、いかがでしょうか。","respondent":"宮尾人事課長","answer":"今、保健師の報酬についてのお尋ねをいただきました。職の給与額の設定の考え方というのは、これまでにご説明を申し上げているとおりです。これからも、状況に応じて適宜しかるべき見直しは行ってまいりたいと考えております。","id":"exchange-092"},{"speaker":"石田（し）委員","kind":"質問","question":"よろしくお願いします。私からは、ちょっとページが見当たらないのですが、カスタマー・ハラスメント対策について、それと、１８２ページ、デジタル推進費についてお伺いをします。昨年の第３回定例会でも、私は一般質問で質問しましたが、東京都でカスタマー・ハラスメント防止条例が制定されて、来月から施行されます。","respondent":"石井コンプライアンス推進担当課長","answer":"東京都で、２月１７日、１８日で各業界団体のマニュアルが策定されたところです。そうしたものを受け、品川区としても、職員の対応要領について策定途中です。４月１日に発出できるように準備を進めているような段階です。","id":"exchange-093"},{"speaker":"石田（し）委員","kind":"質問","question":"ぜひ進めていただければと思います。その中で、品川区におけるハラスメントの防止等に関する基本方針というのがあります。ここにいわゆるカスタマー・ハラスメントは入っていない。だから、第３回定例会でも、この件については改正をするべきではないかと言ったのですが、答弁がありませんでしたので、その点について、どのように進めているのか教えてください。","respondent":"石井コンプライアンス推進担当課長","answer":"４月１日付で、東京都のカスタマー・ハラスメント防止条例が施行される予定です。それに向けて、品川区でも職員対応要領を定めることで、その職員対応要領の中で、カスタマー・ハラスメントについての定義は一定程度入れていくように考えております。","id":"exchange-094"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"了解です。二本立てでということなので、改正をしないということだと思うのですが、ぜひ、どちらにしても、東京都が条例を施行する中で、品川区としてもしっかりと対応していっていただきたいなと思いますので、これは要望でとどめておきます。よろしくお願いします。来年度の予算について、これまでと、そして、今回のこの予算案、どこが大きく違うのか、推進をしているのか、教えてください。","respondent":"西澤ＤＸ戦略担当課長","answer":"これまでの取組とどう違うかという話ですが、来年度、ＤＸ推進基本方針を改定しまして、これまで３か年ＤＸの取組をやってまいりました。","id":"exchange-095"},{"speaker":"石田（し）委員","kind":"質問","question":"要は、この技術に追いつけないで、１年が終わってしまって、次の年、どうしようかな、いっぱい新しいのが出てしまったけれど、どれをやるというふうになってしまうので、ここは、ＤＸ化に関しては、少し角度を変えて、もちろん行政だから年度でやらなければいけないというのも十分分かるのだけど、技術の革新の速さを鑑みると、やはりもう少し違う仕組みで、補正も含めてですが。","respondent":"西澤ＤＸ戦略担当課長","answer":"これはＭｉｃｒｏｓｏｆｔ３６５でも同じような状況になっております。","id":"exchange-096"},{"speaker":"石田（し）委員","kind":"提案","question":"常にアップデートできるようになっているということですが、本当に日々変化をしていくので、ぜひそこを捉えていただきながら、しっかりとやっていただきたいなと思うし、せっかく五反田バレーで、ＩＴの人たちと今一生懸命いろいろ区も進めようとしているわけですから、そこをどうやって活用していくかというのは、やはり大事だと思うのです。","respondent":"宮尾人事課長","answer":"今、新規職員の採用に関しては、当然ですが、一人ひとり面接を行った上で、その職員の人物像、能力等を見極めながら、職員一人ひとりに合った職場を考えているです。今後については、どのようなことがこの中でできているかというのは研究をしてまいりたいと考えています。","id":"exchange-097"},{"speaker":"石田（し）委員","kind":"提案","question":"ぜひこういったものを活用していただいて、よりよい品川区のサービス、そして、職員の皆さんの仕事軽減にぜひ取り組んでいただければと思いますので、提案にしますが、ぜひ研究をしていただければと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-098"},{"speaker":"こんの委員","kind":"質問・要望","question":"私らは、１９３ページ、住民参加型デジタルプラットフォーム、１９９ページ、庁舎跡地等活用検討、時間があれば、２０７ページ、生活安全活動費、住まいの防犯対策助成金、ページ順不同で質問してまいります。現在の検討の進捗状況をお知らせいただきたいのと、これまで検討してきて、基本的な活用の考え方というのが出てきたと思いますので、簡潔にご説明いただきたいと思います。","respondent":"泉広町事業調整担当課長","answer":"今後は、こういった活用のテーマ、生活環境の向上ですとか、憩いの充実、また、にぎわいの創出ですとか、様々幅広い視点がニーズとして把握されたところから、こういったところの位置づけに向けまして、今後具体の検討を進めていくというところになってあります。","id":"exchange-099"},{"speaker":"こんの委員","kind":"質問・要望","question":"ご説明ありがとうございました。そこで、日々の訓練が災害時に役立つように、消防団の訓練を常設した場所でできるように何とかならないかというこの要望に対して、この跡地活用というところでの声があるのですが、そうした声についての跡地活用で消防団、いわゆる災害時の実効性あるそうした訓練ができるようにとの声に対して、跡地活用、どのように考えますでしょうか。","respondent":"泉広町事業調整担当課長","answer":"今、消防団の活動場所というところのご提案がございまして、一定程度そういった重要な視点の一つに入っているところはありますから、そのような視点で今後段階的に検討を進めてまいりたいというところと、当該地につきましては、災害時に拠点となってくる新庁舎、また。","id":"exchange-100"},{"speaker":"こんの委員","kind":"提案","question":"そのように考えていてくださっていて大変にありがとうあります。次の質問に参ります。このプラットフォームにおいて、ぜひ、品川区の家賃が高い実態だとか、若者の生活事情や、品川区で住み続けたいのに住み続けられない要因だとか、何が若者の住宅に困難を擁しているのかということを把握していただきたい、このように提案をいたしました。事業開始からこれまでに４４人の若者の方にあっ旋をしてきた。","respondent":"與那嶺戦略広報課長","answer":"昨年実施した試行実施におきましても、３０代以下、若い世代の方からの回答が全体の４割程度を占めるというところで、若者世代の声を聞く手段としては非常に有効であるというところは区としても評価していますので、今委員おっしゃったテーマも含めまして。","id":"exchange-101"},{"speaker":"こんの委員","kind":"質問","question":"ぜひ、このデジタルプラットフォームの中で、若者の意見等々をお聞きしていただいて、若者の住宅支援というところを具体的に検討を進めていただくようお願いをいたしまして終わりとします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"こしば委員","kind":"質問","question":"よろしくお願いします。私からは、１８７ページ、非核平和都市品川宣言事業、時間が余りましたら、１８９ページ、地域住民と外国人との交流促進について聞いてまいります。今年は戦後８０年を迎えます。戦後８０年を迎えまして、品川区の平和に対する考えについて教えていただければと思います。","respondent":"勝亦総務課長","answer":"戦後８０年ということで、まず、品川区は、非核平和都市品川宣言に基づきまして、平和事業を実施しております。非核平和と恒久平和、そういったものの確立に向けて意識啓発を図っていきたいと考えています。","id":"exchange-103"},{"speaker":"こしば委員","kind":"質問","question":"私も、地域の大先輩の方々から様々な話をお聞きして、地域の歴史というのを対話の中から学ばせていただいております。戦後８０年ですので、実際に戦争を経験した方というのは、およそ８０代後半の方、実際に戦地に行って戦った方というのは、ほとんど１００歳を超えている状況です。この「平和の誓い」像について、つくられました経緯と、当時のつくられたことへの思いについて教えていただければと思います。","respondent":"勝亦総務課長","answer":"「平和の誓い」像です。「平和の誓い」像、まず大井町駅に一番大きいものが設置されてございまして、西大井の駅前、それから、五反田文化センターですとか、大崎ニューシティにも設置をさせていただいているところです。","id":"exchange-104"},{"speaker":"こしば委員","kind":"質問・要望","question":"私も、今回の質問がありましたので、意識的に見てはおりましたけれども、やはりどうしても通り過ぎてしまうようなところもありましたので、そういった意味では、ぜひ視認性の高いものに何か手を加えるとか、そういったものをぜひご検討していただきたいと思いますけれども、いかがでしょうか。","respondent":"勝亦総務課長","answer":"「平和の誓い」像です。この平和への願いを込めた像、多くの方に見ていただくことは大事なことだと考えています。そういった意味で、今あります説明文ですとか看板を、より目立つといいますか、視認性の高くなるように工夫していきたいと考えます。","id":"exchange-105"},{"speaker":"こしば委員","kind":"質問・要望","question":"例えば、台座の高さを上げるとか、その周りの整備にもまた視認性を高める工夫ができると思いますので、ぜひご検討していただきたいと思います。それを品川区のほうでも呼びかけてもらい、平和をいま一度考えるために、戦争経験のある高齢者からお話を聞く座談会のようなものをぜひ検討していただきたいと思いますが、もし取組を予定されておるのでしたら、ぜひその辺りも教えていただきたいと思います。","respondent":"勝亦総務課長","answer":"今後この声を伝えていく、聞いていくという部分ですけれども、まず今年度、非核平和都市品川宣言４０周年に当たりますので、平和の動画ということで、今、区内にお住まいの被爆二世の方のインタビューを撮らせていただいて、動画として公開していきたいと考えています。","id":"exchange-106"},{"speaker":"こしば委員","kind":"質問・要望","question":"特にこの広島のほうは、区内の各中学校から１人ずつだったと思いますけれども、広島に派遣していると聞いております。それぞれの子どもたちが見て、聞いて、そして、心に入ってくる気づきを自分の記憶にとどめるだけでなく、外に向かって発信をしていくこと、言葉をつなげていく役割があると考えますが、これらの事業を通じて派遣されました子どもたちの役割についてどのように考えているか教えてください。","respondent":"勝亦総務課長","answer":"こちらのほう、行って戻ってきたときに、それぞれ報告会をやってあります。今年度の非核平和都市品川宣言４０周年式典です。こちらのほう、３月２３日に実施いたしますけれども、この中でも、広島、長崎に参加した方たちのグループの発表、お話をするような場を設けてあります。","id":"exchange-107"},{"speaker":"こしば委員","kind":"提案","question":"恐らく１２月ですと、人権の啓発週間、そういった時期に重なってくるのかなとは思うのですけれども、多くの方が演奏に耳を傾けていただける機会もぜひ確保していただきたいと思いますが、また同時に、やはり先ほど視認性のところでも話をさせていただきましたが、例えば、大井町の駅前「平和の誓い」像の中心で、被爆ピアノの展示なども含めてご検討いただければと思いますが。","respondent":"勝亦総務課長","answer":"今のところ、場所は、やはり中心のきゅりあんで実施できたらと考えています。そういった中で、近隣にある大井町の「平和の誓い」像、そういったものと連携した形で、広く被爆ピアノ、それから、戦後８０年というものを区民の方に周知啓発していきたいと考えております。","id":"exchange-108"},{"speaker":"こしば委員","kind":"質問・要望","question":"子どもの頃だからこそ、物事に対して純粋に学ぶことは大変大切だとは思います。ただ、その一方で、批判的に物事を考えることができないゆえに、なかなか一方的に受け止めてしまうところもありますけれども、それをいろいろと切り口を変えて、平和教育というものをぜひ伝えていっていただきたいと思いますが、区のお考えについて教えていただければと思います。","respondent":"勝亦総務課長","answer":"そういった意味では、来年度予定しております被爆ピアノを使った形、音楽といったものを使った平和の伝え方ですとか、今年度から実施いたしました絵本を使ったワークショップですとか、子どもたちの健やかな成長を願ったひな人形をつくるワークショップ、そういった様々な形で。","id":"exchange-109"},{"speaker":"こしば委員","kind":"質問・要望","question":"ぜひ、いろいろな切り口で取り組んでいただきたいと思います。次に移ります。１８９ページの地域住民と外国人との交流促進です。国際理解の促進が盛り込まれておりますけれども、品川区が目指す外国人との共生社会の到達点、目標等がありましたら教えていただきたいと思います。","respondent":"勝亦総務課長","answer":"区内には１万７,０００人、史上最高と言えるぐらいの外国人の方にお住まいいただいております。異なる文化、それから、習慣を持つ外国人の方に地域にとけ込んでいただいて、地域住民と共生し、地域の担い手として一緒に共存していける社会を築いていきたいと考えております。","id":"exchange-110"},{"speaker":"田中委員","kind":"質問・要望","question":"１９７ページ、新庁舎関係と、２０３ページ、地域センター関連についてお伺いします。そういう観点からまずお伺いをしたいのですが、今ここの広町二丁目に現品川区役所があります。そのことが、より多くの区民が来る新庁舎においての、また一方で歴史的な視点を感じてもらえるようなスペースとして活かしていただきたいと考えていますが、今現在のお考えをお聞かせいただきたいと思います。","respondent":"山下新庁舎整備課長","answer":"ただいま委員からございましたとおり、現庁舎、広町二丁目１番３６号から、新庁舎の予定地につきましては、広町二丁目２番５号ということで、昨年の第１回定例会で位置の条例についてご議決を賜ったところです。","id":"exchange-111"},{"speaker":"田中委員","kind":"質問・要望","question":"もう一個お伺いしたいのは、町会側が、例えば、広町二丁目も権現町会の地域として共に活動していきたいという要望がもしあれば、私は、歴史的な経緯からも、広町二丁目は権現町会として編入する、そして、共に地域の皆様とまちづくりを進めていただきたいと思っているのですけれども、今現在のご見解をお聞かせいただきたいと思います。","respondent":"宮澤地域活動課長","answer":"町会に関しましても、面しているところも全て権現町会になってあります。権現町会からも、マンション等ができた暁には、勧誘・加入等を進めていきたいというふうにもお聞きしています。","id":"exchange-112"},{"speaker":"田中委員","kind":"質問・要望","question":"その背景には、システムの標準化ということも同時に行われておりますが、私は、さらにもう一歩進むと、今の年金とか、国民健康保険とか、それぞれ単体においてのシステムの標準化というのは行われておりますが、それこそまさにワンストップとして、業務としても、国民健康保険も年金も住基台帳も含めて、一か所で全てができるような、それはシステム上は問題ないと思うのですけれども、あとは、条例とか。","respondent":"山下新庁舎整備課長","answer":"ただいまございましたように、新庁舎におきましてワンストップの窓口の検討ということで、現在進めてあります。","id":"exchange-113"},{"speaker":"田中委員","kind":"質問・要望","question":"そういったものも含めて、全てワンストップで、地域センターなのかどうかも含め、ワンストップで行政サービスが受けられるような、新庁舎建設のこのタイミングこそ、地域センターも含めた取組が必要だと思いますが、いかがでしょうか。","respondent":"宮澤地域活動課長","answer":"新庁舎、ワンストップの窓口、ワーキンググループに私も参加しております。地域センターでできるところというところ、しっかり研究してまいります。","id":"exchange-114"},{"speaker":"松永委員","kind":"提案","question":"１８９ページの早川町との交流事業について伺います。品川区と早川町との最初のきっかけは、こちら、品川区が昭和６０年頃に自然の潤いということを求めて、平成２年４月１９日に「ふるさと交流協定」が結ばれたと伺っております。そこで伺いますが、協定が結ばれてから今年が３５周年という節目の年として、何か早川町と品川区でイベントまたは式典などは行われる予定はありますでしょうか。","respondent":"勝亦総務課長","answer":"今後とも引き続き交流を拡大していきたいと考えています。３５周年に当たって、より広くＰＲがどのようにできるか検討してまいりたいと思います。","id":"exchange-115"},{"speaker":"松永委員","kind":"質問","question":"３５周年という大切な節目の年でありますので、ぜひ何か行っていただければと思いますので、ご検討をお願いいたします。次に、早川町との交流バスツアーについて伺います。この目標値についてでありますが、どのように決定されたのでしょうか。この宿泊施設のヘルシー美里、ヴィラ雨畑、それぞれどういった割合になっているのか教えてください。","respondent":"勝亦総務課長","answer":"バスツアーにつきましては、年間８回行っているものでございまして、参加者数の最大から考えまして、そのような目標設定としています。宿泊施設ですけれども、現状、今年度は、昨年度を上回る、４００件以上のご利用をいただいております。","id":"exchange-116"},{"speaker":"松永委員","kind":"質問","question":"こうしたバスツアーについてでありますけれども、課題があると思います。なぜキャンセルが多いのかお知らせください。その中で、当日キャンセルというのはあるのでしょうか。何で伺うかというと、数週間前にやはりキャンセルしますということであれば、キャンセル待ちのようなシステムを導入していただければと思うのですが、もしこうした取組があればお知らせください。","respondent":"勝亦総務課長","answer":"そういった課題もありますので、今後、金曜日の設定を、予定の立てやすい土曜、日曜を中心に設定して、できるだけキャンセルの出ないように設定してまいりたいと考えております。","id":"exchange-117"},{"speaker":"松永委員","kind":"提案","question":"ぜひ、皆さんが参加できるような形にしていただきたいと考えています。これは提案になるのですけれども、実は近年、４０代から５０代を中心とした層が行っている新たな人生のパートナーを求めて、婚活を始めるケースが増加しているそうです。中でも、特に観光と出会いを融合させた婚活バスツアーが注目されており、こうしたツアーについて、品川区としての考えをお知らせください。","respondent":"勝亦総務課長","answer":"早川町のバスツアーは様々な切り口で実施しています。そういった意味では、いろいろな切り口はあろうかと思います。今後、ご意見を参考にさせていただければと存じます。","id":"exchange-118"},{"speaker":"松永委員","kind":"質問・要望","question":"そこで、「マウントしながわ」は、自然と親しむ活動の場、ふるさとの山等、様々ありますけれども、この中で、現在では１８歳以上の品川区民を対象に、早川町民による林業、植林、伐採などの指導、アドバイスを受け、森林保護育成、環境問題の啓発などを学んでおられるようですが、この２つの事業のみなのか伺いたいと思います。こうした観点からも、区としてのご意見を伺いたいと思います。","respondent":"勝亦総務課長","answer":"「マウントしながわ」については、里山の再生を中心に実施しています。今後、様々な林業ですとか、自然に親しむような活動は拡大していくことも大事だと考えています。様々な活用方法について、今後も検討していきたいと思います。","id":"exchange-119"},{"speaker":"松永委員","kind":"質問","question":"ぜひ、こうした活動を進めていただければと思います。お伺いするのを忘れていたのですが、先ほどのバスツアーの内容で、８回ということでありますが、こちらのピーク時の月、分かりましたら教えていただければと思います。","respondent":"勝亦総務課長","answer":"基本的には年間を通じまして実施しておりまして、各回とも約３０名から４０名の方にご参加いただいている状況です。","id":"exchange-120"},{"speaker":"松永委員","kind":"質問","question":"いい時期はあまりないということでよろしかったでしょうか。例えば、夏休みとか、そうしたところで例えば２回やるとか、そういったところはないかなということだったのですが。","respondent":"勝亦総務課長","answer":"様々な企画を実施しております。例えば、田植えですとか、ホタル、そういったそれぞれの企画に合った時期を設定しています。","id":"exchange-121"},{"speaker":"松永委員","kind":"質問","question":"ぜひ、よろしくお願いします。次に、進みます。２０７ページの特殊詐欺対策プロジェクトについて伺いたいと思います。侵入経路は、ほとんどが窓ガラスです。先ほどの質疑にもありましたけれども、ぜひともガラスフィルターの助成をお願いしたいのですが、いかがでしょうか。こうした非対面から対面式の犯罪が主流になりつつある中、本区として、どういった対策を進めていかれるのでしょうか。併せて伺います。","respondent":"河合生活安全担当課長","answer":"対面型の犯罪に対する予防としまして、今、高齢者宅とか、そういったところは、やはり犯罪に対する弱者ということになりますので、高齢者地域支援課の、いろいろな高齢者が集まる「脳力アップ元気教室」とか、そういったところにお邪魔して、個別的に。","id":"exchange-122"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、１８７ページの非核平和都市品川宣言事業に関わって、核兵器廃絶と城南空襲の日を設置することを求めて質問します。核廃絶についてです。核兵器禁止条約締約国会議がニューヨークの国連本部で、３日から本日７日まで行われています。区も、この被団協と同じ立場に立つべきだと思いますが、いかがでしょうか。国に核兵器禁止条約に参加を求めていただきたいと思いますけれども、いかがでしょうか。","respondent":"勝亦総務課長","answer":"非核平和都市品川宣言は、今年４０周年です。区といたしましては、核兵器の廃絶、それから、恒久平和の確立に向けた願いを込めまして、これを内外に発信しているものです。区では、この宣言に基づきまして、創意工夫を重ねて平和事業を継続的に実施をしております。","id":"exchange-123"},{"speaker":"のだて委員","kind":"質問","question":"国で議論すべきと言いますけれども、区の宣言には、いまだかつて開発された兵器で使われなかったものはないと。持てる国は即時に核兵器を捨てよと書かれております。これを見ると、被爆者の皆さんと同じ立場にあると思うのですけれども、いかがでしょうか。","respondent":"勝亦総務課長","answer":"非核平和都市品川宣言です。この宣言の理念に基づきまして、区は平和事業を実施いたしまして、恒久平和の確立について区民に意識啓発、周知を行っていくという考えです。","id":"exchange-124"},{"speaker":"のだて委員","kind":"質問・要望","question":"この宣言に核兵器は捨てよと書かれてあるわけですから、ぜひ、そこは区としても、日本原水爆被害者団体協議会と同じ立場で国に求めていただきたいと思います。先ほども質疑がありましたけれども、学生が品川区からも広島・長崎の平和記念式典に参加をしているということで、ぜひ区長も一緒に参加をしていただきたいと思いますけれども、いかがでしょうか。","respondent":"勝亦総務課長","answer":"日本原水爆被害者団体協議会の方につきましても、そういった思いに寄り添って、区として平和事業を進めてまいりたいと考えています。日本原水爆被害者団体協議会の方のお声を聞く機会を捉えまして、できるだけ考えていきたいと存じます。","id":"exchange-125"},{"speaker":"のだて委員","kind":"質問・要望","question":"４０周年で被爆二世の方の動画を流すということもぜひやっていただきたいと思いますし、そうした場面を、やはり非核平和都市宣言を行っている品川区が様々つくっていくということが、私は必要だと思います。特に荏原区は約７割が全焼しました。このＢ２９の機数ですとか、焼夷弾の数、３月１０日の空襲よりも大きな規模です。例えば、荏原区役所があった荏原文化センターに設置するのはいかがでしょうか。","respondent":"勝亦総務課長","answer":"こういった空襲、そういった被害を後世に伝えていくべく、引き続き周知を図ってまいりたいと考えています。","id":"exchange-126"},{"speaker":"のだて委員","kind":"質問・要望","question":"様々取り組んでいただいて、その中に、この城南空襲の碑を設置するということも実施をしていっていただきたいと思います。隣の港区には「山の手空襲」追悼碑というのもありますので、ぜひ品川区としても設置を検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-127"},{"speaker":"西本委員","kind":"確認","question":"私から、プレス発表のリークの件です。先日、歳入のときに動議をかけて、款別審査の中でということだったので、質問させていただきました。そのときの答弁の確認をまずさせてください。この区長のプレス発表前の報道記事掲載は、記者の努力であるということで、これは容認するということですか。お答えください。","respondent":"與那嶺戦略広報課長","answer":"一昨日の歳入の際にもご答弁差し上げたとおり、今回の報道の件につきましては、各メディアの記者の取材活動の中で行われているものと理解しています。","id":"exchange-128"},{"speaker":"西本委員","kind":"質問","question":"それは分かっています。それは当然ながら。ですから、今回の問題は、区長のプレス発表の前には公表しないでくださいというのを私たちは言われています。それで、公表されています。２月５日の朝刊に掲載があります。それに対して、今の見解だと、それはご自由にどうぞということでよろしいですね。","respondent":"柏原区長室長","answer":"こういった中での編集権とかでやっておりますので、その出てくる資料といいますか、情報というのは、どのタイミングで新聞なりメディアのほうに出るかというのは、そういった編集権がマスメディア側にありますので、我々がそれを止めることはできないといった認識であります。","id":"exchange-129"},{"speaker":"西本委員","kind":"質問","question":"答弁になっていません。訳分からないです。私が聞いているのは、容認しているのですねということです。外に漏れるということは、こういう状況で、２月５日の朝刊に出たということは皆さん分かっているわけです。その状況というのは、区として了解、容認でしょう。抑えられないということは、容認ということですよね。そういうことの理解でいいですかと先ほどから。明確に答えてください。容認でしょう。","respondent":"柏原区長室長","answer":"もう一度ご答弁しますけれども、先ほどのマスメディアの活動に対しては、我々は、出ることに対しては止められないというところがあります。容認云々というよりは、それが出たという事実を我々は認知したと、そういうところです。","id":"exchange-130"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、いつ記者の聴取があったかどうか、それはもちろん自由だと思います。でも、２月５日のプレス発表があるからということで、そこはルール、義務ではないのですか。千代田区のほうのどうのこうの言っていますが、そんなのはどうでもよくて、品川区の例で言うと、今まではなかったです。そのときに、２月５日まで待ってください。だから、みんな守ったではないですか。区長、どうなのですか。","respondent":"柏原区長室長","answer":"ただ、その内容であったりとか、お渡しのタイミングであったりとか、そういったところに関しては再考する部分はあるのではないかというのは、これまでの議論の中で感じているところですので、それについては再考・検討させていただきたいといったところです。","id":"exchange-131"},{"speaker":"西本委員","kind":"質問・要望","question":"少し返事が変わってきました。再考するという話が出てきました。はっきり言ったらいいのではないですか。そんな簡単なこと、子どもだってできることを、なぜ役所の人たちはできないのですか。しかも、トップクラスの人たちがなぜできないのですか。反省して、ちゃんと手続、それから、信頼関係を壊すようなことはしないようにしますと、なぜ言えないですか。要望書を出しますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-132"},{"speaker":"若林委員","kind":"質問","question":"２０９ページの観光資源整備事業について伺います。一方で、東京湾ダブルブリッジのクルーズ、そして、東京湾クルーズと、私どもはお台場クルーズの視察をさせていただいたわけですけれども、そのほかも含めて、様々、今年度は事業の本格的な展開をされてこられましたので、そういった今年度のトライしたこと等も含めて、一回総括をお聞きしたいと思います。","respondent":"大森文化観光戦略課長","answer":"運航コースに関しましては、年間を通した運航ということで、夏場は目黒川コースはフルオープンの船だったりするので、そういったところのコースを停止してみたりですとか、夏休みは平日の運航をしてみて人が集まるのかといったことで。","id":"exchange-133"},{"speaker":"若林委員","kind":"質問・要望","question":"そこで、改めて品川区の魅力の向上、また、価値を高めるという意味で、また、活性化という意味で、品川区もしっかりとこのネットワークづくり、また、他自治体、湾岸地域との桟橋同士でつないでいく広域的な連携で品川区の魅力を高める、そういった取組を今後、来年度以降取り組んでいただきたいと思いますけれども、お話を伺います。","respondent":"大森文化観光戦略課長","answer":"おかげさまで、こちらの便に関しましては大盛況で、２日間の平均で、１便当たり５０人のお客様に乗っていただくということができまして、場所が港区ということもあり、港区の観光部門の職員の方々にもご乗船いただいたというような形で。","id":"exchange-134"},{"speaker":"若林委員","kind":"質問・要望","question":"要望として、最後に、これは河川下水道課の予算になりますけれども、来年度、目黒川の護岸等のライトアップを行うと伺っております。変わって、時間はありませんけれども、１８１ページの行政評価（事務事業評価）について伺います。それを、例えば、Ａは幾らで、Ｂは幾らで、Ｃは幾ら、Ｄは幾らというぐらいのブレークダウンはできませんかという、そういう質問です。","respondent":"吉岡政策推進担当課長","answer":"削減額の事務事業評価の効果の部分が見えにくいです。今後、削減額の見せ方というところで、さらに今より見やすいようにというところは、引き続き検討していきたいと思います。どうぞよろしくお願いいたします。","id":"exchange-135"},{"speaker":"西村委員","kind":"提案","question":"１８９ページ、全国自治体との連携事業、２０５ページ、区民保養所経費、時間が許せば、１８１ページ、中高生リバースメンター事業を順不同で伺ってまいりたいと思います。これまでもいろいろと質問が出ておりますが、保養所について、品川荘と光林荘、また、新しい提案について伺ってまいりたいと思います。保養所を自前で持っている自治体の数と、校外学習施設を自前で持っている自治体の数を伺います。","respondent":"宮澤地域活動課長","answer":"区民保養所を保有している区につきましては、品川区を含めて９区、校外学習施設につきましては、１６区と聞いているところです。","id":"exchange-136"},{"speaker":"西村委員","kind":"質問","question":"自前で持っている９区、また、校外学習施設は２３区中１６区が持っているということですけれども、まず光林荘に関してなのですが、江戸川区も同じく日光市で校外学習施設を持っておりまして、廃止をしたのですけれども、方針を変更しまして、今後新たに校外学習施設として改築、使っていないときは区民が宿泊できる施設にと検討していると伺っております。","respondent":"宮澤地域活動課長","answer":"関東有数の観光地というところもありますが、施設として見ても、レクリエーションホールがありましたり、キャンプファイヤーができたり、飯ごう炊さんができる野外体験活動のできるフィールドを持っているというところが魅力です。","id":"exchange-137"},{"speaker":"西村委員","kind":"質問","question":"先ほどの例のように、２年連続で同じ場所に行くということは、教育的観点でも意義があると考えています。一度行ったことのある場所でも、季節が変われば風景が変わってきます。今おっしゃったように、安心できる環境のそろう校外学習施設ですので、私は必要だと考えております。一般利用に向けては課題が多くあると思いますが、この辺り、課としてはどのようにお考えでしょうか。","respondent":"宮澤地域活動課長","answer":"施設自体も駅から離れていたり、温泉施設ではないというところ等がありますので、一般のお客様にとってみると、魅力については低い部分はありますが、レクリエーションホール等があることから、団体利用というのには活用方法があると感じているところです。","id":"exchange-138"},{"speaker":"西村委員","kind":"質問","question":"より多くの区民が泊まりに来られるような検討も考えましたときに、団体利用を拡充していただくというようなお考えはあろうかと思うのですが、今どういう団体が使っているか、改めて伺えればと思います。","respondent":"宮澤地域活動課長","answer":"区内の団体の利用ですけれども、例えば、私立保育園の団体であったり、区内のスポーツ団体、バレーであったり、ドッジボールであったり、そういった団体、また、高齢者クラブなども利用しているというふうに伺っているところです。","id":"exchange-139"},{"speaker":"西村委員","kind":"質問・要望","question":"光林荘、土日の活用ですとか、紅葉の時期の活用などの質問も松本委員からあったところであります。団体利用の告知も積極的にしていただきたいと思いますので、よろしくお願いをしたいと思います。修繕の見込みですけれども、来年度は今後の方向性を検討していくとのことで、これまでかけてきた経費でしたり、今後考えられる懸念点を伺いたいと思います。","respondent":"宮澤地域活動課長","answer":"光林荘の修繕の見込みというお話です。これまでかけてきた経費というところでいきますと、現在の建物、平成６年に改築しておりまして、その際、２５億９,０００万円余の経費をかけているです。","id":"exchange-140"},{"speaker":"西村委員","kind":"質問・要望","question":"自前で持つということで、大きなお金もかかってまいりますけれども、ぜひ様々にご検討いただきたいと思います。予算特別委員会の質問の中でも、老朽化が進んでいると、抜本的に大規模改修をする時期に来ているとのご答弁がありました。現在、民間事業者に貸付けをしています。もし施設を手放すとするならば、他区の事例としてはどのような手法があるのかを伺います。","respondent":"宮澤地域活動課長","answer":"売却する際には、５年間、引き続き区民保養所として継続するというところで、保養所の運営経費の交付金という形であったり、区民が宿泊された際の宿泊補助を引き続き５年間するというような手法でやっていると聞いております。","id":"exchange-141"},{"speaker":"西村委員","kind":"質問・要望","question":"更地にして返さないといけないというようなことも様々あると思いますので、ぜひお考えいただきたいと思います。区が２０年ほど前に借上げでホテルと連携していたというお話を先輩方から伺ったことがありまして、時代が早かったのかなと思っているのですけれども、今、施設を持たずに民間のホテルと協定を結んでいる自治体が複数あります。この辺りも、ほかの他区の事例があればお知らせください。","respondent":"宮澤地域活動課長","answer":"民間の宿泊施設を、協定を締結する形で保養施設として位置づけるような形で行っているのも、９区あるというところは認識しております。","id":"exchange-142"},{"speaker":"西村委員","kind":"提案","question":"地方は関係人口を求めている中で、品川区と連携したいという地方の方々の声もたくさん届きます。それぐらい品川区が魅力があると思ってもらえているからだと思っています。そこで、ワーケーション促進のご提案を差し上げたいと思っています。このような視点も視野に入れながら、既に交流のある複数の自治体への宿泊助成の拡充と、ワーケーションの促進をご検討いただきたいと思いますが、お考えを伺います。","respondent":"勝亦総務課長","answer":"こうした住民同士のつながりを広げることのできる取組については、ぜひ進めてまいりたいと考えています。坂井市の実施されているワーケーション事業の推進ですとか、宿泊助成なども、今後先方様のお考えを伺いながら、相談してまいりたいと考えております。","id":"exchange-143"},{"speaker":"西村委員","kind":"質問・要望","question":"コロナ禍で毎日会社に行かなくていい働き方が増えました。最後に、中高生リバースメンター事業ですけれども、先ほども質問にありましたが、私も大変楽しみにしておりまして、公平性や多様性をどのように担保するのか、参考にされた取組があればお聞かせください。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"特に多様な意見から提言がされている点が参考になりまして、令和５年度はＬＧＢＴＱの当事者から、教員向けのそうしたＬＧＢＴＱを啓発するための講演会の実施という提言がありましたし、今年度につきましては、不登校当事者、通信制の高校に通う高校生から。","id":"exchange-144"},{"speaker":"西村委員","kind":"質問","question":"私立でしたり、都立高校、本当に区内中様々な子どもたちに声をかけていただけるということで、お願いをしたいと思います。事業の目的としまして、主権者教育的なリバースメンターとしての取組になるのか、それとも、全ての子どもの声をというところの包摂した事業として捉えておられるのかを最後に伺えればと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"一方で、多くの子どもたちの声を聞くという観点につきましては、こども基本法にのっとりまして、子ども未来部や教育委員会事務局の取組と連携して進めていきたいと考えているところです。","id":"exchange-145"},{"speaker":"高橋（し）委員","kind":"確認","question":"１９４ページ、人事管理費および１９７ページ、職員健康管理費について、それから、１８２ページ、デジタル推進費をお尋ねします。毎年１２月に品川区人事行政の運営等の状況についてが公表され、ホームページにも載っています。令和６年度版の公表とともに、令和２年度版から確認できるようになって、大変公平性、透明性の確保に値していると思います。それに基づく職員の健康管理についてお伺いします。","respondent":"宮尾人事課長","answer":"今、委員からお話のありました公表の部分、令和５年度の１年間に病気休職を取得した職員が７７名、うち精神疾患によるものが６８名です。おおむね９割ほどの職員が、休職のうちの精神疾患が理由というものです。","id":"exchange-146"},{"speaker":"高橋（し）委員","kind":"質問","question":"職員というのは、ものではないですけれども、本当に人として区の財産です。このような休職する方が多い、今お話があったように、大体６０人を超えて、今７７人、もうすぐ８０人ということですから。１０年前は、病気休職の方は４９人しかいらっしゃらなかったのです。お答えできる範囲で結構ですから、ご病気だったのか、それとも、そのほかの何かの原因だったのかということをお尋ねします。","respondent":"宮尾人事課長","answer":"今の死亡退職ですけれども、理由は様々あります。今お話がありましたように、病気で亡くなった職員もおります。理由は様々あります。","id":"exchange-147"},{"speaker":"高橋（し）委員","kind":"質問","question":"発表しているのが５区しかないのですけれども、その５区の中でも多いほうなのですね。ですから、職員の方々のメンタルの部分は、大変厳しい状態の方々がいらっしゃるのではないかと思います。令和６年度について、今度は分限処分を受けた休職の方が何人で、そういったメンタル、精神疾患の方は何人かということをお尋ねします。","respondent":"宮尾人事課長","answer":"令和６年度に休職を取った職員の数ですけれども、令和６年度は、すみません、今すぐに数字が出ないのですが、傾向としては、大体近年同様の数値と認識をしております。","id":"exchange-148"},{"speaker":"高橋（し）委員","kind":"質問","question":"職員の分限に関する条例に基づいてこのようなことが行われているのですが、心身の故障の場合、年次有給休暇がなくなったとか、不利益な身分上の変動をもたらす処分を受けることとなる、そういう経緯が一般的にどのような状況なのか、差し支えのない範囲でお尋ねします。それから、もう一つ、病状が回復して、職場に復帰なさった場合、どのような配慮が行われているかをお伺いします。","respondent":"宮尾人事課長","answer":"職員が長期の休みに入って復帰されるまでの間には、まず必ず産業医との面談を義務づけております。それから、いきなりフルで働ける者もおりますが、大半の者は、まずならし勤務という、１００％にいきなりではなくて、徐々に慣らしていくというようなことを必ずやっております。","id":"exchange-149"},{"speaker":"高橋（し）委員","kind":"質問","question":"そんな中で、一つ特筆すべきは、年代別構成は、２０代、３０代が、休職の年齢の平均を初めて上回ったというようなことがあります。この２０代、３０代が休職のパーセンテージを上回ったということがあるのですけれども、品川区の場合はどのような状況でしょうか。それはどのような原因によるものか、そして、区として、どのような、先ほどあったような配慮というか、フォローをしていくのかお尋ねします。","respondent":"宮尾人事課長","answer":"特に今、新規採用をすごく多く採っている中で、職員同士のつながり、そういうものがますます大事になってくるというのを痛感しております。こういった職員同士のつながりといいますか、そういうものを強められるような、そういう取組が我々は求められていると認識をしております。","id":"exchange-150"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"病気休職者、先ほど令和５年度で７７人、今年もそれに近いということですので、特に精神疾患の方を一人でも減らすということを目標にして、職員の方々が心も身体も健康に過ごせるように、職員の方々のウェルビーイング、それが実現できるようにご尽力いただきたいという思いで質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-151"},{"speaker":"松本委員","kind":"質問","question":"私からは、１８１ページ、しながわＳＤＧｓ共創推進プラットフォーム等運営経費、１８９ページ、早川町との交流事業、２０５ページ、区民保養所経費について伺います。お願いしたいと思います。","respondent":"宮澤地域活動課長","answer":"光林荘の稼働の関係です。今年度４月から１月末までで見ますと、３０６日ありますが、このうち、利用が全くない日というのは２０１日になります。学校が利用しているのは８４日、団体が利用しているのは２０日という形になっています。","id":"exchange-152"},{"speaker":"松本委員","kind":"提案","question":"１月までで２００日ということなので、２月・３月合わせるとさらに増えるということで、やはり年間の半分どころではないというところで、稼働していないというのが現実なのだと思います。なので、区としても、ぜひ教育委員会に対して、一回ゼロベースで校外学習、どういう在り方があるのかというのを検討していただくように要請していただきたいと思いますが、いかがでしょうか。","respondent":"宮澤地域活動課長","answer":"光林荘、品川荘も含めてになります。区民保養所という形の今後の方向性について検討していく中では、教育委員会にも入っていただき、区長部局含めて、しっかりと検討していきたいと考えております。","id":"exchange-153"},{"speaker":"松本委員","kind":"提案","question":"もう一つの品川荘の話ですけれども、先ほど西村委員から連携している自治体の話が出ていて、これ、第１会派と方向性が同じだったのは、すごくうれしくてですね。そこで、まず最初に、今回しながわシティラボの中でも、課題解決型ではなく実証実験提案型でマチルダというのは出てきたと思うのですけれども、この実証実験提案型の趣旨・目的について改めて伺えればと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"現状といたしまして、区民ニーズが多様化する中で、社会や地域の課題は複雑化していて、行政だけで解決するのは難しい時代を迎えております。そのため、企業等の持つ技術やノウハウを活用しまして、産学官の連携により課題の解決を目指すことを目的とするものです。","id":"exchange-154"},{"speaker":"松本委員","kind":"提案","question":"そこで、区内事業者との関係、商店街などとの関係というのが出てきているので、これは、今も産官学という話はあったかと思いますが、例えば、商店街とか個人事業主が提案から排除されているわけではないというふうに伺ってよろしいでしょうか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"提案していただく事業者なのですけれども、当然、民間企業、ＮＰＯ等の団体、それから、大学、研究機関、それから、個人事業主の方も、皆様ご提案いただく要件を満たしているということになります。","id":"exchange-155"},{"speaker":"松本委員","kind":"提案","question":"そうすると、いろいろな人が提案できるというのが、この実証実験提案型ということになるかと思います。一方で、デメリットもあるかと思うのですが、区内事業者に提案者を限ってしまった場合のデメリットを伺えればと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"課題解決のスピードが遅れたり、あるいは、もう課題解決ができないような状況になりまして、ひいては区民サービスの向上につながらなくなるということが考えられるかと思います。","id":"exchange-156"},{"speaker":"松本委員","kind":"提案","question":"ここで多分同じ区民のニーズとか区民の利益と考えたときに、同じ区民でも多分対立は生じ得ると思うのです。アイデアを出すのが事業者です。今回のマチルダの件も、アイデアだけ例えばマチルダに出させて、あとは区内事業者がやりますと言ったら、もう誰も提案しなくなる。ぜひここは積極的にやっていただいて、いろいろな方が提案をしていただきたいと思うのですが、いかがでしょうか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"ただ、委員がおっしゃられたような個人事業主などについては、周知を徹底してまいりたいと考えております。","id":"exchange-157"},{"speaker":"藤原委員","kind":"質問","question":"２２３ページ、臨海斎場運営負担金。どうしてもこれは聞きたかったのでお伺いしますが、火葬されたご遺骨から金、銀、プラチナが出てきて、これが１年間で結構な額になると聞いたのです。私は初めてこういう質問をするのですけれども、それは事実ですか。","respondent":"築山戸籍住民課長","answer":"金、銀、プラチナ、パラジウムが有価物として出ますが、これを売却すると、ある程度の金額となっております。","id":"exchange-158"},{"speaker":"藤原委員","kind":"質問","question":"その売却したお金は、どこにどう行ってしまうのですか。","respondent":"築山戸籍住民課長","answer":"臨海斎場の場合ですと、火葬にかかる経費との相殺をしておりますので、委託料と相殺をするような形となっております。","id":"exchange-159"},{"speaker":"藤原委員","kind":"質問・要望","question":"そうすると、１年に出る金、銀、プラチナ等で、料金が少し安くなっているということですよね。年間どのぐらい出るかということを教えていただきたいのと、例えば臨海斎場で、葬家さんが、今回亡くなった火葬する方は、歯の中に山ほど金歯が入っていますと。だから、その金歯だけは返してくださいと言えば、それで話は通るのですか。","respondent":"築山戸籍住民課長","answer":"年間です。現在金の価格が高騰しておりますので、状況は変わっているかと思いますけれども、私が臨海斎場から聞いた時点では、年間１,０００万円程度というところでございました。２点目のご質問です。","id":"exchange-160"},{"speaker":"藤原委員","kind":"質問","question":"四苦八苦という言葉があります。その最初の四苦、４つの苦は、生老病死です。つまり、老病死、その最初の苦は、生きること、生まれてきたことが生です。つまり、生を持った者は必ず、本当に悲しく残念だけど亡くなるという宿命、これは誰もいち抜けたということは言えないわけです。ですから、ほかの地域と比べても、東京ではなくて、自治体に比べても、火葬料というのは安価ですよね。いかがですか。","respondent":"築山戸籍住民課長","answer":"臨海斎場の火葬料の設定の方針ですけれども、これは適正な価格ということで、実際に火葬にかかる経費から割り出して、実費分をご負担いただくという考えで行っているところです。","id":"exchange-161"},{"speaker":"藤原委員","kind":"質問・要望","question":"高いと言っているのではないのです。だけど、誰でも火葬するのだから、この部分に対しては、ほかの自治体では、無料もしくは物すごく安価だから、品川区もぜひしていただきたい。よろしくお願いします。そして、次が、１９３ページ、しながわ百景普及啓発事業、伺います。１つだけ確認です。しながわ百景というのは、品川区が認め推薦する１００個のすばらしい地域の風景を推薦しているわけですよね。","respondent":"與那嶺戦略広報課長","answer":"委員ご質問の西大井駅にあります百景の看板ですけれども、名称を「西大井駅とその周辺」と銘打っておりまして、西大井駅前のロータリー、喫煙所の横に設置しています。","id":"exchange-162"},{"speaker":"藤原委員","kind":"質問","question":"百景です。そして、１８７ページ、しながわ平和の花壇。だったら、駅の前の横断歩道を渡った右側につくるのが一番目につくではないですか。喫煙所は交番の前に持っていけばいいではないですか。移転してしまえばいいではないですか。これは詳しいことは土木費でまた聞いていきますが、もうこれ、西大井のことを考えたら、抜本的に変えていかないといけないと思うのですけれども、いかがでしょうか。","respondent":"河合生活安全担当課長、勝亦総務課長","answer":"苦情の数からして、今、工事に着工しましたけれども、現在はパーテーションの設置工事が始まりました。やはりあの場所でないと、喫煙者の方々が入り切れない状況がありますので、ここはまずそれで対応したいと考えております。西大井の平和の花壇ですけれども、関係所管と調整いたしまして、現在、再々整備といいますか、リフレッシュに着手しています。水やりに関する問題につきましては、周辺の施設、関係課と協議を進めてまいりたいと考えております。","id":"exchange-163"},{"speaker":"藤原委員","kind":"質問・要望","question":"駅前のある意味観光です。駅を出たときに、あのロータリー、何というのか。すばらしいです。すばらしくなった。煙に意思はないから、受動喫煙も含めて、パーテーションをつくっても、煙が真上にずっと行ってくれるというのは分からないではないですか。この７月の条例は、しっかりこうやっているというのを、生活安全担当課長に見ていただいて、確認していっていただきたいと思います。いかがでしょうか。","respondent":"河合生活安全担当課長","answer":"条例改正、施行が７月というところで、私の任期を含めてというところで、今質問があったと思うのですけれども。任期は３月末で、立場は変わりますけれども、私は携わった者ですので、状況を確認しながら、後任の者といろいろ話し合っていきたいと考えております。","id":"exchange-164"},{"speaker":"藤原委員","kind":"質問・要望","question":"急にそんな３月３１日とか言われると、何か切なくなります。今まで区民委員会でも、本当に真剣な質問、答弁していただきました。そうですよね。もし警視庁へ戻られても、私は、この品川区でいろいろしていただいたことを、ぜひ今度は東京都民のために活かしていっていただきたいと思うのです。その辺について、もう常任委員会はありませんから、私に対しての最後の答弁をしていただければ幸いです。","respondent":"河合生活安全担当課長","answer":"私も派遣元で、基礎自治体と連携、連携などと机上でやっていたのですけれども、実際こちらに来て、基礎自治体のほうでできることとできないこと、しっかり勉強させていただきました。","id":"exchange-165"},{"speaker":"藤原委員","kind":"質問・要望","question":"生活安全担当課長、品川区のことを忘れないでください。ぜひ、この７月を過ぎたとき、どうなったかというのを見ていただきたいと思います。それと、さっき西側のことを言いましたけれども、観光の立場として、西口改札口があったほうがいいと思いますか。","respondent":"大森文化観光戦略課長","answer":"西大井駅前の、まず今の目の前の環境がよくなるということは、西大井駅の元からの移動幅の多い複数路線が乗り入れているといったところも鑑みて、ポテンシャルが高いものと考えています。","id":"exchange-166"},{"speaker":"大倉委員","kind":"質問","question":"よろしくお願いします。２０３ページ、区民まつり経費、２１７ページ、区民スポーツ大会を先に伺えればと思います。両イベントなのですが、以前も伺いましたが、この間の物価高騰、エネルギー高騰の中で、費用についてはどのようになっていますでしょうか。教えていただければと思います。","respondent":"宮澤地域活動課長、三井スポーツ推進課長","answer":"区民まつりです。区民まつり、各１３地区の地域センター管内ごとに開催しているところで、実施計画に基づきまして補助をしています。区民スポーツ大会ですが、こちらは競技によっていろいろ変わっていますが、主に個人は３００円から５００円、団体は１,５００円から３,０００円等で実施をしているところになります。","id":"exchange-167"},{"speaker":"大倉委員","kind":"質問・要望","question":"地域のふれあいおよび連帯意識が向上し、明るく豊かなまちづくりとコミュニティの醸成が期待できるというところで、工夫してやられているというところではあるのだろうと思いますが、ぜひ増額も含めて検討していただいて、区民の方がより満足できるような区民まつりにしていっていただきたいと思いますが、いかがでしょうか。","respondent":"宮澤地域活動課長、三井スポーツ推進課長","answer":"そういった実行委員会の中で、どういうやり方をしていくかというのは、しっかり聞いていて、必要な部分というところは今後検討していきたいです。失礼いたしました。運営のほうということで、区民スポーツ大会は、スポーツ協会と共催で実施しているところで、区は２,２００万円ほど分担金を予算で計上しているところになります。","id":"exchange-168"},{"speaker":"大倉委員","kind":"質問・要望","question":"そのまま引き続き、２５ページの地域スポーツ等推進経費に関連するのですが、区民大会ではないですが、代表質問でもしましたけれど、知的障害者の運動体験の場の提供というところで、品川区でも障害者水泳教室、フライングディスク教室、ｆｕｎｒｕｎ＆ｗａｌｋ、ユニバーサルフェスタ、障害者スポーツチャレンジデーなどがあるのですが。","respondent":"三井スポーツ推進課長","answer":"委員がお話しいただいたとおり、やはり成果の発表の場というのはとても重要だと考えております。障害者フライングディスク教室も、こちら年３回実施しておりまして、延べ４０名の方にご参加いただいております。","id":"exchange-169"},{"speaker":"大倉委員","kind":"質問","question":"今、フライングディスクのほうは、小学生以上の知的障害者と関心のある方ということで、知的障害者の方の人数なのかなと思うのですが、障害者水泳大会のほうは、いろいろな方が参加できるというところでは、今言っていただいた数は、知的障害者の方が参加した数ということでいいでしょうか。","respondent":"三井スポーツ推進課長","answer":"すみません、正確な数字までは把握できていないですが、主に知的障害者の方だと聞いております。","id":"exchange-170"},{"speaker":"大倉委員","kind":"質問","question":"そうすると、障害者水泳大会やフライングディスク教室で発表も含めてやっているというところではあると思いますが、この間も聞きましたが、スペシャルオリンピックスでも知的障害者が参加できる種目は、３つの競技しか今ないというところで言うと、残念ながら、これも２つの競技しかないのかなというところで、何か一緒に皆さん、障害がある方もない方も含めてでも全然構わないと思いますし。","respondent":"三井スポーツ推進課長","answer":"今も、例では出さなかったのですが、年２回ほど、ユニバーサルスポーツフェスタというものもやっておりまして、こちらのほうは、特に知的障害の方に限ってはいないのですが、障害の有無にかかわらず参加しやすいイベントとなっておりまして。","id":"exchange-171"},{"speaker":"大倉委員","kind":"意見","question":"実際、この間、大井町のイトーヨーカドーの上で、知的障害者の方がやっているサッカーの教室を会派で視察してまいりましたが、子どもたちが非常に楽しそうに参加して、ボールを蹴ってシュートを決めてということもやっていましたので、例えば、そういったスポーツ団体と連携して、やる場所がないという課題もあって、なかなかそういう情報も取れないということだったので、ぜひ、そういった発信とかも含めて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-172"},{"speaker":"あくつ委員","kind":"提案","question":"令和８年度にかけて事業者選定に入るスケジュールになっているので、私ども会派としても大変関心があり、改めて、提案を含めて確認をしてまいりたいと思います。そこで、お伺いしたいのですけれども、区として、この施設整備において、コンセプトの中心に図書館を置いたのはなぜなのか教えてください。２３区において、同様の図書館中心の複合機能施設があるのか教えてください。","respondent":"吉岡政策推進担当課長","answer":"２点ご質問をいただきました。なぜ図書館なのかですけれども、こちら、昨年度跡地活用方針策定委員会というものを設立いたしました。その中で、まず大きな施設のコンセプトといたしまして、多様な人々が集い、学び、助け合い、心と体の健康を育む交流拠点。","id":"exchange-173"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１０年前の決算特別委員会の総括質疑で、次のように伺いました。そして、期間を２年残しての指定管理者の交代という結果となりました。そして、最も大事なことは、品川区として、二度と利用者を絶対に悲しませることのないような、サウンディング調査を含め、区の意向が１２０％事前に伝わるような事業者選定と、指定されたＳＰＣとその後の十分な協議を行っていけるのかどうか、ここで確認をさせてください。","respondent":"吉岡政策推進担当課長","answer":"旧荏原第四中学校の整備・運営手法につきましては、委員からもご案内がございましたＰＦＩ方式のうちＢＴＯ方式を採用する方向で検討を進めているところです。","id":"exchange-174"},{"speaker":"あくつ委員","kind":"確認","question":"全庁共通プロジェクトということで、区としても相当力を入れているのは分かっていますけれども、ぜひ、今の言葉、今のご答弁、また、これも確認をしていきたいと思います。次に、施設のデザインについて伺います。今はもう実施設計が終わりそうですけれども。まだ想定ができないというのであれば、何階以上、何階以下という想定でも分かると、イメージがわかないので、そこについてご教授ください。","respondent":"吉岡政策推進担当課長","answer":"サイズ感というようなご質問かと思いますけれども、こちらは従来方式と違いまして、今回ＰＦＩ方式を採用するというところで、民間からの提案を意識してというところで、ある程度情報を落として、ある程度民間のアイデアを採用していくというところで。","id":"exchange-175"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２０１６年に日本建築学会賞を取っていますけれども、それなりに力を入れて、お金をかけてやっています。はっきり言って、デザインを失敗したら、今回のこの複合施設の大きな成否に関わっているというところで私は感じているのですが、そこについて、品川区はＳＰＣに裁量を大きく持たせる、分かるのですけれども、品川区としても譲れないコンセプトというものが今あれば教えてください。","respondent":"吉岡政策推進担当課長","answer":"当然、デザイン性にも凝りたいところですけれども、これにつきましては、費用対効果といいますか、コストのところに跳ね返るような部分もありますので、しっかりと検討しながら、より皆様からも愛されるような施設、魅力的な施設をつくっていきたいと考えています。","id":"exchange-176"},{"speaker":"あくつ委員","kind":"質問","question":"図書館のページが、この中において１ページ半しかないのです。図書館中心というところで、ほかのところはかなり特色を持ってやっています。７万冊以上という、非常に少ない、ゆたか図書館と同等のレベルの蔵書数が今書いてあるのですけれども、これで本当に足りるのかと。図書館としての特色について、何かここに書いていないものがあるのであれば、今考えているものを教えてください。","respondent":"吉岡政策推進担当課長","answer":"そういった中では、広くスペースを取って、本を借りる人も借りない人も少しおしゃべりをしながら交流できるようなスペースもあって、そういった新しい図書館を目指しています。","id":"exchange-177"},{"speaker":"まつざわ委員","kind":"質問","question":"私からは、１８９ページの全国自治体との連携事業、市町村交流事業、２０７ページ、特殊詐欺対策プロジェクト経費についてお聞きします。先ほど早川町との協定締結から３５年というお話もありました。こういう交流事業は、お互いの地域に相乗効果があると思いますが、長くこういう事業を続けてきた区として、メリットやデメリットを教えてください。","respondent":"勝亦総務課長","answer":"自治体との連携・交流につきましては、早川町、山北町、福井県坂井市、高知県等と協定を締結して、連携・交流を行っております。昨日もお話が出ましたけれども、未来のご近所、飯田市とも交流等々、今後検討しています。","id":"exchange-178"},{"speaker":"まつざわ委員","kind":"意見","question":"市町村交流は、そういったいろいろな文化の交流、地域の交流があるということが分かりました。こういうのは、例えば、交流の中で、学校同士がつながってもいいのかなというのが１点。例えば、クラウドファンディングを活用して、区民・市民が参加できる支援の仕組み、そういったものを構築するような長期的な交流プログラムを策定していくのも一つと考えますが、それぞれにご見解をお聞かせください。","respondent":"勝亦総務課長","answer":"具体的には、従前ですと、学校などでオンラインなどを活用した交流ですとか授業をした実績等もありますので、こういった方法については推進していきたいと考えております。寄附を含めて、様々な角度で、それぞれの住民が参加できるような仕組みを考えてまいりたいと思います。","id":"exchange-179"},{"speaker":"まつざわ委員","kind":"提案","question":"坂井市はお祭りが相当盛んだとお聞きしました。だったら、こっちがお神輿を持っていくというのもすばらしい事業だと思うので、そういうのも提案したいと思います。なので、こういった交流事業については、助成額をやはりもっと引き上げて、例えば、坂井市、そしてまた高知県、今までないところにもしっかり助成することが、交流のさらなる拡大につながると考えますが、ご見解をお願いします。","respondent":"勝亦総務課長","answer":"そういった中で、現在も早川町ですとか山北町との間で宿泊助成、区民割引等々は行っているところですが、今後さらなる交流の拡充につながるように、対象ですとか宿泊助成の在り方について、また。","id":"exchange-180"},{"speaker":"まつざわ委員","kind":"意見","question":"そういうことが、さらなる交流制度に反映できるものだと考えますが、ご見解をお聞かせください。","respondent":"勝亦総務課長","answer":"そういった中で、地域の企業や団体の交流についても活発に展開されることはすばらしいことかなと考えています。双方の自治体、それから、それぞれの団体の支援について、今後あり方を考えていきたいと思います。","id":"exchange-181"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"特殊詐欺です。私も松永委員と一緒で、開口部からの侵入が一番怖いので、防犯カメラが終わったら、開口部に対する助成、次はまずそこをやってほしいなという要望です。これまでの生活安全担当課長がそれぞれ頑張っていただいたＡＩの通話録音機、そして、防犯カメラ、次の新しい課長に対しても、しっかりと期待していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-182"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/619855?Template=document&Id=7005#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":120325,"voices":402}},{"id":"r07-20250310-3","meetingId":"r07-c-budget","date":"2025年3月10日","dateIso":"2025-03-10","committee":"予算特別委員会","time":"午前 ９時３０分～午後 ５時３２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を163件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"澤田委員","kind":"質問","question":"おはようあります。本日もどうぞよろしくお願いいたします。私からは２６７ページ、ファミリーサポートセンター運営費、同じく２６７ページ、ヤングケアラー支援事業についてお伺いいたします。令和７年度予算では、ファミリーサポートセンター運営費なのですが、３,２０９万８,０００円が計上されていますけれども、内訳をお知らせください。","respondent":"染谷子ども家庭支援センター長","answer":"予算の内訳といたしましては、平塚分が１,２５２万５,０００円、大井の分が１,８０５万５,０００円となっておりまして、こちら委託料の内訳としては、主にセンター事務局のアドバイザーの人件費、それから、その他事務費等で構成されているものになります。","id":"exchange-001"},{"speaker":"澤田委員","kind":"質問","question":"それぞれの内訳を教えていただきました。アドバイザー人件費や事務費などが主なものということで、アドバイザー人件費については、後ほどお伺いさせてというか、触れします。現在の提供会員と依頼会員の登録人数、あわせて、区としてどのような課題があるとお考えでしょうか、お聞かせください。","respondent":"染谷子ども家庭支援センター長","answer":"もう一方の依頼会員の登録数につきましては、４,１５６人となっております。課題といたしましては、今委員のご指摘のとおりで、提供会員と依頼会員の登録数の差の部分にあるかと思います。提供会員の成り手を増やすための取組が必要であると考えているところです。","id":"exchange-002"},{"speaker":"澤田委員","kind":"質問","question":"成り手の年齢層の幅を広げ、人数を増やすには、依頼会員の経済的負担を増やすという形ではなく、区として助成をするなどの方向で、もう少し報酬を上げていくことや、提供会員養成講座、皆さん受けていらっしゃると思うのですが、その際のテキスト代の無償化、子どもの手が離れてきた４０代から６０代のミドルシニア世代というものをターゲットに、周知を行っていただくことも必要ではないのでしょうか。","respondent":"染谷子ども家庭支援センター長","answer":"こちら都の補助事業を活用しながら実施していきたいと考えております。それから普通救命講習のテキスト代、こちらにつきましても、新規、それから更新の方も含めて、無償とするよう実施していきたいと考えております。","id":"exchange-003"},{"speaker":"澤田委員","kind":"質問","question":"送迎が約９割、預かりが１割ということで理解いたしました。働きながら子育てをしている保護者も多いということもあり、シッターサービスの需要も高まっていますが、今の割合をお伺いすると、ファミサポではそれほどまだ活用されていないのかなという印象も受けます。現在ファミサポでの預かり支援としては、依頼会員宅ではなく、提供会員宅となっています。","respondent":"染谷子ども家庭支援センター長","answer":"ニーズ調査につきましては、現在は事務局のアドバイザーが、申込みや顔合わせのタイミングにおいて要望のほう丁寧にお聞きしておりますけれども、ただ、今委員おっしゃられたとおり、登録はしているけれども利用していないニーズなどもあるかと思いますので。","id":"exchange-004"},{"speaker":"澤田委員","kind":"質問・要望","question":"一般質問でもお伺いしましたが、提供会員の面談等でしっかりと人柄なども見ていただいていると思いますし、研修も行って、これからまた報酬を上げていくとともに、さらに研修のほうも深めていくということなので、安全面、安心面、しっかり取り組んでくださっていると思いますが、虐待や性被害などで子どもたちが傷つくことがないよう、研修により一層力を入れていただくとともに。","respondent":"染谷子ども家庭支援センター長","answer":"』というタイトルの絵本かと思います。こちらは現在品川図書館において取扱いをしておりまして、そのほかヤングケアラー関連の書籍が、児童図書やティーンズ向けのものも含めて、各地区館に数十点取扱いがあるという状況です。","id":"exchange-005"},{"speaker":"澤田委員","kind":"質問・要望","question":"現在も取扱いがあるということで安心いたしました。未就学のお子さん向けに絵本などはとても分かりやすいと思う一方で、小学生以上になると、子どもたちによってはもう少し深い内容、濃い内容を求めるということもあるのではないかと思います。その辺を取り扱う施設の拡充と、絵本や漫画の取扱いを増やしていただくとともに、ヤングケアラーの漫画の導入について区の見解をお聞かせください。","respondent":"染谷子ども家庭支援センター長","answer":"ヤングケアラーの支援の課題としまして、１つケアの状況が表面化しづらいというところがあるかと思います。","id":"exchange-006"},{"speaker":"澤田委員","kind":"意見","question":"それとともに、より一層の理解を促すためにも、今おっしゃっていただいた漫画の導入以外にも、防災教育、中学生に向けての防災教育のように、アニメや動画の制作なども視野に入れ、アプローチしていただくことをお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問","question":"おはようあります。２３３ページ、終活支援パッケージ事業助成、２３７ページ、福祉ショップ運営費、２４５ページ、旗の台リボン跡地障害者就労支援事業、関連して伺います。２４１ページ、中等度難聴者への補聴器購入費助成について、順不同で伺います。最初に、中等度難聴者への補聴器購入費助成についてお伺いをいたします。お伺いをいたします。","respondent":"松山障害者支援課長","answer":"中等度難聴者への補聴器購入助成ですが、委員のおっしゃるとおり、東京都の事業とは別の、区独自の事業です。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"東京都の事業と、品川区独自の事業ということを確認いたしました。私からは、ニーズを確認しながら、１８歳以上の方にもぜひ助成の検討をと要望させていただきましたので、先ほど確認をいたしましたが、新たに区の事業として助成対象となったということを大変うれしく思います。そこで、助成するに至った経緯と、この事業が今後継続をして行っていただけるのか、お伺いをいたします。","respondent":"松山障害者支援課長","answer":"助成に至った経緯です。１８歳から６４歳までの中等度の難聴の方や、日常生活用具等検討会の相談員の方からもお声をいただきまして、検討した結果、聞こえの能力の向上や費用負担の軽減から必要であると区として強く認識し、事業化に至ったものです。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"中等度難聴児への助成は、購入費と修理にも使える制度です。所得制限も撤廃をされました。１８歳以上から６４歳の方へは購入のみが対象で、所得制限があります。６５歳以上の高齢者の方には所得制限がありません。所得制限なく行っていただきたいと思います。そしてまた、修理費用が対象となっていないこと、所得制限の考え方をお伺いいたします。","respondent":"松山障害者支援課長","answer":"障害者手帳を所持する難聴者の方が使用する補聴器につきましては、修理はございません。所得制限がありますので、今のところ制度の変更というものは、国の制度に合わせているところなので非常に難しいところですが、国の動向を今後とも注視してまいります。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"例えば、区内での手帳を持っている対象の方で、所得制限があることで助成を受けられない方、どれくらいいるのか、今後ニーズを把握していただきながら、事前にお伝えしていないので数は聞きませんけれども、そこをしっかり品川区で補填をするなりの、そのようなことも含めた検討をしていただきながら、ぜひ所得制限の撤廃は要望させていただきたいと思います。８３０万円の予算の内容を伺います。","respondent":"東野福祉計画課長","answer":"こちらが大体９０名から１００名ぐらいをめどとして、倍増していくのではないかというところで、そのぐらいの見込みとしての補助を用意しているものです。それから、ひとり暮らし高齢者、それから高齢者世帯の人数です。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"現在５０人が既に利用されていて、倍増するのではないかということの予算立てというように確認をいたしました。一方で、今高齢者のひとり暮らし、また、世帯の確認をさせていただきましたが、今いただきました数を合わせると３万７,０００人を超えている。そして、これを今後どのように多くの区民の方にお知らせをしていくのかという、最後周知を聞かせていただきたいと思います。","respondent":"東野福祉計画課長","answer":"周知につきましては、区のホームページ、社会福祉協議会のホームページ、それからデジタル関係、ＳＮＳなども使いまして、様々周知を行っていく予定です。広報紙なども活用していく予定です。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"そのような広報紙等々、必要だと思いますが、直接、やはり高齢の方ですので、確実に高齢者の対象の方に届くような、民生委員を通じて等々、高齢者クラブ等も含めて、大きく周知を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"ひがし委員","kind":"質問","question":"本日もよろしくお願いいたします。私からは、２３９ページ、障害者グループホーム運営費助成、２６３ページの青少年育成事業について、時間が許せば２８９ページの里親養育包括支援（フォスタリング）事業について伺います。最初に障害者グループホーム運営費助成についてです。障害者支援区分の入居者数について、改めて品川区の現状をお聞かせください。","respondent":"松山障害者支援課長","answer":"この障害者グループホーム運営費助成の中の中重度障害者受入助成を検討するに当たりまして、区内の民間事業者を対象に調べましたところ、昨年の９月時点で、区分６が１名、区分５が２人、区分４が８人、区分３が１２人という状況です。","id":"exchange-014"},{"speaker":"ひがし委員","kind":"質問・要望","question":"特に区分５、６というところはなかなか入居が難しいというところで、確認をさせていただきました。会派といたしましても、要件の見直し、しっかりと使えるような事業にしてほしいというように求めておりましたが、進捗についてお聞かせください。別途厚生委員会等でも要望しておりました、障害者区分に応じた運営費の助成、令和７年度より始まるということで大変期待をしております。","respondent":"松山障害者支援課長","answer":"初めに、有資格者配置助成の検討状況です。有資格者配置助成につきまして検討したところ、サービスの質の確保の観点から、年数等については国からも示されており、難しいところです。その検討に至る経過の中で、今回、中重度障害者受入助成というものを初めてご提案するものです。","id":"exchange-015"},{"speaker":"ひがし委員","kind":"質問","question":"有資格者の助成というところではなくて、中重度の受入助成のところにシフトしたというような形で認識をしてよろしいでしょうか。この障害者区分ごとの助成の金額、全体の予算、そして各区分の想定の人数はどうやって決定をしていたのか、参考にした自治体等もあればお聞かせください。","respondent":"松山障害者支援課長","answer":"１,５１２万円です。この金額につきましては、２３区調べたところ、あまり実施している区がなく、練馬区を参考にさせていただいたものです。","id":"exchange-016"},{"speaker":"ひがし委員","kind":"確認","question":"その予算の規模としては、今入っている入居者の方々に当てはめて金額を算出したというところも確認をさせていただきました。これ参考にした自治体、練馬区ということで、品川区はもう区分３、４についても一律１.５万円ずつ下げるという形を取っていると思うのですけれども、この練馬区との違いというところは、品川区はどのように検討したのかというところも教えてください。","respondent":"松山障害者支援課長","answer":"練馬区との違いです。委員おっしゃいますとおり、まずはそれぞれの金額、練馬区は４以上からなっておりまして、重度という扱いです。品川区の場合、中重度の障害者の受入助成を検討する際に、前提として、有資格者助成をまず検討したということがあります。","id":"exchange-017"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ただ、厚生委員会の中でも重度の方、中度よりも重度の方がなかなか入りにくいというところのお話があったので、重度のところにもう少し金額を乗せておいたほうが、区分５、６の方々が入りやすいのかなと思いまして、また参考にした自治体が練馬区ということで、練馬区と比較してみたときにも、品川区の金額が少し違うのはなぜだろうと疑問に思ったので質問をさせていただきました。こちらは要望とします。","respondent":"柴田子ども施策連携担当課長","answer":"その中で若者に特化した支援というものは、ほかのライフステージと比べると少ないというように認識をしています。","id":"exchange-018"},{"speaker":"ひがし委員","kind":"質問・要望","question":"今では月１回、土曜日の午後に開催をし、中・高生、また２０代の若者も多く集まるというように聞いております。月１回に行われておりますしなわかカフェ、まだ開催して間もないとは思いますが、どのような工夫、しっかりとオープンに話しやすい雰囲気というところを意識してほしいなと思うのですけれども、工夫している点、どのようなことを行っているかについてもお聞かせください。","respondent":"柴田子ども施策連携担当課長","answer":"ただいまのお尋ねにお答えします。しながわほけんしつの年齢に決めた、参考にした自治体はですが、ユースクリニックのような事業をしている自治体というものは全国でもまだ限られておりまして、数は少のうあります。","id":"exchange-019"},{"speaker":"ひがし委員","kind":"質問・要望","question":"門間先生のところでは、おやつ、飲物を準備したり、あとアクセサリーの製作、ネイルアートなど、少し年齢層高めに設定をしているというようなお話を伺っております。１９歳までではなく、ぜひ２０代も、大学などで学生の方、また妊娠や性の悩みというところは年齢が少し上がっているというようにも聞いておりますので、そちらについても対応をぜひ検討していただきたいなと思いますが、いかがでしょうか。","respondent":"柴田子ども施策連携担当課長","answer":"ただ、他の自治体を拝見いたしますと、もう少し年齢を上に上げて、２４歳など、そういったところも見受けられますので、その点については今後需要と、それから社会の動きと、研究しながら対応してまいります。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"２７４ページ、保育施設運営費に関わって、保育園民営化統合方針について、２８１ページ、区内私立保育園経費に関連して、定員割れ加算制度について伺います。保育園事業が、子どもや親にとってどのような意義があると区は考えていらっしゃるのか伺いたいと思います。それと、共働き世帯の割合の推移について、近年増えているのか、減っているのか、伺います。","respondent":"中島保育施設運営課長、芝野保育入園調整課長","answer":"親にとっても、やはりご自身の保育、子どもたちの育児を専門家の方から、保育士から様々聞くことによりまして見直すということも今行っておりますので、そのような面でも、親にとってもメリットがあると考えているところです。未就学児の人口のピークですが、今策定中の品川区総合計画実施計画の中で、年少人口ということでピークのほうを出しておりまして、年少人口０歳から１４歳のところ、これは２０４６年、令和２８年にピークを迎えるです。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"区長は施政方針で、核家族化や共働きが進む中、まさに今言ったところです。私、これは現実の社会と子育て世代のニーズにもかなって、まさにこれから求められる施策であり、全くそのとおりであり、代表質問でも評価したとおりなのです。伺いますけれども、あり方基本方針の具体化はしないよう求めますが、いかがでしょうか。それともスクラップ・アンド・ビルドの対象と考えているのか、伺いたいと思います。","respondent":"芝野保育入園調整課長","answer":"２点ご質問をいただきました。あり方検討の内容というか、そちらのほうをお答えしますが、区では、これまで待機児童対策として、保育施設を積極的に誘致した結果、令和４年度に待機児童ゼロを達成しています。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"次に定員割れ加算について伺いたいのですが、２０２３年１月の調査時点なのですけれども、保育施設に定員割れに特化した補助を行っていないという区は、品川区含め３区だけでした。こうも言っております。これらの事業を園で行うことが自社努力というのでしょうか。改めて、この補助をやらない理由というのですか、こういった保育士、現場の声も踏まえて、どのように考えているのか伺いたいと思います。","respondent":"佐藤保育事業担当課長","answer":"空きが発生しているという状況に対する補助についてですけれども、この補助につきましては、まず効果検証というものをどのように図っていくのか、また、区内には区が認可している認可保育所以外にも、認可外の保育施設というものが多数存在していますので。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"ほとんどがやれていないわけで、それがあるからそれを使ったらどうですかということは、あまりにも実態とそぐっていないというのですか、見直しを求める、実施を求めることがいかがでしょうかということと、あと先ほど言った未就園児定期預かり事業、これ株式会社以外でやれているところというものは何園ぐらいあるのですか。ちょっと伺いたい。無理だったらあれですけれども、伺いたいと思います。","respondent":"佐藤保育事業担当課長","answer":"未就園児定期預かり事業に関して、株式会社以外でやっている園ということについてですが、申し訳ございません、今ちょっと手元に資料がないので正確にお伝えすることはできないのですけれども、委員からお話しいただいた未就園児預かり事業を導入することが難しいというお声。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひこの事業、補助を実施していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問・要望","question":"保育園関連についてお伺いいたしますけれども、これ私立保育園の事業者の方からご要望を受けたのですが、今からお話しすることは、私立、区立問わず問題になることかなと考えていますので、お話をします。対応可能になることが多くなると思いますので、そうした入園前のお子様の日本語の習得状況や能力などの状況の情報提供をぜひしていただきたいのですけれども、いかがお考えでしょうか。","respondent":"中島保育施設運営課長","answer":"園児、そして保護者の方の語学、言語での対応についてです。こちらの現状、今入園前の面談や身体測定などもありますが、そのところで、語学の状況について現場も把握をしています。","id":"exchange-026"},{"speaker":"筒井委員","kind":"確認","question":"現場で体制が整えられているということですけれども、その園の方がお困りの状況ということが実際発生しているので、確認の際、なかなか確認し切れないパターンなどがあるかと思うのですが、ぜひ、今後外国人の方増えてきますので、そうした事前の情報提供というものをよりしっかりと、よろしくお願い申し上げます。","respondent":"中島保育施設運営課長","answer":"現時点で、例えば区立保育園では毎月各園の感染状況の件数などを記録して、本課とも共有しています。現場ではしっかり感染対策に努めているところで、リアルタイムでまだ把握をするような、特段の支障なく園運営はできているというようには認識しています。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問・要望","question":"よろしくお願い申し上げます。１つ明るい動きかなと考えております。このスケッター、川崎市、北九州市、仙台市、そして特別区では中野区と協定をされて、今現在自治体と協定拡大をされているところですけれども、品川区では、令和７年度では令和６年度のような予算化はやらないという状況ですが、令和７年度ではやめられた理由は何か、そしてスケッター側に対して何か課題があったのか、お伺いをいたします。","respondent":"菅野高齢者福祉課長","answer":"しかしながら、こちら６か月の無償のトライアルを利用したというところで、こちらのほうとしてはきっかけづくりをさせていただきまして、事業者のほうも、現在２月で無償トライアル終わったのですけれども、３月からそのうちの１１事業所のほうが継続して。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問","question":"そうですね、今後ぜひ、令和６年度は予算化、令和７年度ではされないということなのですけれども、１１事業者は継続ということで、そのほかの事業者の方が継続しなかった理由は何か把握されていますでしょうか。品川区はなぜ協定ということを結ばなかったのか、その理由もお聞かせください。","respondent":"菅野高齢者福祉課長","answer":"他自治体では、協定を結んでいるところは、委託料、こういったトライアルを委託料として払っているところもあれば、きっかけとして呼びかけて、事業者の参加を促しているというところと、様々と聞いておりますので、区としては委託事業として実施をさせていただいて。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。いずれにしても、今回スケッター側の課題ということもいろいろ見えてきたかなと考えています。一方で、非常に介護人材不足のこの状況の中、１つ明るい動きだと思いますので、ぜひ品川区といたしましても、今後ぜひ広報など、支援の協力や今後協定を結んでいくとか、そうした無形、有形の支援を行っていただきたいと思いますが、いかがお考えでしょうか。","respondent":"菅野高齢者福祉課長","answer":"そういった形で、今後も何か区として支援できることがあればというところで、引き続きこのスケッターサービス、継続する事業所も多数ありますので、いろいろなお声を聴きながら、何か支援できる方法を考えていきたいと思います。","id":"exchange-030"},{"speaker":"筒井委員","kind":"意見","question":"ぜひよろしくお願い申し上げます。最後にちょっと時間がないですけれども、支え愛・ほっとステーション事業、全世代向けになるのですが、人員体制は十分なのか、それと相談場所の確保は十分なのかお聞かせください。","respondent":"東野福祉計画課長","answer":"支え愛・ほっとステーションの人員体制です。こちらにつきましては、令和７年度、５か所で今の２名から３名に増員する予定です。場所につきましては、地域センターと場所の確保について十分話し合っているところです。","id":"exchange-031"},{"speaker":"せらく委員","kind":"質問","question":"私ごとなのですけれども、４月に子どもが小学生になるため、今入学準備にいそしんでいます。すまいるスクール運営費からは、登録の電子化をしてほしいという思いで質問いたします。１月、２月は次年度の申込みで、職員の皆様も対応が多い時期だと思いますので、紙での直接のやり取りは苦労があるのではないかと思いまして、オンライン化、電子申請など活用できませんでしょうか。","respondent":"藤村子ども育成課長","answer":"こちらの今現状、おっしゃるとおり紙で出していただいている形になるのですが、こちらについてはデジタル化というものは順次進めておる形でございまして、現在のところ、来年度の途中からなのですけれども、例えば期中の登録ですとか、Ａ登録からＢ登録に変えるですとか。","id":"exchange-032"},{"speaker":"せらく委員","kind":"質問・要望","question":"順次対応を進めてくださるということで、保護者としても、その手続がスムーズになると、入学準備の負担が軽減できると思います。申込みのほかに口座登録の手続などもあると思いますが、そちらもぜひ一緒にオンラインをしていただきたいなということで要望させていただきたいと思います。改めてこちらの事業の目的を教えてください。","respondent":"藤村子ども育成課長","answer":"こちら朝の居場所の実施目的というところですが、朝の小１の壁というような社会的課題がある中、区におきましても、校門の前で開門を待っている児童の方はいらっしゃるというところですので。","id":"exchange-033"},{"speaker":"せらく委員","kind":"確認","question":"実施についてなのですけれども、例えば土曜授業の日や、学校が休みだけれどもすまいるスクールが開いている夏休みなどの長期期間中は、どのように考えていらっしゃいますでしょうか。先日質疑からは、朝の朝食の支援の中では、アレルギー対応が出てきたときの対応の話が出たと思いますが、朝食の内容について、アレルギー対応はしないということか確認させてください。","respondent":"藤村子ども育成課長","answer":"アレルギー対応のところですが、朝食支援に当たりましては、アレルギー対応の食事を提供するということは想定しておりませんので、そういった形での運用を今検討しています。","id":"exchange-034"},{"speaker":"せらく委員","kind":"質問・要望","question":"運用のところ、平日の学校の営業日ということなのですけれども、やはり大人は夏休みもお盆休みだったり、冬休みも年末年始の一部で、春休みも基本的には平日、月から金で勤務をしていると思いますので、そこの支援を小１の壁の解消という点では今後考えていただきたいなと考えています。昨年夏はほとんどのすまいるスクールで１０日程度注文できましたが、次年度はどれくらいを想定していますでしょうか。","respondent":"藤村子ども育成課長","answer":"今年度ですね、昨夏に関しましては、１校が１７日、ほかがおおむね１０日程度というところで実施いたしました。来年度に関しましては、個別の学校の状況等もあるのでばらつきは出てくると思うのですが、基本的には夏休み中の平日全てで実施していきたいと考えておるところです。","id":"exchange-035"},{"speaker":"せらく委員","kind":"質問","question":"個別の学校の状況によってですけれども、夏休みが入る７月の後半から８月いっぱいまで実施できるのではないかというようなことだと思います。この仕出し弁当なのですけれども、春休み、冬休みの実施の声が届いておりますが、こちらについては検討など、お考え状況いかがでしょうか。","respondent":"藤村子ども育成課長","answer":"こちら、特に春休みのほうに関しましては、保育園から小学校に上がったばかりのお子様がたくさんいらっしゃるというところで、やはり決まったお子さんがいらっしゃるわけではないというようなすまいるスクールの特性というものがありますので。","id":"exchange-036"},{"speaker":"せらく委員","kind":"質問・要望","question":"引き続きよろしくお願いいたします。最後に、オアシスルームについて、１点だけ質問します。以前、オアシスルーム利用をできるのは、保育園児は利用できないということで質問をさせていただいておりまして、今年の９月から保育園児も土曜日が利用できるようにしていただけるということで、こちらについても反響がありました。９月からということで、半年間準備が必要ということだと思います。","respondent":"藤村子ども育成課長","answer":"スケジュールの時期として、令和７年９月ということで、少しスタートのほうが約半年ぐらい、年度の始めから遅れるところに関しましては、そういったシステム改修のお時間をいただいて、運用を確認した後の運用開始というような形というところで、この時期になってあります。","id":"exchange-037"},{"speaker":"横山委員","kind":"提案","question":"」に参加しました。加害者からの相談事例があり、変わることを望む人が存在していますので、港区の事例もありますが、被害者への配慮を行った上で、ＤＶ加害者の面談の際に民間の加害者支援の情報を伝えたり、団体のチラシを児童相談所や子育て応援課の窓口に置くなど、情報提供をお願いしたいと思いますけれども、主体的に行動変容に取り組みたい加害者への対応について、区のご見解をお伺いいたします。","respondent":"長谷川児童相談課長、金子一時保護担当課長","answer":"児童相談所を中心とした性被害の発生予防についてですけれども、児童相談所は現状、事案が発生した段階で認知しまして、子どもと家庭を支援していく機関であることから。性被害を含めた様々な暴力から自分の心と体を守る暴力防止プログラムを取り入れまして、子どもを取り巻く大人、子ども自身が暴力を防止する意識やスキルを学ぶワークに取り組み始めています。","id":"exchange-038"},{"speaker":"横山委員","kind":"質問・要望","question":"２点目に、若者の心と体の健康相談事業、孤独・孤立対策推進事業についてお伺いいたします。先ほどひがし委員の質問でもあったのですけれども、ユースヘルスケアしながわほけんしつ、しなわかチャットについて、チャット相談と対面相談会の実施の状況を確認させてください。可能な範囲で、性別、年齢別の人数と、性に関する相談にどのような内容があったのかということを教えてください。","respondent":"柴田子ども施策連携担当課長","answer":"チャット相談、それから対面相談会ともに、昨年１０月から１１月にかけて約１か月間の試行実施をしたのち、本年１月より本格実施をしております。利用期間を通じまして、１月末時点の実績といたしましては、チャット相談のほうは約３５０人の利用登録があります。","id":"exchange-039"},{"speaker":"横山委員","kind":"質問・要望","question":"ご説明ありがとうございました。理解をいたしました。昨年６月にＮＨＫスペシャル「ヒューマンエイジ人間の時代第４集性の欲望デジタル技術“解放”か“堕落”か」で放送された事例をご紹介します。特に若者の性の相談については、まだまだ相談しづらい雰囲気があることも否定できません。若者の心と体の健康相談のさらなる充実と、孤独・孤立対策の推進を要望いたしますが、区のご見解をお伺いいたします。","respondent":"柴田子ども施策連携担当課長、東野福祉計画課長","answer":"若者の性に関する依存に対する対策につきましては、現在実施しております若者の心と体の健康相談の事業を通じまして、区においてどのような課題があり、対応が求められているかについて把握することに、まず努めたいと考えています。こちらの取組のほか、令和７年度につきましては、精神科医によるオンライン相談、こちらについても取り組んでまいる所存です。","id":"exchange-040"},{"speaker":"横山委員","kind":"質問・要望","question":"ご答弁ありがとうございました。ぜひ課題の対応、課題や今後の対応を早くしていただくということを努めていただきたいと思いますし、特に先ほどもありましたけれども、２０代前半の大学生や、就職して品川区のほうに入ってきて、それでまだ地域に知り合いがいない方で性の悩みを抱えていらっしゃるというような若者も、私は潜在的にいるかと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"えのした委員","kind":"質問","question":"私からは、２５３ページ、高齢者活動支援事業についてお伺いします。皆様ご存じだとは思いますが、アニメのサザエさん、お父さんの磯野波平さんは５４歳だと知りました。私ごとですが、今年波平さんと同じ５４歳になります。そしてサザエさんは２４歳、未婚ですし、子どももいませんが、今年私の長男も２４歳で、磯野家と親子ともに同じ年齢になります。そこでお伺いいたします。","respondent":"樫村高齢者地域支援課長","answer":"高齢者クラブ、それから会員の人数ですけれども、令和６年度の４月現在におきまして、１０６クラブ、それから８,４９２名の会員が入会をされている状況です。推移ですけれども、それぞれ５クラブ、８０７名減少で、３年前と比較しますと減少しています。","id":"exchange-042"},{"speaker":"えのした委員","kind":"確認","question":"この３年の間に、５クラブ、８０７名と大変減少していると確認が取れました。クラブや会員数、減少の原因は何だと捉えていますでしょうか。お伺いします。","respondent":"樫村高齢者地域支援課長","answer":"企業の定年延長や、定年後も就労する方が増えておりまして、高齢者クラブへ加入する年齢が高くなっていることに加えまして、会員が高齢化することもあり、施設への入所や死亡などによることが主な要因だというように認識をしております。","id":"exchange-043"},{"speaker":"えのした委員","kind":"確認","question":"やはり原因は、加入年齢が高くなり、会員の高齢化と確認が取れました。先日地域の高齢者クラブの現役会長、解散したクラブの元役員にお話を伺いました。私は８５歳、もう１０年以上会長を務めている。次期会長が見つからない。そこでお伺いします。地域センターには高齢者クラブの担当者がいますでしょうか。ワンストップサービスができると、会長や役員の負担軽減になると考えますが、いかがでしょうか。","respondent":"樫村高齢者地域支援課長","answer":"引き続きご相談やお問合せのあった際には、関係課とも連携を図りながら、少しでも会長や役員の方々の事務処理の負担軽減につながるように、適切に工夫を図りながら支援してまいりたいと考えています。","id":"exchange-044"},{"speaker":"えのした委員","kind":"提案","question":"会派のまつざわ委員の代表質問からも、高齢者福祉、高齢者クラブの増員、民間との連携、フレイル予防等、ご提案がありましたが、高齢者の方がもっと活躍できるような場はないのでしょうか。ご見解をお伺いします。","respondent":"樫村高齢者地域支援課長","answer":"１例ではありますけれども、高齢者地域支援課では地域貢献ポイント事業を実施しております。今後も高齢者の増加が見込まれる中、地域でのボランティア活動を通じまして、地域における高齢者の相互支援と社会参加のさらなる促進を図っていきたいと考えております。","id":"exchange-045"},{"speaker":"えのした委員","kind":"質問・要望","question":"この地域貢献ポイント事業、よい取組だと評価しております。こちらさらに様々な高齢者福祉に寄与できるような取組を要望いたします。今後の高齢者支援における展開をお知らせください。","respondent":"樫村高齢者地域支援課長","answer":"引き続き、高齢者の方が住み慣れた地域でいつまでも安心して生活が送れるよう、高齢者クラブをはじめとした高齢者の方々のご意見を丁寧に聞き取りしながら、必要な支援を適切に行ってまいりたいと考えています。","id":"exchange-046"},{"speaker":"えのした委員","kind":"質問","question":"スマホを活用した介護予防サポートについてお伺いします。こちらの新規の事業とのことですが、概要をお知らせください。","respondent":"樫村高齢者地域支援課長","answer":"具体的には、利用者が５人程度のグループを作成いたしまして、日々の歩数や写真について、このアプリを通じてグループ間で共有して、自然に交流を図ることで運動習慣の定着化を促進するアプリを導入いたします。","id":"exchange-047"},{"speaker":"えのした委員","kind":"質問","question":"こちら補助金などはあるのでしょうか。お伺いします。","respondent":"樫村高齢者地域支援課長","answer":"補助金の件ですけれども、こちらは東京都の補助金を活用する予定です。令和７年度につきましては５９６万６,０００円を予算計上しておりまして、１０分の１０の割合で東京都からの補助金が歳入の見込みです。","id":"exchange-048"},{"speaker":"つる委員","kind":"質問","question":"２６３ページ、朝の児童の居場所確保事業、２６３ページ、こども計画推進費、２９３ページ、生活困窮者自立支援事業について伺っていきます。朝の児童ですが、これについては２０１９年に区民相談をいただきまして、具体的には現場対応で、学校で朝受け入れていただいたというところの対応から始まって、それから繰り返し質問もさせていただきました。当初予算に入っているかどうかを教えてください。","respondent":"藤村子ども育成課長","answer":"関係各所への共有ですが、通学ですので、教育委員会と連携を図っていくほか、警察や関係各所のほうに、事業実施の詳細が決まりましたら積極的に周知をして、児童が安全に登校できるようにというところや、居場所にいるときの事故がないようにというところは。","id":"exchange-049"},{"speaker":"つる委員","kind":"質問・要望","question":"質問の中で事例紹介として挙げさせていただいた豊中市は、この２０２５年度から、夏休み、冬休み、春休みも受け入れていきますということで、事業の拡充を図られていくそうでありますので、そうした取組もまた参考にしていただきながら、次年度、次々年度以降の対応についてお願いしたいと思うのですが、２０２６年度等も含めて。","respondent":"藤村子ども育成課長","answer":"２点ご質問いただきました。今年度、来年度試行実施という形ですので、その中で課題等整理いたしまして、再来年度、４月１日から実施できるかどうかや、長期休みのところどうしていくかというところを、状況を踏まえて検討していきたいと思います。","id":"exchange-050"},{"speaker":"つる委員","kind":"質問","question":"にぎやかな状況でありますけれども、そういったところをしっかりとやっていくということが大切かなと思います。ですから、そのようなファイナンシャルプランナーとの連携、これは事業の中で。セミナーや講演というものは結構やっているかと思うのですけれども、より１歩を踏み込んだ形での、そのような連携のありようということについて、区のお考えを教えてください。","respondent":"豊嶋生活福祉課長","answer":"今委員ご紹介の、ファイナンシャルプランナーの資格を持っているかどうかですが、委託している業者のほうにはそうした資格を持っている方もいらっしゃって、そういった資格を使ってご相談をお受けすることもたまにはあるのですけれども、今その資格を使うことよりも。","id":"exchange-051"},{"speaker":"おぎの委員","kind":"質問","question":"本日もよろしくお願いいたします。本日は２７３ページ、保育料等助成事業より第１子保育料、０歳から２歳児の無償化事業、２８７ページ、児童相談所運営費、２７１ページ、子ども食堂朝食支援についてお聞きいたします。最初に第１子保育料の無償化事業についてお伺いいたします。","respondent":"芝野保育入園調整課長","answer":"そして私立のほうが８８％超ということで、まだ若干の空きがございまして、今第二次募集のほうかけていますが、こちらのほうを含めましても、十分、例年並みに状況は推移しておりますので、そのようなご要望というか、ニーズが増えたとしても。","id":"exchange-052"},{"speaker":"おぎの委員","kind":"質問・要望","question":"少し余裕があるということで、無償化によって、では働きに行こうかなという方が急に増えたとしても対応できるということで、少し安心いたしました。早い段階からそういった建設情報などは入手して、対応されているのかということをお聞きいたします。時々保育士の処遇改善を求める陳情を目にしますが、区立の保育士の平均所得と、あともし分かれば、私立の保育士の収入の状況といったこともお聞かせください。","respondent":"芝野保育入園調整課長、中島保育施設運営課長、佐藤保育事業担当課長","answer":"そちらの中の量の見込みの中で、これから向こう５年間、どのような動きがあるかということは、そのような大型タワーマンション。区立の保育士の給与、人件費につきまして、ちょっと手元に数字はないのですけれども、２３区、人事委員会の方で共通して設定している数字を適用しています。平成２４年度は３２０万円でございましたので、着実に処遇改善等を実施しているというように認識しています。","id":"exchange-053"},{"speaker":"おぎの委員","kind":"質問","question":"令和６年１０月の児童相談所開設をもって、都からの移管推進事業が完了したと思われますが、品川区だけで行うようになって、具体的な問題などどれぐらい報告が来ているのでしょうか。電話や訪問対応など相談窓口が十分に機能できているのか、また、先ほど横山委員からも質問のときに、予防のほうにも取り組んでいかれるということでしたが、職員数は足りているのでしょうか。","respondent":"長谷川児童相談課長、金子一時保護担当課長","answer":"各職種からの意見に基づきまして、しっかりと所として適切な判断ができているというように認識しております。もともと都の品川のケース、保護の件数を基に定員を算出しておりまして、１４名という定員なのですけれども、ただ、実際開所をしてから、都のケース数の年間の数が大体４か月ぐらいで、それと同じ、大体都も同じ数が。","id":"exchange-054"},{"speaker":"吉田委員","kind":"質問・要望","question":"私からは、２４７ページの在宅高齢者支援事業か、５４８ページの居宅介護サービス等諸費に当たるかなと思います。それから時間があれば、２３９ページの地域生活支援事業について伺いたいと思います。最初に居宅介護サービス等諸費です。どうぞよろしくお願いいたします。そのご意見の中から幾つか伺いたいと思います。もっともなご意見だと思うのですけれども、事業所への支援について、まず見解を伺います。","respondent":"菅野高齢者福祉課長","answer":"この居住支援手当のほうは、給与規定を改定してから申請することが条件となっていまして、その金額の１５％、社会保険料事業主負担分相当も支給される仕組みになっておりますので、若干ではありますが、事業者の負担を少しでも少なくするという部分で。","id":"exchange-055"},{"speaker":"吉田委員","kind":"質問・要望","question":"ご見解を伺います。ヒアリングに参加したメンバーからは、断られた人はどうしているのだろうという声が上がったのですけれども、要はケアマネジャーが、多分一生懸命探して、この事業所のように引き受けてくれているところに頼み込んでいて、事業所としては地域福祉の視点から引き受けているものが現状かなと思うのですが、その辺についても見解を伺います。","respondent":"菅野高齢者福祉課長","answer":"ここについては、介護保険全体の中で給付と負担の考え方というところで、要支援１、２が総合事業に移ったという経緯等もありますし、あとは区のほうも、今回の令和６年度の介護報酬の改定に合わせまして、総合事業の単価は国の基準に合わせるということで。","id":"exchange-056"},{"speaker":"吉田委員","kind":"質問","question":"それで、人手不足解消に向けて、かつてのホームヘルパー２級よりも短い研修時間で取れる生活援助研修や、もっと簡単な入門的研修という制度ができたと伺いました。品川区はこれらの制度を活用する予定があるのでしょうか。あるとした場合、どのように制度の運用を始めるのか伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"区のほうとしては、すけっと品川養成講座というものを既に行っておりまして、こちらの中で、生活支援サービスを行っている、あるいは関心のある区民の方を対象に、講座等、介護等に対する基礎知識や介護技術の研修等も行わせていただいておりますので、そういったところで。","id":"exchange-057"},{"speaker":"吉田委員","kind":"質問・要望","question":"この新しい生活援助研修や入門的研修という制度は使わないというお答えと理解してよろしいのでしょうか。この事業所としてはそのような人材が欲しいので、底辺を広げるという意味でも、ぜひその制度を品川区も活用してほしいというご要望だったと思うのですけれども、やらないそうですよという感じのお返事になって間違いないのでしょうか。伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"そういったところも活用しながら、ちょっと事業者の行き違いなどもあるかもしれませんので、そういったお声をしっかり聴いて、介護職の担い手確保できるように努めてまいりたいと思います。","id":"exchange-058"},{"speaker":"吉田委員","kind":"提案","question":"今さらですけれども、その辺についての見解を伺いたいと思います。ここに書かれていますよというご紹介なので、皆さんで共有して、皆さんで知恵を絞れば、よい制度ができるのではないかなと思って、今後、まず障害者支援課で活用を研究して、同行への援護のサービス向上につなげればよいと思うのですけれども、そのときお聞きになったことも含めて、課長のご見解を伺いたいと思います。","respondent":"松山障害者支援課長","answer":"まだまだこういったご提案もありますので、確かに移動支援、同行援護については、非常に区としても課題だと認識しております。このご提案につきまして、しっかり研究をしていきたいと考えています。","id":"exchange-059"},{"speaker":"吉田委員","kind":"提案","question":"そこでせっかく出たご提案なので、研究とおっしゃいましたけれども、ぜひ、もう実現に向けた具体的な制度設計など、そのようなことに向かっていただきたいと思います。多分協力してくださると思うのです。制度をよくご存じなわけだから。ぜひそのような視点でもう１回、意気込みと申しますか、その辺についてご見解を伺いたいと思います。","respondent":"松山障害者支援課長","answer":"当事者の方から教えていただいた、いいご提案なので、きちんと受け止めて検討してもらいたいと思います。","id":"exchange-060"},{"speaker":"せお委員","kind":"質問","question":"よろしくお願いします ２４７ページ、障害児区外特別支援学校への通学支援、障害者手帳アプリ活用の導入、２６３ページ、すまいるスクール運営費等、時間があれば２８３ページ、医療的ケア児保育支援事業について伺います。大変感謝しております。多様な交通手段というところをちょっと、そのような意味で見解をお聞かせください。","respondent":"松山障害者支援課長","answer":"例えば電車やバス、あるいはタクシー、それからライドシェアといったようなことも想定しております。いずれにしましても、ご利用されるご本人やご家族が利用しやすいような交通手段を選んでいただき、ご相談いただければと考えています。","id":"exchange-061"},{"speaker":"せお委員","kind":"質問・要望","question":"障害者手帳アプリ活用の導入なのですけれども、こちらも会派から要望していたので、早速取り組んでいただき大変楽しみにしております。そこで、アプリ活用の具体的な導入場所や方法を教えてください。さらに５０万円という予算額なのですけれども、その内訳、分かれば教えてください。","respondent":"松山障害者支援課長","answer":"１台１日当たり１,０００円程度と見込み、約５０台を予定しております。そこに精算機を設置する際の工事期間を見込みまして、全てで５０万円とするものです。","id":"exchange-062"},{"speaker":"せお委員","kind":"提案","question":"本当にタイムズのありがたいお話ということで、そのような流れが広がっていくといいなと思っています。今回の障害者手帳アプリ活用ですけれども、まずはできる、そういったところから始めていただいて、その後ですが、ご提案をしますので、今後ご検討いただければと思います。そういった方たちも気軽に利用できるようなアプリ作成のご検討も今後行っていただきたいのですが、そちらの見解をお聞かせください。","respondent":"佐藤障害者施策推進課長","answer":"私からは、アンケート機能等につきましてのアプリ作成のご検討ということで質問いただいたところについて、お答えします。障害者施策推進課では、次期障害者・障害福祉計画の作成に向けて、来年度施策に向けた調査、基礎調査等を行ってまいります。","id":"exchange-063"},{"speaker":"せお委員","kind":"質問・要望","question":"ぜひご検討をお願いいたします。初めにすまいるスクールのところで一言要望したいのですけれども、午前中にすまいるスクールの登録手続を電子申請できないかというお話ありました。新１年生の初めての登録だけは、すまいるスクールに行ってほしいなという思いがあります。ですから、面談のような時間にもなり得ますし、最初の登録は足を運んでいただきたいなと、それだけ要望します。それで質問に入ります。","respondent":"藤村子ども育成課長","answer":"ということで、予算はこちらの運営費の中に２段構えになっておりまして、通常の委託契約に増員の金額として、増員できるというのは、契約変更の金額として７００万円ほど取っておりまして、それとは別に、今特別支援サポーター制度というものを今年度から始めておりまして。","id":"exchange-064"},{"speaker":"せお委員","kind":"質問","question":"入学式の前からすまいるスクールに通うわけですから、学校内の環境も、先生などの大人も何も知らないまま入って、児童にとっては不安しかないと思います。しかも言動や体も未就学児です。入ってくる全員に支援が必要なのかなと思っています。児童の安全確保のためには事前の情報収集も必要かと思いますが、すまいるスクールを利用する子どもたちの特性を現在どのように情報収集していますでしょうか。","respondent":"藤村子ども育成課長","answer":"すまいるスクールでの４月当初の過ごし方というところ、また、障害のある方、お子様への対応というところでご質問かと思います。","id":"exchange-065"},{"speaker":"せお委員","kind":"質問","question":"対応にばらつきがあるというお話だったので、そちらばらつきがないよう、保育園、幼稚園、学校、すまいるスクール、保護者、この関係各所での連携をさらに強めていただいて、確実に情報共有できるよう、体制整備をよろしくお願いいたします。医療的ケア児はちょっと時間がなくなってしまったので、違う場所でお伺いします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"中塚委員","kind":"質問・要望","question":"２５５ページの新規事業、家具転倒防止対策助成について、後半は高齢者の医療費無償化を求めて伺います。それは対象者が制限をされているからです。これが主要施策なのかと思います。そこで、対象者について、６５歳以上で要介護２以下の高齢者がいる世帯をなぜ対象から外したのか、障害者手帳保持者で２級以上を対象とし、それ以下の障害者がいる世帯をなぜ対象から外したのか、理由を伺います。","respondent":"樫村高齢者地域支援課長","answer":"対象者の範囲を決めた経緯ですけれども、先ほど申し上げたとおり、世帯の中で取付けが困難な方への支援という観点から、当時の関係課による協議の上、一定の線引きを行いまして、範囲を決めたというように理解をしています。","id":"exchange-067"},{"speaker":"中塚委員","kind":"質問","question":"取付けが困難な方への支援とのご説明でしたが、要介護２というものは、なかなか厳しい状況だなというものが実態です。そこで線引きをするということが、私は区長が「誰もが」と繰り返し述べている中で、なぜこうした線引きをするのか、なぜこうした高齢者や障害者をこの対象から外すのか、理由が分かりません。取付けが困難な方だと私は思いますが、いかがでしょうか。","respondent":"樫村高齢者地域支援課長","answer":"ですから、それぞれお一人での判断ということではなくて、世帯の中でということで判断をしているといったところです。あくまで本事業としては、先ほど申し上げた基準によりまして、本事業においての一定の線引きを行いまして、対象を設定しているものです。","id":"exchange-068"},{"speaker":"中塚委員","kind":"質問・要望","question":"この事業は年間６６万７,０００円と、決して大規模ではありません。対象を広げても数万円程度の追加で済むのです。改めて今年４月の実施ですが、制度を見直し、６５歳以上がいる世帯、障害者手帳保持者および６５歳以下でも介護認定を受けた方、要支援、要介護がいる世帯をこの事業の対象にして、「誰もが」を実現していただきたいと思いますが、いかがでしょうか。","respondent":"樫村高齢者地域支援課長","answer":"委員ご指摘のとおり、来年度、令和７年度につきましては、今回所得制限撤廃ということで実施をしてまいりますけれども、対象世帯の拡大につきましては、利用者からのお声や実態、それから他自治体の情報も参考とするとともに、関係各課とも協議しながら。","id":"exchange-069"},{"speaker":"中塚委員","kind":"提案","question":"」だったら、この事業の対象は高齢者、障害者とうたっているわけですから、高齢者、障害者がいる世帯は誰もが対象となると、ぜひそうしていただきたいと思います。要望したいと思います。続いて区長が述べる無償化ですけれども、ならば高齢者の医療費を無償にしていただきたいと提案したいと思います。私はそのとおりだと思います。ならば高齢者の医療費無償化を提案しますが、いかがでしょうか。","respondent":"池田国保医療年金課長","answer":"したがって、これ今の保険医療制度につきましては、現役世代の負担を軽減するために、実際に使われる高齢者の方の負担を伴いながら、医療の制度を継続するということで行っている制度ですので、現在の制度については特に問題はないかと思うのですけれども、ただ。","id":"exchange-070"},{"speaker":"中塚委員","kind":"質問・要望","question":"高齢者医療費無料化は国のほうだと。区としては注視するとのお話でありました。私、併せて伺ったことは、高齢者にとって医療とは生活の基礎となる行政サービスではないのかと。私はそう思いますがいかがかと質問しましたので、ぜひお答えいただきたいと思います。","respondent":"池田国保医療年金課長","answer":"医療の制度につきましては、国民健康保険と同様に相互扶助の精神に基づきまして、お互いに拠出しまして、制度の維持をしているものですので、生活をする上では必要なものではありますけれども、使われる方。","id":"exchange-071"},{"speaker":"中塚委員","kind":"質問・要望","question":"その生活の基礎となる行政サービスは無償で提供することが必要と区長はおっしゃいました。今、課長も、高齢者にとって医療費というものは、やはり大事だというお話だと思います。ぜひ品川区独自に高齢者の医療費を無償にしていただきたい、品川区から一石投じていただきたいと思いますが、改めていかがでしょうか。","respondent":"池田国保医療年金課長","answer":"医療費の抜本的な制度改革につきましては、国の動きについて注視してまいります。よろしくお願いします。","id":"exchange-072"},{"speaker":"塚本委員","kind":"質問","question":"私からは、２３９ページ、生活介護延長受入運営費助成、それから、２８７ページの私立幼稚園預かり保育事業補助金と、２点についてお伺いしたいと思います。この給付型のほうに移行した園とそうでない園の間で、預かり保育事業ということに何か違いのようなものが生じることがあるのかどうか、その点についても伺いたいと思います。","respondent":"芝野保育入園調整課長","answer":"もう１点、新制度園、今委員は新制度園の話をされているとは思うのですが、この制度、区立幼稚園、新制度を含めた私立幼稚園、認可外保育施設共通の制度でございまして、金額も同じ金額で、助成のほうさせていただいているものです。","id":"exchange-073"},{"speaker":"塚本委員","kind":"質問","question":"この預かり保育事業というものをしっかり充実させていくことによって、私立幼稚園の今後の事業継続、こういったことに寄与するというか、効果をどのように区としては考えているのかについてお伺いしたいと思います。","respondent":"芝野保育入園調整課長","answer":"現時点では、負担の公平性を考慮すると、国の無償化の制度を超えた保育の充実、拡充については慎重な検討が必要かと考えていますが、子育て世帯の多様なニーズに応えていくことも重要な課題であるというように認識しているものが、現状です。","id":"exchange-074"},{"speaker":"塚本委員","kind":"質問","question":"拡充、要するに補助金を増やすなどということに対しては慎重な検討云々というところであったと思うのですけれども、預かり保育がしっかり保護者の利用負担のようなものがなくなっていくとか、園側が運営する上でいろいろな経費が、負担がなくなっていくとか、そのような状況になっていくことによって、今の定員割れなど、そういったことが解消していく。","respondent":"芝野保育入園調整課長","answer":"預かり保育が、区の政策として今後どのように考えていくかですが、今後も預かり保育の利用状況、こちらを注視するとともに、保護者の皆様のご要望、こちらのほう丁寧に把握させていただきまして、また、国や都の補助金拡大の動向なども注視しながら。","id":"exchange-075"},{"speaker":"塚本委員","kind":"質問","question":"このような状況の中で、やはり事業者が、いや、うちやります、できますというところに対する支援という姿勢から、これ時々議論されているところだと思うのですけれども、ある程度これをやるのだという区の決断の下、できる事業者、できそうな可能性のある事業者とも一緒になって、いつまでにこれやりますよというような計画性を持ってやっていくというような施策の推進の仕方というものは、現行のこの法制度。","respondent":"松山障害者支援課長","answer":"なかなか障害の方、個別性が高いものですから、全ての方に合ったものというものがなかなかつくりにくいところですので、個々の状況に合わせて、本当にその方の必要なものは何かというところを知恵を出し合いながら、お互いに支援をしていくです。","id":"exchange-076"},{"speaker":"鈴木委員","kind":"質問・要望","question":"２４５ページ、２４７ページの障害者福祉について伺いたいと思います。中身については、放課後等デイサービスの質、量ともに拡充を求めたいと思います。本来、国が制度として無償化すべきものですが、今回品川区が障害者の通所支援の無償化というものは、私はこの基本合意や骨格提言の考え方と同様のものであると思いますけれども、区の認識を伺いたいと思います。","respondent":"松山障害者支援課長","answer":"そういったことは国のほうでも掲げるところですが、いかんせん、やはり国のほうでも、令和元年１０月に国の改正によって、就学前３歳から５歳までの利用者負担が全国的に無償化されているといったところが現状でもありますので、区においても既に開始しています。","id":"exchange-077"},{"speaker":"鈴木委員","kind":"提案","question":"基本合意の観点からも、また、この品川区の全ての家庭の子育てを支援する観点という点からも、医療的ケア児の訪問看護のレスパイト事業ですとか、入浴サービスですとか、訪問介護だと在宅サービスの無償化もしていただきたいと思いますが、いかがでしょうか。","respondent":"松山障害者支援課長","answer":"こちらのほうで初めて無償化を今回実施するという形になっておりますので、そういった影響や効果なども踏まえながら、今後は引き続き検討ということになります。","id":"exchange-078"},{"speaker":"鈴木委員","kind":"質問・要望","question":"日中一時支援について伺います。ここは定員２０名で、事項別明細で委託料について見たのですけれども、毎年増えているのです。令和５年が約４,０００万円、令和６年が５,１８０万円、新年度が５,７２０万円ということで、２年間で１.４倍に増えているわけなのですけれども、なぜ自宅送迎ができないのか、このことについては品川区も承知の上なのか伺います。","respondent":"松山障害者支援課長","answer":"ぐるっぽの日中一時支援の送迎についてのご質問です。自宅送迎からスポット送迎に対しての変更ですが、区としましては、施設側の運用の範囲内と思いますけれども、もう一度、再度施設側の現場のほうに確認させていただければと考えています。","id":"exchange-079"},{"speaker":"鈴木委員","kind":"質問・要望","question":"雨の日や風の日、雪の日、また猛暑だったり、寒波だったりなど、障害の子どもを２０分も歩かせるということは大変なことだというようなことで聞いています。家族に大きな負担をかける幹線道路でのスポット送迎は、この目的にも合わないのではないかと思いますが、いかがでしょうか。区立の総合支援センターなので、これまで同様送迎が続けられるようにしていただきたいと思いますが、いかがでしょうか。","respondent":"松山障害者支援課長","answer":"日中一時支援の送迎についてですが、区としてはまだ確認できていない状況ですので、改めまして施設側にきちんと確認を取らせていただいて、対応については検討します。","id":"exchange-080"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひ自宅送迎が続けられるようにということで、よろしくお願いしたいと思います。次に、放課後等デイサービスについて伺います。以前、利用限度が月１０日しかなくて、これは要望もいただいて議会でも何回も取り上げて、月２３日まで使えるようになりました。これは増やすことが必要ではないかと思うのですが、いかがでしょうか。","respondent":"佐藤障害者施策推進課長","answer":"障害福祉計画のサービス実績、見込み量につきましては、計画のほうにも、見込み量確保のための方策のところに、放課後等デイサービス整備進めておりますが、利用者ニーズに十分答えられていないというようなところは。","id":"exchange-081"},{"speaker":"鈴木委員","kind":"質問・要望","question":"計画の中でもそのような、令和８年度まで増えないという、１人当たりの６日という、２３区で最低の、そのようなサービス量というものが増えないという状況ですので、これはぜひ増やす方向で取り組んでいただきたいなと思います。これは医療的ケア児や重度だけでなく、対象を広げて放課後等デイサービスの誘致をしていただきたいと思いますが、いかがでしょうか。","respondent":"松山障害者支援課長","answer":"今年度につきましては、放課後等デイサービスも新たに対応に加えましたので、児童発達支援２事業所、放課後等デイサービス２事業所です。こちら１事業所に５００万円の、１回限りではなくて、年間、毎年助成しているものです。こちらの誘致をさせていただいているです。","id":"exchange-082"},{"speaker":"鈴木委員","kind":"質問・要望","question":"具体的にいろいろな社会福祉法人への働きかけなど、そのようなものも含めて、ぜひよろしくお願いしたいと思います。それから、代表質問で、重度障害者や医療的ケア児者のグループホームの整備計画と具体化を求めましたけれども、所要量を出して具体化していくという計画はいつまでにつくるのか、それから土地の確保は民有地の購入も含めて検討するのか、その点について伺います。","respondent":"佐藤障害者施策推進課長","answer":"必要量、計画の示し方につきましても、次期障害福祉計画等とも整合を図りながら検討を進めていくということで、その示し方、それから検討の体制や時期などにつきましては、改めて検討を今進めているところです。","id":"exchange-083"},{"speaker":"やなぎさわ委員","kind":"提案","question":"先ほど吉田委員も質疑されていた総合事業に関して、ちょっとマニアックですが、大切な質問、提案をします。それで、事業者都合でお休みをすると、これが月ぎめから日割りに変わってしまうということで、事業者の収入は下がってしまうということが一般的なのですけれども、そこでお伺いしますが、仮に悪天候、雪や台風などによって臨時で休業したときの取扱いはどうなりますでしょうか。お願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-084"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"もう前日ずっと１時間おきにネットで天気予報の更新を見なくても済むし、利用者にも、区からもそのように通知があったのでお休みしましたという、ある種免罪符になると思うので、ぜひそういったことを区としてやっていただきたいのですけれども、いかがでしょうか。もしくは、そういった、何かシステムがあれば教えてください。","respondent":"樫村高齢者地域支援課長","answer":"ただし、事業所の方が判断に迷われていて、お問合せ等いただく際には、他の事業所からの情報など、そういったことを参考になるような形でお伝えして、丁寧に事業所の方には対応したいと思ってあります。","id":"exchange-085"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ぜひこれは、それほど手間のかかることではないと思うので、進めていただきたいと思うので、強くこれは要望しておきます。その日に利用する予定だった方は全員日割りになってしまう。介護事業者などだとそうだと、通所事業所だとそうだと思うのですけれども、なってしまっているという状況、注意書きにそう書かれているのですが、それは間違いないですか。","respondent":"樫村高齢者地域支援課長","answer":"現状としては、委員ご指摘のとおりです。","id":"exchange-086"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"これは結構酷だと思うのです。そのＱ＆Ａの中に。ですから、ぜひこういったところは、区の中できちんと、何というか、柔軟な対応をしていただきたいと強く求めますが、いかがでしょう。","respondent":"樫村高齢者地域支援課長","answer":"事業所等の声も丁寧に聴きながら、今後の運用については検討してまいりたいと考えます。","id":"exchange-087"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"もう時間がないのであれですけれども、ぜひこういったところの取組もしっかりしていただければと思いますので、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"},{"speaker":"西村委員","kind":"質問","question":"２５９ページ、品川子育てメッセ、２６３ページ、朝の児童の居場所確保事業、２７１ページ、子ども食堂朝食支援、２７３ページ、私立幼稚園保育料助成について伺ってまいりたいと思います。その中で実施校の検討状況と、いつ頃からの実施を予定しているかなどの協議や報告など、何か進展があったのか伺います。","respondent":"藤村子ども育成課長","answer":"実施のタイミングとしては、５月の最終週から実施というところを目指して動きたいと考えています。","id":"exchange-089"},{"speaker":"西村委員","kind":"質問・要望","question":"この３校を選ばれた理由があればお聞かせいただきたいと思います。","respondent":"藤村子ども育成課長","answer":"３校、全て区役所からの距離が近いというところで、何か試行の際にトラブルがあった際にも対応しやすいというところがまず１つ、あと１校義務教育学校であったり、戸越小学校については昇降口というものがたくさん分かれていて。","id":"exchange-090"},{"speaker":"西村委員","kind":"質問・要望","question":"この朝食支援を始めるに至りまして、区内の現状をどのように分析しているのか伺いたいと思います。親が朝ご飯を作らないのか、作れないのか、朝ご飯の提供は実態の調査、支援の検討までをセットで実施していただきたいと考えています。朝ご飯の提供は、実態の調査と児童の状況に合わせた、その先の支援の検討までをセットで実施することが不可欠だと思いますが、お考えを伺います。","respondent":"藤村子ども育成課長","answer":"この朝食支援の実施の経緯といたしましては、私どもとしては総務省の調査、令和３年度の調査だったと思いますが、それで７％ほど朝食を食べていない児童がいるというところ、また、あと区内の子ども食堂のほうで実際にもう朝食支援をされていて。","id":"exchange-091"},{"speaker":"西村委員","kind":"質問","question":"ぜひよろしくお願いしたいと思います。朝ご飯に困ってはないけれども、一緒に通学する友達が朝食支援に行くので自分も一緒に行くというようなことも考えられると思います。３食親と食べない子どもも出てくるかもしれません。夜も民間学童などで済ませるなど、そのような子どもへの影響をどう捉えるかお伺いいたします。","respondent":"藤村子ども育成課長","answer":"この区の進める施策の方向性として、生活基盤となる行政サービスは所得制限なく全ての方に提供するというものに基づいているような形なのですが、先ほど申し上げましたけれども、この具体的な運用については、今後の調査に基づいて検討してまいりたいと思いますが。","id":"exchange-092"},{"speaker":"西村委員","kind":"質問・要望","question":"分かりました。提供内容がどのような食べ物を用意するか伺いたいのですけれども、食べていないお子さんにとっては、調理不要なおにぎりやパン、野菜ジュースなどでも食べる習慣をまずはつけるということが必要だろうと考えることは分かっておりますし、大変重要なことだと考えています。そして、栄養面にも気をつけてあげられたらいいなと要望いたしますが、お考えを伺います。","respondent":"藤村子ども育成課長","answer":"提供する朝食のところですけれども、おにぎりやパンなど、そういったものを含め現在検討中というような形です。ご利用される児童や保護者に喜んでいただけるというものを届けるような形で検討していきたいと考えております。","id":"exchange-093"},{"speaker":"西村委員","kind":"質問・要望","question":"次に私立幼稚園ですけれども、保護者の皆さんや幼稚園側からの長年の要望をいただいております。私どもも要望させていただきまして、今回、私立幼稚園保護者補助金の助成内容の拡充がされました。ぜひ私立幼稚園側と話合いを始めてほしいと考えています。こういった幼児教育、支えていかなければいけないと思いますので、お考えをお聞かせください。","respondent":"佐藤保育事業担当課長","answer":"私立幼稚園についてですけれども、区といたしましては、品川区の幼児教育を長きにわたりリードしていただいている、大切な施設であるというように認識しております。","id":"exchange-094"},{"speaker":"西村委員","kind":"質問","question":"子ども食堂のほうでの朝食支援についても伺ってまいりたいと思うのですが、学習食の支援事業のほうでは温かいお弁当を提供するというように伺っております。子ども食堂では、今既に始まっている事業を広げるというように認識しておりますが、配布はどの時間帯で、どのようなものを配布しておられるのか伺います。","respondent":"飛田子育て応援課長","answer":"子ども食堂での朝食支援のご質問です。","id":"exchange-095"},{"speaker":"西村委員","kind":"質問・要望","question":"去年の夏ですけれども、夏休みのラジオ体操でサンドイッチや飲物を子どもたちに直接配布した自治体がありました。最後に子育てメッセについて伺いたいのですが、今年度でもう１７回目になるというように認識をしております。今年度、２１１万円余の予算が新規計上されておりまして、コロナ後の参加者の推移と、子育てメッセ、今後どうしていくのか伺います。","respondent":"藤村子ども育成課長","answer":"今後としては、区としてはこちらの子育てメッセ、共催という形で運営しておりますので、今後も区の多数の部署、１１課になりますけれども、ＰＲの場として活用しているところありますので、しっかり連携して取り組んでまいりたいと考えています。","id":"exchange-096"},{"speaker":"西村委員","kind":"質問・要望","question":"担当課のみならず、区内中の様々な団体が出展をしておりまして、子育て家庭がつながる、この分野では区内最大級のイベントであると考えています。大変運営に苦慮してこられました。これだけの規模のイベントを区独自で行うならもっと予算がかかるものですので、今回支援が広がり、喜びの声が届いておりますけれども、実際にどのような企業がこの子育てメッセに参画をされているか伺います。","respondent":"藤村子ども育成課長","answer":"こちらの子育てメッセにつきましては、様々協賛を受けている形になっておりまして、個別の企業名としては、ちょっと今手元にはないのですけれども、様々、いろいろな形で区内の、例えば今出てきたのですが、サンリオなど、そういった企業のほうにもご協力いただいて。","id":"exchange-097"},{"speaker":"西村委員","kind":"意見","question":"この実行委員のお母さんたちが協賛を募りながら、そういった企業に向けて苦労して続けてこられた、もう１７回目になるイベントですので、ぜひとも引き続きご支援をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-098"},{"speaker":"こんの委員","kind":"質問","question":"私からは、２３３ページ、民生委員活動経費、２３９ページ、移動支援事業（ガイドヘルプ）、５５９ページ、要支援者夜間対応サービス特別給付費と通院等外出介助サービス特別給付費からお聞きしたいと思います。順不同でお聞きしたいと思います。そこでお聞きしますが、ガイドヘルパーの養成講座など取組状況と、人員の、いわゆる人材確保、この課題について改めてご見解をお聞きしたいと思います。","respondent":"松山障害者支援課長","answer":"定員については１５名で、ほぼほぼ定員は埋まるのですが、その後、実際に従事するかどうかとなりますと、そこのハードルが高くて、実際の従事する方々がほとんど少数であるというような課題を持っております。","id":"exchange-099"},{"speaker":"こんの委員","kind":"質問・要望","question":"ガイドヘルパーの１例ですけれども、まず利用者の自宅に向かいます。ですから、この片道サービス、いわゆる往路、復路だけの片道のサービスの報酬ではなくて、ここを見直していただいて、ヘルパーが一旦戻るといったところもサービスの中に入れていただく、いわゆる１時間弱でも１時間とするというような費用の見直しをというお声がありますけれども、こうしたことについて伺いたいと思います。","respondent":"松山障害者支援課長","answer":"他区の状況についても今現在調べているところで、算定時間についても少し工夫している区も少数ございましたので、今後他区の事例を参考にしまして、引き続き通学等の移動支援の充実に努めてまいりたいと考えています。","id":"exchange-100"},{"speaker":"こんの委員","kind":"質問・要望","question":"今、通学の支援のお話も出ましたけれども、私もその件はお聞きしています。利用者が利用したいときにそのサービスが受けられる体制として、この報酬の見直しをぜひご検討いただきたい、前に進めていただきたいと思います。何かございましたら、後でご答弁ください。次に参ります。改めて区のご見解を伺いたいと思います。来年度の事業はどのようになってしまうのでしょうか、お知らせください。","respondent":"菅野高齢者福祉課長","answer":"国のほうも、現在全世代型対応型の社会保障制度を見直す中で、介護保険の自己負担が２割負担となる対象範囲を拡大するなど、いろいろと検討されている中でありますので、引き続き区としては、国の制度の中で。","id":"exchange-101"},{"speaker":"こんの委員","kind":"質問・要望","question":"今、事業に対しては継続という形で確認をさせていただきました。この介護サービスについては、先ほども申し上げましたように、国の制度ですので、国の動向を見て理解をしております。そのように動向を見ていただきながら、考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"石田（し）委員","kind":"質問","question":"私からは２４５ページ、障害者就労支援事業、２６７ページ、ひとり親家庭支援事業についての、就労支援についてお伺いします。それと２７７ページ、幼稚園、保育園の給食について、時間があれば２７３ページ、児童福祉費、保育園や幼稚園の、いわゆる償還払いについてお伺いをしていきます。品川区で今行われている、その方々への就労支援というものはどのようなものがあるのか教えてください。","respondent":"松山障害者支援課長、飛田子育て応援課長","answer":"就労支援につきましては、区内で就労支援センターを設置いたしまして、そちらでも超短時間雇用促進事業という、長時間働くことが難しい方に対しまして、こちら別に手帳がなくても障害の疑いがあるといったような。実際サポートのほうでは、ひとり親のところの働きやすさや、またそこのところを聞きながら、また一緒にどのようなところで働くか、また生活リズム、そのようなところも兼ねて一緒に支援をしているところです。","id":"exchange-103"},{"speaker":"石田（し）委員","kind":"提案","question":"今いろいろ時代が変わって、この間総務費でもお話ししましたが、ＡＩ、様々な最新技術が出ていて、障害者の方たちの就労支援も、今提案をしますけれども、いわゆるＡＩを活用した仕事に就いてもらうと。この考え方を教えてください。その学校には幼稚園が含まれているのでしょうか。現在保育園と幼稚園、こういった施設での給食について、無償化に向けての取組というものは考えているのか教えてください。","respondent":"松山障害者支援課長、飛田子育て応援課長、中島保育施設運営課長","answer":"委員ご提案の、ＡＩを活用した学習支援によるスキルの向上や、新たな働き方のご提案です。そのＡＩの提案ですが、そのようなよりよいものがあれば、また研究していきたいと思います。幼稚園につきましては、施設によって様々、給食を出している、お弁当、給食、それぞれありまして、こちらのほうの無償化の考え方につきましてですが。","id":"exchange-104"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ということは、これは学校です。ですから、学校給食費というのであれば、ここは幼稚園も入れてしっかりと対応していく必要があるのではないかなと思います。北区では、令和５年からですか、幼稚園や保育園の、いわゆる給食無償化というものにも踏み込んで、今実施されていると思います。ぜひ品川区としてもそういった取組を進めていっていただきたいなと思いますが、改めてご答弁をいただきたいと思います。","respondent":"中島保育施設運営課長","answer":"先ほどの答弁繰り返しとなりますが、今、教育基本法等にも、幼稚園、位置づけられるというところもありますけれども、義務教育ではないというところ、その観点から、今のところ、まだ無償化等の対応はしておりませんが、今後社会情勢等を見極めつつ。","id":"exchange-105"},{"speaker":"石田（し）委員","kind":"意見","question":"そして償還払いについてですけれども、先日あくつ委員から力強いお話をいただいて、実は私も当事者として強く思っている課題の１つが、いわゆる保護者の負担と、要はやはり事務経費がかかっているのではないかなと思うので、その事務経費の軽減という両方の視点で、必要ではないかなと、新たなシステムが必要ではないかと思うのだけれども、もう一度その部分に関して答弁いただければと思います。","respondent":"中島保育施設運営課長、芝野保育入園調整課長","answer":"幼稚園での給食につきましては、現状、区立、私立ともに形態様々ですので、社会情勢等見極めつつ、判断すべき課題と認識してまいりたいと考えています。こちら保護者の経済的負担の軽減と、今、委員のおっしゃられました事務費軽減、こちらの観点から、各園保護者への周知と、システム改修も必要ですので、そちらのほうを進めまして。","id":"exchange-106"},{"speaker":"松永委員","kind":"質問","question":"２３３ページの孤独・孤立対策推進事業について、２５１ページの福祉人材確保・定着事業について、２５３ページの高齢者外出習慣化事業について伺いたいと思います。令和５年度の取組で、２０代から３０代の孤独・孤立に係る当事者へのヒアリングも行っているかと思いますが、そのほかの世代、いわゆる子ども、またお年寄りについては、どういった対策、また調査を行われているのでしょうか。","respondent":"東野福祉計画課長","answer":"大まかに説明いたしますと、分析結果といたしましては、１２５件の相談がございまして、土日夜間の相談が多かった。それから、女性が約６９％ということで、男性に比べての相談が多かった。２０代、３０代の相談が多かったという結果となっております。","id":"exchange-107"},{"speaker":"松永委員","kind":"質問","question":"ぜひ高齢者、子どもたちもそうですけれども、しっかりと調査をして、１人でも多くの命を救えるような事業にしていただければと考えています。そこで、２５３ページの高齢者クラブ支援事業、先ほども質問がございましたけれども、そのことについてかぶらないように質問いたします。事業評価シートではＣ評価ですので、この事業実施方法を検討するとありますが、今後の進め方についても併せて伺います。","respondent":"樫村高齢者地域支援課長","answer":"来年度以降、区では本格実施します重層的支援体制整備事業を進めていくのですけれども、そこに当たっても積極的に高齢者クラブの活動を支援していく必要があると考えています。","id":"exchange-108"},{"speaker":"松永委員","kind":"提案","question":"今後この高齢者クラブの周知が必要などという場合もあります。その中で、何か情報や、そうした調査というものが行われているのかどうかということを伺いたいと思います。最後はちょっと提案になるのですけれども、まずはこの高齢者クラブという考えから、ネーミングを変えていただけないでしょうか。６０歳以上の方は、高齢者と言われるのが嫌だ、また高齢者では俺はないと。区の見解をお知らせください。","respondent":"樫村高齢者地域支援課長","answer":"こういった形でクラブの方針によって名称を決めることができますので、こういった形で運用できるように、引き続き支援していきたいと考えています。","id":"exchange-109"},{"speaker":"松永委員","kind":"提案","question":"住環境、研修や講習、事業者へはＩＣＴシステムの導入など助成されておりますが、その中で外国人への家賃助成を確認させていただいたところ、年々、２０２２年からそれぞれ６件、２０件、１６件と、まばらでありますけれども、本区として比例しているとは思いませんが、現在外国人の方は、介護職についてどのくらいの人数の方が働かれているのでしょうか。","respondent":"菅野高齢者福祉課長","answer":"区内事業所に勤務する外国人の介護職員数ということのご質問についてですが、こちら区の、先ほど委員もご指摘ありましたけれども、住居の確保等の事業で、実際にご入居いただいている外国人の数ということで把握させていただいているものが、現在は１６人です。","id":"exchange-110"},{"speaker":"松永委員","kind":"質問・要望","question":"そこで本区としては、講座や講演会、外国語による相談会というような形で行っているかと思いますけれども、そうしたところを踏まえて、ぜひ外国人に対しての対策、取組をしっかりと取っていただきたいと思うのですが、また何か言語以外にも、例えば介護職専門のセミナーなど、何かそのようなものがあればいいなと思うのですけれども、いかがでしょうか。","respondent":"菅野高齢者福祉課長","answer":"セミナー等につきましては、例えば今年度ですと、ある事業者が外国人の方を集めて、そこで交流会などをさせていただいたり、そのようなことも努めしていますので、引き続き区も支援してまいります。","id":"exchange-111"},{"speaker":"田中委員","kind":"質問・要望","question":"今これを操作します。この請願で、目的、要望事項は２つありまして、１つは今言ったような保護者補助金、入園料の助成を求めるものと、あともう一つは、私立幼稚園協会、これは言い方が若干違うのですが、この添付されたものは振興助成金というものは私立幼稚園振興費補助金、そして保護者教職員連合会への助成というものは私立幼稚園協会への補助金、これを求めるものであります。認識をお伺いします。","respondent":"佐藤保育事業担当課長","answer":"委員からお話しいただきました保護者教職員連合会、これは私立幼稚園協会の中の１つの連合会というように聞いておりまして、主な参加メンバーは保護者の方たち、教職員の方たちということなのですけれども、保護者の方たちですので、子育て世帯の感じる。","id":"exchange-112"},{"speaker":"田中委員","kind":"質問・要望","question":"かつて私は母親大会に出たことありますが、その当時は自民党から共産党まで全ての会派の方を呼んで、予算要望のお願いや、そういったことに対する感謝のお言葉などがありました。それで保護者の立場からその会に出たら、なぜあなたはこの会に来ているのですかと思われるぐらいのような対応だったそうです。このような視点を財政課長、補助金担当の企画部門としてはどのように判断されますでしょうか。","respondent":"佐藤保育事業担当課長","answer":"一部繰り返しの答弁となってしまい大変申し訳ございませんが、私立幼稚園協会に対する補助に関しましては、品川区全体の幼児教育の向上を図るための取組の経費を、一部を補助しているというものです。","id":"exchange-113"},{"speaker":"田中委員","kind":"質問・要望","question":"ですから、私は、これあえて冒頭皆さんにお伝えしたことは、ぜひ考えていただきたいのですけれども、請願を、これはほぼ全会一致で通ってしまっていますが、そのことが私は影響しているのではないかという思いもしてなりません。私は言うべきことは言う、改善していくべき視点は、保護者負担軽減はいいけれども、協会に対する支援は大いに見直したほうがいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-114"},{"speaker":"高橋（伸）委員","kind":"質問","question":"よろしくお願いします。２４５ページ、旗の台リボン跡地障害者就労支援事業、２４３ページ、心身障害者福祉会館運営費についてお伺いをします。初めに、２４５ページの旗の台リボン跡地障害者就労支援事業についてお伺いをいたします。これ今後のことなのですけれども、当然連携取っていくと思われますが、どのような方向性なのか教えてください。","respondent":"松山障害者支援課長","answer":"ただし、こちらの就労支援施設の場合につきましては、就労体験をしていただくというような形なので、例えば会館の地域活動支援センター逢のところで通っていただいた方が、またこちらのリボン跡地で就労体験をするですとか、あとは地域の町会の方々も含めまして。","id":"exchange-115"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これ事業内容で、２点質問をします。本区では恐らく全校なのかということが、すみません、今の質問の１点目で、それとあと、中央区にはそこのホームページがあって、ネット上でも何かやり取りができるということがあります。これはぜひホームページを開設していただいて、受注に関してもホームページ上でやり取りができるような仕組みをつくっていただきたいと思いますが、いかがでしょうか。","respondent":"松山障害者支援課長","answer":"制服につきましては、教育委員会と今後連携をしまして、具体的には検討していきたいと思います。","id":"exchange-116"},{"speaker":"高橋（伸）委員","kind":"質問","question":"すみません。それでもう１点目が、これ地域のインクルーシブな交流を促進しますということなのですけれども、具体的に、今まで心身障害者福祉会館まつりでは、そこの当該町会が積極的にやっていただいている中で、具体的にお分かりになれば、具体的に地域のインクルーシブな交流の促進ということはどのようなことを取り組むのか教えてください。","respondent":"松山障害者支援課長","answer":"１階の集いの場というところで、障害の有無にかかわらず、どなたでも利用できる集いの場を併設したいです。そこで地域交流を促進していきたいと考えています。","id":"exchange-117"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"２４３ページ、心身障害者福祉会館運営費についてお尋ねをします。これ逢がやっていて、地域活動支援センターがあります。恐らくこれ、利用件数も相当数伸びているのかなと思いますが、この中で、身体・知的障害、高次脳機能障害等々、いろいろありますけれども、一番多いというのか、何というのか、活発にやっておられると思いますけれども、数字が現時点でお分かりになれば教えていただきたいと思います。","respondent":"松山障害者支援課長","answer":"地域活動支援センター逢の数字ですが、手元にはちょっと障害種別ごとのものはございません。一番多いものは、恐らく手話講座の部分です。障害のない方もかなり多くいらしていただいております。","id":"exchange-118"},{"speaker":"高橋（伸）委員","kind":"意見","question":"それで、これは言葉のリハビリ教室も開催をしていると思います。これ事業運営の母体が、東京都の言語聴覚士会でやっております。あくまでこれ、都のことなのですけれども、来年度の予算は、失語症の方に対するというものは見えていないのですが、失語症に対しての意思疎通支援事業というものは、いずれ、今後区としてお考えになられているのかどうか、お尋ねをします。","respondent":"松山障害者支援課長","answer":"昨年から失語症の当事者やご家族の方、そしてＳＴ、言語聴覚士協会の方々からもご意見を頂戴しております。実際の事業の内容につきまして、今学ばせていただきまして、今後各区にも足を運んで研究をしてまいります。","id":"exchange-119"},{"speaker":"西本委員","kind":"質問","question":"２５６ページの子ども育成費全般で、関連して朝の児童の居場所確保、それから病児保育、仕出し弁当という関係で、それぞれ関連してお聞きします。時間があればお米プロジェクトもやりたいのですけれども。子育て支援の考え方を聞きたいと思います。子育てというものは、親の役目は当然あると思うのです。区はどこまでやって、この子育て支援をどう考えていろいろ施策をやろうとしているか、教えてください。","respondent":"藤村子ども育成課長","answer":"子育て支援というか、親育ちという関連のところかなと思うのですが、区としては、児童センターのほうで様々、親育ち支援事業ということで実施しておりまして、小学校から中学生で将来子どもを持つことの意識を持ってもらうですとか、母親の方や父親向けの子育て。","id":"exchange-120"},{"speaker":"西本委員","kind":"質問","question":"いや、そのようなことを聞いているのではないのです。子育て支援というものをどのように捉えてやっているのですかという話なのです。よく区長も言っておりますけれども、負担とか、不満とか、負担と不満は違いますが、それを軽減するという言い方をします。子育ては負担ですか。どうでしょう。","respondent":"藤村子ども育成課長","answer":"こういった状況下で、所得制限なしに生活基盤となるサービスを誰もが受けられるというような状況を提供しているということが、今の子育て支援という形で主に展開している施策かと思います。","id":"exchange-121"},{"speaker":"西本委員","kind":"質問","question":"区でやらなければいけないことは、子育ては楽しいですよ、大変だけれども。その中で、これ文部科学省の教育基本法でも、父母その他の保護者は、これは教育法ですから、教育についてと書いてありますが、第一義的責任を取りましょうと言っているのです。ですから、親の仕事、親の役割とは何でしょう。品川区はどこまで税金を使ってやろうとしているのかお答えください。","respondent":"藤村子ども育成課長","answer":"親のほうが一義的に何か子育てについて責任を担うというところはありますけれども、先ほど申し上げたとおり、何かをしてほしいという、こちらとしては義務を課しているわけではなくて、あくまでサービスの１つとして選択肢を提供しているという形になりますので。","id":"exchange-122"},{"speaker":"西本委員","kind":"質問","question":"友達もいっぱいいるからという形になってしまうので、ですから、どこまでやろうとしているのか。そうなると、いいですか。朝は学校で食べさせてもらい、日中は給食が出て、仕出し弁当、夏休み仕出し弁当、夜はテイクアウト、子どもに対して親は何をやるのですか。今回食で考え方をちょっとしたいのですけれども、その食に対しての親の責任、子育ての中での食の大切さというものをどう考えられていますか。","respondent":"藤村子ども育成課長","answer":"ですから、１つ子どもとの関わりとして親との気づきがあるということは、一概にはそういった局面だけで申し上げられないと思いますので、様々な場面の中で、子どもの成長や親の成長につながる場面というものはあると思いますので。","id":"exchange-123"},{"speaker":"西本委員","kind":"質問","question":"だけれども、忘れてはいけないことは、子どもの気持ちを考えたら、朝ご飯ぐらいきちんと食べさせてほしいということを教育の一環も含めて、行政はやらなければいけないと私は思います。だから、子育て支援というものは、本当に親がしなければならないことは何なのか、子どもの利益とは何なのかということをしっかり考えた上で、子育て支援というものをやらなければいけないと思いますが、いかがですか。","respondent":"藤村子ども育成課長","answer":"子どもの支援をやり過ぎると親が何もやらなくなるというようなお話ですが、そういったことは、批判には当てはまらないかなと思っておりまして、誰もが自分の子どもをかわいがって育てるというところはありますので。","id":"exchange-124"},{"speaker":"若林委員","kind":"質問・要望","question":"今春、または来春卒業するお子さんを持つ保護者の方々から、情報提供なり、直接お話を伺うことができました。２０２７年度に移転し、定員が現在の６名から２０名へと３倍強に拡大されることになっていますけれども、ここについては期待も大きいということで、速やかに延長の準備に着手をしていただいて、できるだけ早く、今のうちから早期の延長受入れを要望いたしますが、事業所、区の取組を確認します。","respondent":"松山障害者支援課長","answer":"やはり特別支援学校卒業後、働き続けることが困難ということでございまして、生活介護の施設で利用時間の延長の実施をお願いするということが１点、そしてもう１点目は、延長時の送迎の実施ということの、大きく２つの点があります。","id":"exchange-125"},{"speaker":"若林委員","kind":"質問・要望","question":"ピッコロを含め、延長を確実に実施できるための一重の行政からの支援のお考えを、いま一度最後に確認します。一応、これはちょっと日中一時支援事業の活用も検討いただきたいという要望もさせていただこうと思っておりましたが、こちらについても、一定の進めていらっしゃるというお話も聞いておりますので、ここについてもちょっと、今後の見通しがあればご答弁をいただきたいと存じます。","respondent":"松山障害者支援課長","answer":"重要な課題と認識しておりますので、引き続き実現できるよう取り組んでまいります。","id":"exchange-126"},{"speaker":"若林委員","kind":"質問・要望","question":"４月の１日以降、ぬか喜びにならないように、しっかり前に進めていただきたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-127"},{"speaker":"高橋（し）委員","kind":"提案","question":"２８６ページの児童相談所運営費に関連してお伺いします。その結果、平成２８年の児童福祉法改正により、政令で指定された特別区は児童相談所の設置が可能となったことから、準備が整った区から順次児童相談所の設置を目指すこととする区長会総会での確認事項を踏まえて、取組がなされております。江東区も区立児童相談所の設立を目指してきましたが、令和７年１月に都の提案を受け、方向転換したようです。","respondent":"吉岡政策推進担当課長","answer":"東京都品川児童相談所の目黒区、大田区、こういったやり取りの中につきましては、情報共有を行ってきたところです。","id":"exchange-128"},{"speaker":"高橋（し）委員","kind":"質問","question":"そこで、東京都はどのように考えているのか、そのようなことについてのお話はあったのでしょうか。この後も区が使っていいのかどうか、そういったことに関してあったのでしょうか。","respondent":"吉岡政策推進担当課長","answer":"東京都品川児童相談所のその後の活用についてですけれども、今区のほうで聞いておりますものは、令和８年度以降の活用方針、現状未定というように聞いているところです。","id":"exchange-129"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"令和８年度以降が未定ということであれば、品川のほうから働きかけるべきではないでしょうか。まだ建物は使えると思います。令和８年度に移転するわけですから、令和７年度に品川区がどのように使うかということをこちらから働きかける、そのための令和７年度に検討して東京都に要望する必要があると思いますが、見解を伺います。","respondent":"吉岡政策推進担当課長","answer":"こちらの施設につきましては、ご案内のとおり区立施設も併設されております。都有地でありながらも、非常に貴重な公有地です。引き続き東京都のほうは情報連携を密に行いながら、庁内においてもどのような活用ができるかというところの検討を進めているです。","id":"exchange-130"},{"speaker":"高橋（し）委員","kind":"質問","question":"検討を進めているというレベルですが、それよりも、もはや土地を含めて取得するぐらいの強い姿勢、そして区のほうから具体的にこのような形で使っていきたいということを示すべきだと思いますが、改めていかがでしょうか。","respondent":"吉岡政策推進担当課長","answer":"繰り返しになりますけれども、貴重な土地、財産であるというところは認識をしています。活用方法、しっかりと検討して、東京都のほうと協議をしていきたいと考えております。","id":"exchange-131"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"令和７年度にしっかりと検討し、その令和７年度の間に、東京都に言って、何といいますか、要望していかないと、令和８年度に大田区が出ていったときに、あれどうするということになりますので、どれぐらいの検討の状況か分かりませんけれども、先ほどから繰り返し申し上げておりますが、貴重な建物であり、品川区が必要な、何ですか、事業はたくさんあります。その点についてはいかがでしょうか。","respondent":"吉岡政策推進担当課長","answer":"おっしゃるとおり、こういった跡地活用、そういった部分は非常に今行政需要も様々ありますので、多角的な視点から判断をしていきたいと考えております。","id":"exchange-132"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"多角的に検討していただきたいと思いますが、本当時期が迫っているのです。ぜひお願いします。このようなバラバラの状況をどのように捉えているかお伺いします。","respondent":"森澤区長","answer":"様々、それぞれの各自治体の事情があるということは認識しておりますが、品川区としては、しっかりとこの区の児童相談所、設置をいたしましたので、今回財調の協議もありました。しっかりと品川区の児童相談所を確立していくべく取り組んでまいりたいと考えています。","id":"exchange-133"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今度、最終的には１２区が区立を持ったとすると、先日プラスした分では足りず、ごめんなさい、区長会事務局の計算によると、５５.１％に０.５％を加えた５５.６％が適切だというような考え方があります。例えば、都立児童相談所を持っているところには対応補正を行わないなどと、そのような形で、区立児童相談所を持っている区がまとまって財調を求めていくということをお願いしますが、いかがでしょうか。","respondent":"加島財政課長","answer":"都区財政調整に関するお尋ねですけれども、今回０.９％の配分割合の変更がございました。こちらにつきましては、委員からもご案内ございましたとおり、令和９年度までに設置予定の１２区、こちらの大体需要額が約１９６億円と試算されております。","id":"exchange-134"},{"speaker":"松本委員","kind":"質問・要望","question":"私からは、２５５ページ、家具転倒防止対策助成、２６７ページ、体験格差改善事業について伺います。先ほど中塚委員からの質問で、この助成の対象についてお話があったかと思います。私のほうでは、高齢者に限らず、視点をさらに広げて少しご質問させていただきたいと思います。その理由についてお伺いいたします。","respondent":"樫村高齢者地域支援課長","answer":"実施事業の所管課についての考えですけれども、本業務につきましては、平時、災害時と切り分けて考えるのではなくて、平時の業務との密接性で事務を行っているものというように認識をしています。","id":"exchange-135"},{"speaker":"松本委員","kind":"質問","question":"そのときに考えていかないといけないことが、ではその転倒の被害に遭うのが、果たして本当にこの高齢者の方たちや障害者の方たちだけなのかというところを考えていかないといけないのかなと私としては思っていて、結構同じように高齢者の方たちに、この家具転倒防止の対策を取りますという自治体は多いのですけれども、一方でその根拠となるところで、転倒の被害者が高齢者などに限られるのかというような。","respondent":"樫村高齢者地域支援課長","answer":"そういったため、福祉部のほうにおいても、現在個別避難計画の作成を進めておりまして、要配慮者への支援が行き届くよう、日頃から準備を進めているものというように理解をしています。","id":"exchange-136"},{"speaker":"松本委員","kind":"質問","question":"そうなのです。消費者庁なども、乳幼児の家具転倒気をつけてくださいねというような話をされています。そのように考えると、先ほど高齢者地域支援課ではあるけれども、障害をお持ちの方たちも広げているというふうに考えると、これは誰が傷つきやすいかということを考えると、子どもたちも支援の対象に含めていくべきではないかと思うのですが、いかがでしょうか。","respondent":"樫村高齢者地域支援課長","answer":"この家具転倒防止器具取付助成を実施していたところですが、実績がほとんどないことから令和５年度末に廃止した経過があります。そういったことも踏まえまして、対象者の拡大につきましては、関係課とも検討しながら検討してまいりたいと考えています。","id":"exchange-137"},{"speaker":"松本委員","kind":"質問・要望","question":"過去実績がなかったというところなので、それはそれで断念というか、なかったということは分かりました。これはあくまで要望としてお伝えいたします。ですから、これは、体験格差はすごく大きな課題だと思うのですが、ただ今回の体験格差改善事業なのですけれども、対象はひとり親に限定されているというところはやはり少し考えないといけないかなと思っています。ここの点についてご見解を伺います。","respondent":"飛田子育て応援課長","answer":"例えば育児や家事、食事の準備などは、全て責任が１人で負わなくてはならないということがあります。何かあったときの相談相手もなかなかいないというところで、そのようなところで様々な課題に直面していても頑張って子育てを応援したいというところで、このようにしました。","id":"exchange-138"},{"speaker":"藤原委員","kind":"質問・要望","question":"２８８ページ、生活保護費、伺いますが、今も対面でお客様といろいろなお話聞いていると思うのですけれども、対面での今の生活福祉課の状況、どうなっているか、正直に話してください。お客様は。つまり、任意後見人になったから安心ではなくて、任意後見人というものは、きちんとした後見人になれるのは、裁判所からきちんとあなたが後見人ですよとしなくてはならないわけではないですか。任意後見人が。","respondent":"豊嶋生活福祉課長、東野福祉計画課長、樫村高齢者地域支援課長","answer":"とはいえ、職員の身の安全も考えながら、何かあったときには複数で対応するようにしておりますが、保護を受給されている方も、多くの方は感謝をして。こちらにつきましては、委員からご案内があったように、家庭裁判所登記をされた、東京法務局に登記をされたことによりまして。こちらの事業の効果と目的としましては、こういった趣味などを活かしていただいて、それを各クラブの方、地域の方と会話にしていただいて、社会参加。","id":"exchange-139"},{"speaker":"藤原委員","kind":"質問・要望","question":"でも対面なのです。全然ＡＩもＤＸも進んでいないではないですか。対面で。私も実は何回か見ました。もう早くＡＩ、ＤＸしていただきたいと思っているのですけれども、どうか職員の方が心折れないように、これからも課長、一生懸命やっていってください。つまり何が言いたいかというと、この花の効果というものは、安否確認もあるかもしれないけれども、お花の効果というものがすばらしいと私は思うのです。","respondent":"樫村高齢者地域支援課長、東野福祉計画課長","answer":"花の効果ですけれども、委員ご指摘のとおり、花が当然きれいなのはきれいで、皆さん見て気持ちよくなっていただくというところもあるのですが、それと併せて、そういった平和の花壇にも使っていただいているように、そういった平和の。任意後見人の制度についてもう少し説明をしたいと思います。任意後見契約をした段階で、任意後見人としての候補者という形で選ばれます。","id":"exchange-140"},{"speaker":"藤原委員","kind":"質問・要望","question":"品川区は元気高齢者がほとんどなのです。実を言うと。ほとんど元気高齢者なのです。雪の中。これどのようなことですか。だって、きちんと求めているわけです。それなのに訪問介護、それで結果出ているではないですか、訪問介護の事業者は減っていく。高齢者福祉課長、私に言われたってと課長は言うかもしれないけれども、介護保険得意の答弁、介護保険制度ですからと。高齢者福祉課長、その辺いかがですか。","respondent":"菅野高齢者福祉課長","answer":"訪問介護は本当に在宅介護の要ということで、すごく大事な事業だということは重々認識しております。","id":"exchange-141"},{"speaker":"藤原委員","kind":"質問・要望","question":"介護は、よく私が言う報酬だけではなくて、ほかの魅力、魅力を発信するのだとよく答弁でお話しするではないですか。どう考えたって年収低いのだから。だからそこをしっかり押さえていっていただきたいのです。１,０００万円以上です。なぜ言うか。それまでの答弁は、区長、副区長がいらっしゃる前は、全部介護保険制度だから駄目ですと言われていたのですから。やはり求めていくべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-142"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですから、今回のこの助成額の倍加は大変よかったなと考えています。それで令和７年度の財調の新規算定に、この補聴器の購入費助成が入ったと思うのですけれども、これによって区の負担は減るということでいいのか伺いたいということと、あと、この直近数年間の利用実績も伺いたいと思います。","respondent":"樫村高齢者地域支援課長","answer":"私から、補聴器の購入実績、この制度の利用実績についてお答えをいたします。昨年度から、令和５年度から開始をしたところでございまして、令和５年度は７月からの開始だったのですけれども、利用実績としては１３０名の方にご利用をいただいたところです。","id":"exchange-143"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですから、これは東京都の補聴器購入費への助成の上限が上がったからということでいいのか伺いたいということと、品川区もさらにこの増額ができるという、他区もこれだけ上げているという状況、そして、財調算定これからだということですけれども、項目に算定されているというところでは、区の負担が今までよりは少なくて済むという状況になってくると思うので。","respondent":"樫村高齢者地域支援課長","answer":"これまで、こういった社会情勢や利用者の声を踏まえながら、迅速かつ的確に対応できたと考えていますので、令和７年度については今申し上げたような内容で実施をしていく考えです。","id":"exchange-144"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"単独補助になったというところで。ですから、それをちょっと確認させていただきたいということと、それを使って他区では、港区含めた３区が増額されているというところでは、品川区もできると思うのですけれども、それで今回倍加したばかりというところですが、結構この補聴器というものが、中程度のものでも１０万円を超えるという状況です。","respondent":"樫村高齢者地域支援課長","answer":"それから今後の展開ですけれども、先ほど申し上げたとおりの経過がありますので、来年度につきましては一度この形でやらせていただきたいと考えています。","id":"exchange-145"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今後もあるというところでは、ぜひ広げていくためにも、増額を私たちとしては求めていきたいなと考えています。それで続いて、小規模デイサービスの送迎のガソリン代について伺いたいと思っているのです。小規模デイサービスは市区町村の認可です。指定権限があるところが。小規模ではないデイサービスは都の認可だと思います。ですから、これガソリン代が大きな負担になっているという声をいただいています。","respondent":"菅野高齢者福祉課長","answer":"今委員ご指摘の地域密着のデイサービスにつきましては、区の指定権限の下で行われているサービスということで、東京都の指定ではないということで、東京都の補助金からの対象外ということになっているのかなというようには認識しております。","id":"exchange-146"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この小規模デイサービスのガソリン代、月に二、三万円かかるのです。そして、この区内には２７か所あります。小規模でも、やはり小規模だからこそ経営が大変だというところがあります。通所も在宅も、介護現場は本当に大変ですので、ぜひ支援をしていただきたい、検討をお願いしたいと思いますけれども、いかがでしょうか。","respondent":"菅野高齢者福祉課長","answer":"他団体や他区の動向や事業者の声などを聴きながら、前向きに検討していきたいと思います。","id":"exchange-147"},{"speaker":"大倉委員","kind":"質問・要望","question":"よろしくお願いします。保育園、幼稚園の数全体から見てどのくらいあるのか。そうですね。代表質問でもちょっと伺ったのですが、事前予約進めていきますということだったので、実際どのように行われていくのかお知らせください。５月から３校のところと、秋から全校展開というところで、予算がどのようになっているでしょうかというところを教えてください。","respondent":"中島保育施設運営課長、藤村子ども育成課長、佐藤保育事業担当課長","answer":"コロナ前が９０園超えていますので、まだコロナ前までは戻ってきていないかなですが、今後も積極的に進めてまいりたいと考えています。予算のほうがどうなっているのかというところですが、９月から朝食支援というものを実施する見込みで、２０人分の予算を今取って、３７校という形ですが。ベビーセンサーに対する補助ですけれども、こちら新規開設園に向けた補助でございまして、令和７年度は新規の開設園がございませんので。","id":"exchange-148"},{"speaker":"大倉委員","kind":"質問・要望","question":"警察との連携等あるかと思いますが、その辺についてはどのようにお考えでしょうかということと、あと、パン、おにぎりを検討しているという、先ほどのほかの委員の方のご答弁であって、どのように提供していくのかちょっと分からなかったので教えていただければと思います。ベビーセンサーに関しては、国のほうで出ているということだと思っていて、新規開設園がないからということでありました。","respondent":"中島保育施設運営課長、藤村子ども育成課長、佐藤保育事業担当課長","answer":"保幼小ジョイント事業のさらなる受入れ拡大の点につきましてですが、担当のほうが学校ともいろいろ意見交換している中では。研修の方法につきましては、委託業者、まず今回３校試行実施という形になりますので、３校試行実施する対象の業者の係の方というか。ベビーセンサーについてですが、これは国の補助制度を利用しまして、区のほうで実施しているものでございまして。","id":"exchange-149"},{"speaker":"大倉委員","kind":"質問・要望","question":"保幼小のジョイント事業、ぜひいろいろと連携をしながら、さらに進むように情報共有して、工夫をして進めていっていただきたいと思います。次に朝食のほう、分かりました。いろいろと教えていただいてありがとうあります。アレルギーなど、その辺は基本的にはすまいるスクールの仕出し弁当と同じで、保護者の責任でしっかりと対応するということでいいのかなというように伺いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-150"},{"speaker":"あくつ委員","kind":"質問・要望","question":"この間ずっと求めてきたので、かなり具体的になったことは大変ありがたいなと思っているのですが、システム改修には予算が必要なのですけれども、新年度予算には計上していなかったと理解をしております。これは流用でスピード感を持って行っていただけるということなのか、それとも補正予算を組むということなのか、お答えください。","respondent":"芝野保育入園調整課長","answer":"年度途中にシステム改修終了すると思いますので、それ以降はシステムのほうで対応させていただきたいと考えております。","id":"exchange-151"},{"speaker":"あくつ委員","kind":"質問・要望","question":"平成２９年第１回定例会代表質問におきまして、公明党から高校生の奨学金制度の見直しを求め、当時の子ども未来部長から、奨学金制度の見直しを検討していくという答弁があり、実現をいたしました。ここで伺いたいのですけれども、返済免除型奨学金制度がスタートをして、これは何名が返済免除にならなかったのかというところ、返済をされている方がいらっしゃるのかということを確認させてください。","respondent":"飛田子育て応援課長","answer":"現在の高校生の返済免除型の支援ですが、今まで返済免除にならなかった人数ですけれども、一部免除の方は２名いましたが、全く免除にならなかったという方はいらっしゃっておりません。","id":"exchange-152"},{"speaker":"あくつ委員","kind":"質問・要望","question":"学力試験等は課さず、作文等の提出書類を基に面接を実施し、家計状況や本人の意欲などを確認して、奨学金運営委員会で審議をして最終決定をすると。先ほど、幸いにも高校生の在学応援資金において、ほぼ全員が返済免除になっているということを確認いたしました。大学と高校の奨学金との整合性を図るためにも、貸付けから給付型への転換を図っていただきたいと思いますが、いかがでしょうか。","respondent":"飛田子育て応援課長","answer":"高校生の在学資金のことですが、現在大学生の給付型奨学金を創設したことを前提としまして、またベーシックサービスの考え方も踏まえながら、改めて制度の在り方の検討をしていきたいと考えております。","id":"exchange-153"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ちょっと時間がないのでまとめて聞いてしまいます。２点目の要望は、周知というものを求めてまいりました。申請を締め切った後に気づいたというお声もあったことから、子ども未来部から教育委員会と学校へしっかりとお伝えをした上で、子どもたち、ご家庭へ、誰１人取り残さずお知らせをしていただきたいと求めましたが、今回この体制についてどのように取られているのか確認させてください。","respondent":"飛田子育て応援課長","answer":"お米の仕入先についてですが、基本的には一般入札となるとは認識しておりますけれども、約３３ｔのお米を２kgの袋詰めにするということで、１つの銘柄で一括購入することはなかなか困難ではないかなと考えておりますので、また昨年同様に。","id":"exchange-154"},{"speaker":"あくつ委員","kind":"提案","question":"４つ目は、数か所に移動できる電源として、そうした電気自動車をプラグインハイブリッド車として避難所へ派遣して、その場所については医療的ケアの必要な当事者、ご家庭へ、マップと併せて周知をしてくださいということで、障害者支援課長からは、川崎市の事業について調査をして、委員ご提案のものについて検討していく、このようなご答弁をいただきましたが、その後の検討状況をお伺いします。","respondent":"松山障害者支援課長","answer":"委員からご提案を受けまして、川崎市の件を調査いたしまして、防災課と自動車会社が協定を結んで、今進めております。その活用を予定しています。充電できる場所、訓練、マップにつきましても、引き続き防災課と連携して検討してまいります。","id":"exchange-155"},{"speaker":"あくつ委員","kind":"質問","question":"たしかあのときもお示ししたのですけれども、不動前にある日産の販売店、これが東京の中で一番大きいということで、こことは既に協定を結んでいたはずなのですが、また新たに協定を結ぶということ、この、いわゆる医療的ケア児の人工呼吸器のバッテリー充電ということに関しての新たな協定を結ぶと、このような認識でよろしいのでしょうか。","respondent":"松山障害者支援課長","answer":"防災課と自動車会社が協定を結ぶということで、実際に訪問をさせていただいて、この電気自動車からの電源確保についての、いわゆる関わる協定について今進めているところです。","id":"exchange-156"},{"speaker":"あくつ委員","kind":"質問・要望","question":"分かりました。所管が防災課ということで、昨年課長のほうから検討するというご答弁をいただきましたが、これはワンクッション置いて防災課がしっかりやっていただくということ、でもこれはやはり地域の、本来前回の答弁だと、医療的ケア児の在宅用人工呼吸器のバッテリーを使用している方が、区が把握しているだけで２５名ということで、この事業を利用して支給件数は９件というご答弁をいただいております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-157"},{"speaker":"まつざわ委員","kind":"質問","question":"私からは、２５９ページ、児童センター運営費、時間があれば、２５３ページの認知症高齢者支援事業についてお聞きします。品川区には児童センター、全部で２５か所です。子どもたちがより快適に利用できる環境を整備していく、そのような考えが必要だと思いますが、まずご見解をお聞かせください。","respondent":"藤村子ども育成課長","answer":"部活があるなど、様々な背景はあると思うのですが、中・高生の居場所としても認識してもらえるように、今年度予算でダーツの事業というものを計上させていただいているのですけれども、そういったもので利用したくなるような機能を充実させたいと思います。","id":"exchange-158"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"特にダーツ、あれは何か、私も聞いたのですけれども、あれがすごく好評で、中・高生が大分、何というのですか、活発に児童センターに来ることになったということは確認しております。でも、何というのですか、館長というものは、それこそ思いが強い方が非常に多いので、やみくもに指定管理にしていくということもいろいろ考えものですので、その辺はしっかりと話し合っていただきたいと考えています。","respondent":"藤村子ども育成課長","answer":"今後の運営の形態としましては、大原が今回指定管理化するので、どういった区民のお声があるのかとか、館長のほうでどういった意向があるのかというところを聞きつつ、どういった方法がよいかということは今後検討してまいりたいと考えています。","id":"exchange-159"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"例えば、近くでいうと、ゆたか児童センター、南ゆたか児童センター、近いところで同じような事業をやっていたら、例えばそのようなものはスクラップ・アンド・ビルドして、そのようにうまく、何というのですか、事業を館同士同じものをやる、同じものも大事かもしれないですけれども、同じものをやるよりも、そういったところにしっかりと事業を精査しながら、今度は新しい事業につなげるほうが。","respondent":"藤村子ども育成課長","answer":"児童センターのほう、新規事業の実施や、今回お米の配布というところで、業務量が増えている部分は確かにあるのですが、今回予算で上げさせていただいている入退館管理システムなど、そういったものを導入することで。","id":"exchange-160"},{"speaker":"まつざわ委員","kind":"意見","question":"新規事業で今いろいろなお話を聞いた中で、私ずっと児童センターの館長と話をしているのですけれども、子ども食堂ありますよね。これ子ども食堂の根幹の中に、全ての子どもに安心して食事を取れる場を提供し、地域全体で子どもを支える、これが子ども食堂の根幹というお話がありますけれども、児童センターというものが、まさしくここに当てはまると思いますが、ご見解を聞かせてください。","respondent":"藤村子ども育成課長","answer":"区では社会全体で子育てを支えるという観点から、様々事業を実施していますので、各課の状況や地域の方の動向を踏まえてですけれども、開催については順次検討してまいりたいと思います。","id":"exchange-161"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"人が多く集まる児童センターの防犯と安全対策の部分で、最近も、何というのですか、品川区のあれも、すぐに不審者情報というものがいっぱい鳴ってくる中で、先ほど課長が言っていました。あれも大分おっくうだなと思いながら、私もずっと大分書いていましたけれども、そのような中、先ほど新規予算の中で入退館管理システムですか、というものが、これも補正予算でも見つけたのです。","respondent":"藤村子ども育成課長","answer":"児童センターの安全対策等というところですが、まず入館の際には、先ほど申し上げたとおりお名前書いていただいているですとか、ほとんどの館に防犯カメラのほう設置しておりますので、そういった面で安全管理もできているかなというところです。","id":"exchange-162"},{"speaker":"まつざわ委員","kind":"質問","question":"カードを忘れても大丈夫だと思うのですけれども、児童センターは中学生、高校生も利用するとなると、例えばそのＱＲコード自体が面倒くさいなとかと、持ってこないことも随分ケースがあるのかなと思っていますので、そのようなところは大丈夫なのかということと、あと保護者も一々メールが来てしんどいなという方もいらっしゃると思うので、その辺の対応がどうなのかと教えてほしいです。","respondent":"藤村子ども育成課長","answer":"南品川児童センターについては、こちら子ども・若者活動拠点として、仮称としてですが、改築を検討しておるところですので、今年度基本設計をしまして、来年度実施設計なのですけれども、子ども・若者まんなか拠点として。","id":"exchange-163"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/619855?Template=document&Id=7007#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":131415,"voices":390}}]);
